(window.GIM_TS=window.GIM_TS||{})["Gittin.6"]={"from":144,"a":[["\u0003ומטמא לה\u0004 אם כהן הוא, \u0003כללו של דבר: הרי היא\u0004 באותם ימים \u0003כאשתו לכל דבר\u0004 — \u0003אלא שאינה צריכה הימנו גט שני\u0004 לכשימות, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' מאיר אומר:\u0004 הגדרת \u0003בעילתה\u0004 על ידי אחר, אם נחשבת כבעילת אשת איש, \u0003תלויה\u0004 בשאלה אם ימות בעלה מחולי זה, שאם כן — נמצא שהיה זה גט וחלו הגירושין משעת נתינה, ולא היתה בכך משום עבירה כלל. \u0003ר' יוסי אומר:\u0004 דין \u0003בעילתה\u0004 הוא ספק. \u0003וחכמים אומרים: מגורשת ואינה מגורשת, ובלבד שימות\u0004 מאותו חולי.","ומבררים: \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מהו ההבדל\u0005]\u0006 \u0003בין\u0004 דברי \u0003ר' מאיר ל\u0004דברי ר' יוסי שלכאורה הם אומרים אותו דבר, שהדבר אינו ברור? \u0003אמר\u0004","\u0003ר' יוחנן:\u0004 הבאת \u0003אשם תלוי\u0004 אם נבעלה על ידי איש אחר כל עוד לא מת בעלה מאותו חולי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל \u0005למעשה; ש\u0006\u0003ל\u0004דעת \u0003ר' מאיר לא מייתי\u0004 \u0005[מביא]\u0006 הבועל \u0003אשם תלוי,\u0004 מפני שבעילתה תלויה, אבל הדבר עתיד להתברר בוודאות לכשימות הבעל או לכשיעמוד מחוליו, שאם יתחייב הבועל — מביא חטאת, ואם לאו — פטור מכל קרבן. \u0003ול\u0004דעת \u0003ר' יוסי\u0004 מעמדה באותם הימים הוא כולו ספק, שאף אם ימות מאותו חולי, עדיין מסופק ר' יוסי מאיזו שעה חל הגט, ולכן הבועל את האשה \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003אשם תלוי.\u0004","שנינו עוד, \u0003וחכמים אומרים: מגורשת ואינה מגורשת.\u0004 ותוהים: שיטת \u0003חכמים היינו\u0004 \u0005[הרי זו]\u0006 שיטת \u0003ר' יוסי!\u0004 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי פסק ההלכה שמסר \u0003ר' זירא,\u0004 ש\u0003אמר ר' זירא אמר רבה בר ירמיה אמר שמואל: כל מקום שאמרו חכמים \"מגורשת ואינה מגורשת\"\u0004 — \u0003בעלה חייב במזונותיה,\u0004 שלדעת ר' יוסי כיון שבאותם ימים שבין נתינת הגט למיתת הבעל היא בספק — אין בעלה חייב במזונותיה בימים אלה. ולדעת חכמים היא בגדר \"מגורשת ואינה מגורשת\" וחייב בעלה בימים אלה במזונותיה.","האומר לאשה \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\"\u0004 — \u0003הרי זו מגורשת, ותתן\u0004 מאתיים זוז כדי לקיים את התנאי שבגט.","אם אמר לה \u0003\"על מנת שתתני לי\u0004 כסף \u0003מיכן\u0004 (מעכשיו) \u0003ועד שלשים יום\",\u0004 \u0003אם נתנה לו בתוך שלשים יום\u0004 — \u0003מגורשת, ואם לאו\u0004 — \u0003אינה מגורשת.\u0004","\u0003אמר רבן שמעון בן גמליאל: מעשה\u0004 היה \u0003ב\u0004עיר \u0003צידן, באחד שאמר לאשתו \"הרי זה גיטך על מנת שתתני לי איצטליתי\"\u0004 (הטלית שלי) \u0003ואבדה איצטליתו,\u0004 ולא יכלה לתיתה לבעלה, \u0003ואמרו חכמים: תתן לו את דמיה\u0004 (שוויה) של אותה איצטלה, ויתקיים בכך התנאי ותהיה מגורשת.","שנינו במשנה: \"הרי זו מגורשת ותתן\" את הכסף. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ותתן\"?\u0004 — \u0003רב הונא אמר:\u0004 הרי היא מגורשת מיד עם מסירת הגט, \u0003והיא תתן\u0004 כדי לקיים את התנאי, ואז יחולו הגירושין למפרע מזמן נתינת הגט. \u0003רב יהודה אמר: לכשתתן\u0004 הרי היא מגורשת.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 במקרה \u0003שנתקרע הגט או שאבד\u0004 לאחר שקיבלה את הגט ולפני שנתנה את הכסף, \u0003רב הונא אמר: והיא תתן,\u0004 כוונתו שהגט חל מיד כשקיבלתו, ואם כן אף אם נקרע לאחר מכן \u0003אינה צריכה הימנו גט שני, רב יהודה אמר לכשתתן\u0004 — כוונתו ש\u0003צריכה הימנו גט שני,\u0004 שהרי לדעתו כל עוד לא נתנה את הכסף אינו גט, ולכן גם אם היה רצונה לתת, כיון שבפועל לא נתנה את הכסף לפני שנקרע הגט — צריכה לקבל ממנו גט נוסף.","ומעירים: \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]\u0006 \u0003גבי קידושין\u0004 שחלקו גם כן רב הונא ורב יהודה \u0003כי האי גוונא\u0004 \u0005[כגון זה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי על מנת שאתן לך מאתים זוז\"\u0004 — \u0003הרי היא מקודשת, ויתן, ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו בשאלה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ויתן\"? רב הונא אמר: והוא יתן,\u0004 כלומר, הרי היא מקודשת מיד, והוא חייב לתת מה שהבטיח, \u0003רב יהודה אמר: לכשיתן.\u0004","ושאלנו \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם ]\u0006 והסברנו: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 כגון \u0003שפשטה\u0004 (הושיטה) \u0003ידה וקיבלה קידושין מ\u0004אדם \u0003אחר\u0004 לפני שנתן לה זה הראשון את הכסף שאמר. \u0003רב הונא אמר: והוא יתן,\u0004 כוונתו \u0003תנאה בעלמא\u0004 \u0005[תנאי בלבד]\u0006 \u0003הוא\u0004 שקיבל על עצמו, \u0003מקיים\u0004 את \u0003תנאיה\u0004 \u0005[תנאו]\u0006 \u0003ואזיל\u0004 \u0005[והולך]\u0006 אבל היא מקודשת לו מיד, ולכן קידושיה מאחר אינם תופסים. ואילו \u0003רב יהודה אמר לכשיתן,\u0004 כוונתו \u0003לכי יהיב\u0004 \u0005[כאשר יתן]\u0006 \u0003לה הוא דהוו\u0004 \u0005[שיהיו\u0006 שיחולו\u0005]\u0006 \u0003קידושין, השתא לא הוו\u0004 \u0005[עכשיו אינם]\u0006 \u0003קידושין,\u0004 ולכן לפי שעה תופסים קידושיה מאחר.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 להיאמר מחלוקת זו בשני המקרים: \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 את שיטותיהם רק לגבי \u0003קידושין,\u0004 היינו אומרים: דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב הונא: והוא יתן, משום דלקרובה קאתי\u0004 \u0005[שלקרב אותה הוא בא]\u0006 ומרצון הוא עושה כן, ולכן יש להניח שכוונתו היתה לקידושין מיד, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003גירושין דלרחוקה קאתי\u0004 \u0005[שלרחק אותה הוא בא]\u0006 ויש להניח שכבד עליו הדבר, שתולה הוא את הגירושין בתנאי על מנת להשהות את הדבר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב יהודה\u0004 שכל עוד לא התקיים תנאו אינם גירושין.","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גירושין\u0004 היינו אומרים: \u0003בהא\u0004 \u0005[בזו]\u0006 \u0003קאמר רב הונא והיא תתן, משום\u0004 שהוא \u0003לא כסיף למיתבעה\u0004 \u0005[מתבייש לתבוע ממנה]\u0006 לאחר מכן את הכסף כקיום התנאי לגירושין, וגמר בליבו לגרשה מיד. \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003קידושין, דכסיפא למיתבעיה\u0004 \u0005[ש\u0006היא \u0005מתביישת לתבוע ממנו]\u0006 את הכסף שאמר, ואולי אינה סומכת בדעתה להתקדש עד שתקבל את הכסף, ועל דעת כן קידשה — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב יהודה\u0004 שדווקא כשיתן יהיו אלה קידושין, לכן נאמרה דעתו בשני המקרים.","ומסבירים גם מפני מה צריכים דברי רב יהודה להיאמר בשני המקרים: \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קידושין,\u0004 היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב יהודה לכשיתן, משום דכסיפא למיתבעיה\u0004 \u0005[משום ש\u0006היא \u0005מתביישת לתבוע ממנו]\u0006 אם לא נתן לה, ולכן אינה סומכת על קיום התנאי עד שיבצענו בפועל, ועל דעת כן קידשה, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003גירושין\u0004 ש\u0003לא כסיף למיתבעה\u0004 \u0005[מתבייש לתבוע ממנה]\u0006 — \u0003אימא מודה ליה\u0004 \u0005[אמור,\u0006 ש\u0005מודה לו]\u0006 \u0003לרב הונא\u0004 שחל הגט מיד.","ומצד שני, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גירושין\u0004 בלבד, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב יהודה לכשתתן, משום דלרחוקה קאתי\u0004 \u0005[שלרחק אותה הוא בא],\u0006 \u0003אבל גבי קידושין דלקרובה קאתי\u0004 \u0005[שלקרב אותה הוא בא]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב הונא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת להיאמר בשני המקרים.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: האומר לאשה \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\", אף על פי שנקרע הגט או שנאבד\u0004 — \u0003מגורשת, ולאחר לא תנשא עד שתתן\u0004 את הכסף.","\u0003ועוד תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשתו \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\" ומת\u0004 הבעל בלא בנים, אם כבר \u0003נתנה\u0004 את הכסף — \u0003אינה זקוקה ליבם,\u0004 לפי שכבר נתגרשה מבעלה בגט שנתן לה. אבל אם \u0003לא נתנה\u0004 — \u0003זקוקה ליבם,\u0004 לפי שלא חל הגט, והריהי רק כאלמנה. \u0003רבן שמעון בן גמליאל אומר:\u0004 \u0003נותנת\u0004 את הכסף \u0003ל\u0004\u0003אביו או לאחיו או לאחד מן הקרובים\u0004 היורשים אותו, ועל ידי כך מתקיים התנאי, ופטורה מזיקת יבום.","ומעירים: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 תנא קמא ורבן שמעון בן גמליאל — \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 באמירת \u0003\"\u0004על מנת שתתני \u0003לי\"\u0004 כוונתו לי בלבד — \u0003ולא ליורשי,\u0004 ולכן אינה מקיימת את התנאי כאשר נותנת ליורשיו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 שכוונת \u0003\"לי\"\u0004 — \u0003ואפילו ליורשי, וכולי עלמא מיהא\u0004 \u0005[ולדעת הכל על כל פנים]\u0006 \u0003תנאה הוי\u0004 \u0005[תנאי הוא]\u0006 הדבר הזה, אבל אין ביצועו מעכב את עיקר חלותו של הגט, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדעת \u0003רב יהודה\u0004 שאמר \"לכשתתן\"!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יהודה: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003רבי היא.\u0004 ש\u0003אמר רב הונא אמר רבי: כל האומר \"על מנת\"\u0004 — \u0003כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006 ולפי זה, כל דבר שיש בו תנאי בלשון \"על מנת\" — חל מיד, אף שהתנאי מתקיים רק לאחר זמן. \u0003ופליגי רבנן עליה\u0004 \u0005[ו\u0006אולם \u0005חולקים חכמים עליו],\u0006 \u0003ואנא דאמרי כרבנן\u0004 \u0005[ואני שאני אומר כ\u0006דעת \u0005חכמים]\u0006 אני אומר.","\u0003ואמר ר' זירא: כי הוינן\u0004 \u0005[כאשר היינו]\u0006 \u0003בבבל,\u0004 \u0003אמרינן\u0004 \u0005[היינו אומרים],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא אמר רבי: כל האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב]\u0006 — \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו\u0006 בזה\u0005].\u0006 \u0003כי סליקי\u0004 \u0005[כאשר עליתי]\u0006 לארץ ישראל, \u0003אשכחתיה\u0004 \u0005[מצאתי אותו]\u0006 את \u0003ר' אסי דיתיב וקאמר משמיה\u0004 \u0005[ש\u0006הוא \u0005יושב ואומר משמו]\u0006 של \u0003ר' יוחנן: הכל מודים באומר \"על מנת\"\u0004 ש\u0003כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006 \u0003לא נחלקו\u0004 חכמים על רבי \u0003אלא\u0004 \u0003ב\u0004מקרה של גט שהיה בו תנאי \u0003\"מהיום ולאחר מיתה\".\u0004"],["\u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"\u0004הרי זה גט \u0003מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט,\u0004 אלו \u0003דברי חכמים, רבי אומר: כזה גט,\u0004 כלומר, גט כשר הוא לגמרי. משמע שבזה נחלקו, אבל ב\"על מנת\" הכל מודים שהוא כאומר \"מעכשיו\".","ושואלים: \u0003ול\u0004דעת \u0003רב יהודה\u0004 ש\u0003אמר\u0004 שרבי וחכמים \u0003ב\"על מנת\" פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005חולקים]\u0006 \u0003ב\u0004מקרה המיוחד של \u0003\"מהיום ולאחר מיתה\", ליפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003ב\"על מנת\"!\u0004 ומשיבים: \u0003להודיעך כחו\u0004 של \u0003רבי\u0004 שאינו חושש כלל לאפשרות שהגט אינו גט.","ומקשים: \u0003וליפלגו\u0004 \u0005[ושיחלקו]\u0006 \u0003ב\"על מנת\" ולהודיעך כחן דרבנן\u0004 \u0005[של חכמים]\u0006 שאינם סבורים ש\"על מנת\" כ\"מעכשיו\" נחשב, והרי זה ענין כללי יותר! ומשיבים: \u0003כח דהיתירא\u0004 \u0005[של ההיתר]\u0006 \u0003עדיף ליה\u0004 \u0005[לו]\u0006 להראות עד כמה מתיר רבי, שיש בכך חידוש גדול יותר מדברי חכמים שאינם באים אלא לאסור.","שנינו במשנה: אמר לאשתו שמגרשה \u0003\"על מנת שתתני לי\u0004 מאתים זוז \u0003מכאן ועד שלשים יום\"\u0004 אם נתנה בתוך שלושים יום — הרי זה גט, ואם לאו — אינו גט. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שהכל תלוי אם מילאה את התנאי או לא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003קפידיה\u0004 \u0005[הקפדתו]\u0006 של הבעל שתתן לו תוך זמן קצוב \u0003לאו קפידא\u0004 \u0005[איננה הקפדה]\u0006 של ממש, ואין זה תנאי ממש המחייבה לגמרי, \u0003ו\u0004רק \u0003לזרזה קאתי\u0004 \u0005[הוא בא],\u0006 שרצונו לקבל את הכסף בהקדם, ואולם אם תאחר מעט לא יקפיד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהוא תנאי גמור, ואם לא קיימתו — אין זה גט.","עוד שנינו במשנה, ש\u0003אמר רבן שמעון בן גמליאל: מעשה\u0004 היה \u0003ב\u0004עיר \u0003צידן\u0004 באדם שהתנה שיחול הגט כשתתן לו אשתו את האיצטלית שלו, ואבדה האיצטלית, ואמרו שתתן לו את מחירה ותהא מגורשת. ושואלים: \u0003מאי תנא דקתני\u0004 \u0005[מה שנה\u0006 קודם \u0005ששנה]\u0006 על זה \u0003מעשה?\u0004 שהרי מעשה זה אינו מתייחס לדברים האמורים קודם!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003אם אמר לה \"על מנת שתתני לי איצטליתי\" ואבדה איצטליתו\u0004 — \u0003איצטליתי דוקא קאמר\u0004 \u0005[אמר]\u0006 \u0003לה\u0004 ולא יועיל לתת את דמיה, וכיון שאינה מצויה — אינו גט, זאת דעת חכמים. \u0003רבן שמעון בן גמליאל אומר: תתן לה את דמיה. ואמר רבן שמעון בן גמליאל\u0004 כראיה לדבריו: \u0003מעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בצידן, באחד שאמר לאשתו \"הרי זה גיטך על מנת שתתני לי אצטליתי\" ואבדה אצטליתו, ואמרו חכמים: תתן לו את דמיה.\u0004","על רקע הסבר זה של המשנה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אסי מר'\u0004 \u0003יוחנן:\u0004 האומר לאשה \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\", וחזר ואמר לה \"מחולים לך\", מהו\u0004 הדין?","והוא מפרט את שאלתו: \u0003תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת \u0005חכמים],\u0006 וכן \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 \u0003ל\u0004דעת \u0003רבן שמעון בן גמליאל;\u0004","\u0003תיבעי לרבנן\u0004 \u0005[תישאל ל\u0006שיטת \u0005חכמים]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאינה מגורשת אם לא תמלא את התנאי ותיתן לו את האיצטלית עצמה — \u0003אלא\u0004 משום ש\u0003לא אחלה גבה\u0004 \u0005[מחל לה\u0006 על האיצטלית\u0005],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003הא קאמר\u0004 \u0005[הרי\u0006 \u0003אומר]\u0004 \u0003לה \"מחולים לך\". או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו רבן שמעון בן גמליאל לא קאמר\u0004 \u0005[אינו אומר]\u0006 שיכולה להתגרש אף אם לא קיבל את האיצטלית \u0003אלא\u0004 משום \u0003דקא מפייסה ליה בדמי\u0004 \u0005[שהיא מפייסת אותו בדמים],\u0006 שנחשב התנאי כמקויים, שהרי קיבל את תמורתה. \u0003אבל\u0004 במקרה שמוותר לה ומתבטל התנאי \u0003לגמרי\u0004 — \u0003לא.\u0004 ואם כן, מה הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה: \u0003אינה מגורשת,\u0004 שלא נתקיים התנאי.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במסכת נדרים: \u0003האומר לחבירו \"קונם\u0004 (הרי אני אוסר אותך בנדר) מכל מה \u0003שאתה נהנה לי\u0004 (ממני) \u0003אם אי\u0004 (אין) \u0003אתה נותן לבני\u0004 כמתנה לחתונה \u0003כור אחד של חטין ושתי חביות של יין\", ר' מאיר אומר: אסור\u0004 חבירו בהנאתו משום הקונם \u0003עד שיתן\u0004 אותם דברים, \u0003וחכמים אומרים: אף זה,\u0004 הנודר, \u0003יכול להתיר את נדרו שלא על פי חכם\u0004 שאינו צריך ללכת לחכם להתיר לו את הנדר, \u0003ואומר\u0004 רק: \u0003\"הריני כאילו התקבלתי\"\u0004 (קיבלתי ממך). משמע שאם מוותר לאחר מעשה על מה שתבע, נעשה כאילו קיבל, ואף כאן תיחשב מחילת הבעל כאילו קיבל, ותהא מגורשת!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם לצעורה קא מכוין\u0004 \u0005[שם\u0006 בגט \u0005לצער אותה התכוון]\u0006 \u0003ולא ציערה,\u0004 שהרי רצה ממנה את הכסף כדי לצער אותה, וכשמוחל לה — נמצא שלא התקיימה כוונתו. \u0003הכא\u0004 \u0005[כאן]\u0006 בענין הנדר \u0003משום הרווחה הוא,\u0004 שרצה שלבנו יהיה קצת יותר רווח \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא איצטריך\u0004 \u0005[\u0006היה \u0005צריך],\u0006 ולכן יכול היה לוותר על מה שתבע.","מסופר: \u0003ההוא גברא דאמר ליה לאריסיה\u0004 \u0005[אדם אחד שאמר לו לאריסו]:\u0006 \u0003כולי עלמא דלו תלת דלוותא ואכלי ריבעא\u0004 \u0005[הכל,\u0006 כל האריסים \u0005דולים\u0006 ומשקים \u0005שלוש\u0006 פעמים את השדה, \u0005ואוכלים,\u0006 מקבלים בשכר זה, \u0005רבע]\u0006 מיבול השדה, ואילו \u0003את דלי ארבעה ואכול תילתא\u0004 \u0005[אתה דלה ארבע\u0006 פעמים \u0005ותאכל\u0006 כשכרך \u0005שליש\u0006 מן התבואה\u0005],\u0006 \u0003לסוף אתא מיטרא\u0004 \u0005[בסוף בא גשם]\u0006 כשהיה צריך להשקות בפעם הרביעית, ולא הוצרך לדלות פעם נוספת, ובאה שאלה לפני חכמים אם זכאי האריס בשליש היבול או רק ברבע.","\u0003אמר רב יוסף: הא\u0004 \u0005[הרי]\u0006 \u0003לא דלה\u0004 פעם רביעית ולא נתקיים התנאי, ולא מגיע לו יותר מלאריסים אחרים, ויקבל רק רבע היבול. \u0003רבה אמר: הא\u0004 \u0005[הרי]\u0006 \u0003לא איצטריכא\u0004 \u0005[הצטרך]\u0006 השדה לדלייה זו, שכבר ירד הגשם וזכה האריס בכך, ומגיע לו שליש היבול.","ושואלים: \u0003לימא\u0004 \u0005[\u0006ו\u0005האם לומר],\u0006 ש\u0003רב יוסף\u0004 ש\u0003אמר כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 שעומדים על מילוי התנאי כלשונו, \u0003ורבה\u0004 ש\u0003אמר כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 שהכל תלוי במה שקיבל הבעל לבסוף כתשלום, ואף פה הושקתה שדהו של הבעלים?","ותוהים: \u0003ותיסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שכן הוא? \u0003והא קיימא לן\u0004 \u0005[הרי מוחזק בידינו]\u0006 שבכל מחלוקותיהם \u0003הילכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רבה\u0004 כנגד שיטת רב יוסף, \u0003ובהא\u0004 \u0005[וב\u0006הלכה \u0005זו]\u0006 מוחזק לזו כי \u0003אין הלכה כרבן שמעון בן גמליאל!\u0004 ואם כן תהיה זו סתירה בין הלכה להלכה!","\u0003אלא\u0004 ודאי \u0003לעולם\u0004 המחלוקת הזאת היא מתוך הנחה שהלכה \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים],\u0006 \u0003רב יוסף\u0004 פוסק \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 בפשטות, \u0003ורבה אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 אמרתי אותם, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאינה מגורשת אם לא תחזיר לו את האצטלית עצמה — \u0003אלא\u0004 משום \u0003דלצעורה קא מיכוין\u0004 \u0005[שלצער אותה הוא מתכוון]\u0006 ואם אינה צריכה לתת את האצטלית עצמה — אינה מצטערת, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 השקיית השדה \u0003משום הרווחה הוא, והא\u0004 \u0005[והרי]\u0006 \u0003לא איצטריך\u0004 \u0005[הוצרך]\u0006 לכך.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת ערכין בענין גאולת \"בתי ערי חומה\", שנאמר בתורה שבית שנמכר בתוך עיר חומה ולא נגאל (נפדה, נקנה מחדש) על ידי בעליו בתוך שנים עשר חודש — נשאר הבית לצמיתות לקונה. ומספרים: \u0003בראשונה היה נטמן\u0004 (מתחבא) הקונה במשך כל ה\u0003יום\u0004 האחרון של \u0003שנים עשר חדש, כדי שיהא\u0004 הבית \u0003חלוט לו\u0004 (קנוי לו לחלוטין), שהרי כך לא יכול המוכר לו לפדות ממנו. \u0003התקין הלל הזקן שיהא\u0004 המוכר \u0003חולש\u0004 (מטיל) \u0003את מעותיו\u0004 שאסף לצורך פדיון ביתו \u0003ללשכה\u0004 שבמקדש, \u0003ויהא שובר את הדלת\u0004 של ביתו \u0003ונכנס, ואימתי שירצה הלה,\u0004 הקונה, \u0003יבוא ויטול את מעותיו\u0004 מהלשכה.","\u0003ואמר רבא: מתקנתו של הלל נשמע\u0004 \u0005[נלמד]\u0006 שהאומר לאשתו \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\", ונתנה לו מדעתו\u0004 (מרצונו) — הרי היא \u0003מגורשת,\u0004 אם נתנה לו \u0003על כורחו\u0004 — \u0003אינה מגורשת,\u0004 ומנין הוא מוכיח זאת —","\u0003מדאיצטריך ליה\u0004 \u0005[מ\u0006תוך זה \u0005שהוצרך לו]\u0006 \u0003להלל לתקוני\u0004 \u0005[לתקן]\u0006 תקנה מיוחדת ש\u0003נתינה בעל כורחיה\u0004 \u0005[כורחו]\u0006 של לוקח \u0003דהויא לה\u0004 \u0005[שתהא\u0006 נחשבת\u0005]\u0006 \u0003נ\u0004 \u0003תינה,\u0004"],["\u0003מכלל\u0004 הדברים אתה למד \u0003דבעלמא\u0004 \u0005[שסתם,\u0006 בדרך כלל\u0005]\u0006 \u0003נתינה בעל כרחיה\u0004 \u0005[כורחו]\u0006 \u0003לא הויא\u0004 \u0005[אינה]\u0006 \u0003נתינה,\u0004 שאם לא כן לא היה צריך הלל להתקין תקנה זו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003רב שימי בר אשי: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003כי אצטריך ליה לתקוני\u0004 \u0005[כאשר הוצרך לו ל\u0006הלל \u0005לתקן]\u0006 שיש תוקף לנתינה בעל כרחו, היה זה דווקא כשנותן את הכסף \u0003שלא בפניו, אבל\u0004 כשנותן \u0003בפניו\u0004 — \u0003בין מדעתו בין בעל כרחו הויא\u0004 \u0005[הריהי\u0006 נחשבת\u0005]\u0006 \u0003נתינה,\u0004 ואם כן אין ללמוד מכאן לענין גט כלל, שהרי נותנת לו עצמו את הכסף!","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 זאת באופן הפוך, \u0003אמר רבא: מתקנתו של הלל\u0004 אפשר להסיק כי האומר לאשתו \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\", ונתנה לו\u0004 — \u0003בין מדעתו ובין בעל כרחו הויא\u0004 \u0005[הריהי\u0006 נחשבת\u0005]\u0006 \u0003נתינה,\u0004 \u0003וכי איצטריך ליה\u0004 \u0005[וכאשר הוצרך לו]\u0006 \u0003להלל לתקוני\u0004 \u0005[לתקן]\u0006 תקנה מיוחדת — הרי זה לנתינה \u0003שלא בפניו,\u0004 שהרי הקונה מתחבא מפני המוכר, \u0003אבל\u0004 כאשר נותן המוכר \u0003בפניו\u0004 — \u0003בין מדעתו בין בעל כרחו הויא\u0004 \u0005[הריהי]\u0006 \u0003נתינה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב שימי בר אשי: ודלמא\u0004 \u0005[ושמא]\u0006 יש לפרש כך: \u0003אפילו בפניו נמי\u0004 \u0005[גם כן]\u0006 דווקא נתינה \u0003מדעתו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הריהי נתינה, אבל נתינה \u0003על כרחו לא\u0004 נחשבת נתינה, \u0003והלל מאי דאיצטריך ליה תקין\u0004 \u0005[מה שהוצרך לו תיקן]\u0006 דווקא במקרה המסויים של נתינה שלא בפניו, ואין ללמוד מכאן דין כללי לגבי נתינה אחרת בעל כורחו.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתינו\u0004 — \u0003הלכה כמותו,\u0004 אף שדעתו מובאת כדעת יחיד, \u0003חוץ\u0004 \u0003מ\u0004שלושה מקרים: בדין \u0003ערב\u0004 שאם התנה המלווה שיוכל לפרוע את חובו ממי שירצה — יוכל להיפרע מנכסי הערב תחילה, למרות שיש נכסים ללווה, שלא כדברי רבן שמעון בן גמליאל, \u0003ו\u0004המעשה שמסופר כאן שקרה ב\u0003צידן,\u0004","\u0003וראיה אחרונה,\u0004 שאם מביא אדם ראיה לבית דין אחרי שהודה שאין לו ראיות — אין סומכים על ראיה זו, אף שלדעת רבן שמעון בן גמליאל סומכים עליה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשתו \u0003\"הרי זה גיטיך והנייר שלי\"\u0004 — \u0003אינה מגורשת,\u0004 שהרי נמצא שלא קיים את האמור \"ונתן בידה\" — שהרי לא נתן לה דבר ממשי. אבל אם אמר לה \u0003\"על מנת שתחזירי לי את הנייר\"\u0004 — \u0003מגורשת.\u0004","ותוהים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה הראש ומה שונה הסוף]?\u0006 הרי לכאורה אותו דבר הוא, שאינו נותן לה את הנייר! \u0003אמר רב חסדא: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי]?\u0006 — כשיטת \u0003רבן שמעון בן גמליאל היא,\u0004 ש\u0003אמר\u0004 בענין איצטליתו — שיכולה היא ש\u0003תתן לו את דמיה\u0004 ואינה צריכה לתת דוקא את גוף הדבר כדי לקיים את תנאו, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 \u0003אפשר דמפייסה ליה בדמי\u0004 \u0005[שתפייס אותו בדמים]\u0006 ולא תיתן לו את הנייר עצמו, אלא רק את דמי הנייר של הגט, ולכן נחשב הדבר שקיבלה את הנייר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר רבן שמעון בן גמליאל\u0004 שתועיל נתינת כסף במקום החפץ עצמו — דווקא \u0003היכא דליתיה בעיניה\u0004 \u0005[במקום,\u0006 במקרה \u0005ש\u0006החפץ \u0005אינו בעינו],\u0006 אבל \u0003היכא דאיתיה בעיניה\u0004 \u0005[במקום ש\u0006הוא \u0005ישנו בעינו]\u0006 כמו הגט כאן, \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שנתינת דמים תועיל?","\u0003אלא אמר אביי: הא מני\u0004 \u0005[\u0006ברייתא זו כשיטת \u0005מי]?\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 בכל תנאי שיהא זה \u0003תנאי כפול,\u0004 שיפרש בהתנאתו גם מה יקרה כאשר יתקיים התנאי וגם מה יקרה כאשר לא יתקיים התנאי, \u0003והכא הא\u0004 \u0005[וכאן הרי]\u0006 \u0003לא כפליה לתנאיה\u0004 \u0005[כפל לתנאו],\u0006 שאמר רק \"הרי זה גיטך על מנת שתחזירי לי את הנייר\", ולא פירש שאם לא תחזיר לא יהא זה גט. ולכן אין לו תוקף של תנאי מחייב, ומשום כך הריהי מגורשת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 מדבריך עולה כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003לא כפליה לתנאיה\u0004 \u0005[כפל לתנאו],\u0006 \u0003הא כפליה לתנאיה\u0004 \u0005[הרי אם\u0006 היה \u0005כופל לתנאו]\u0006 \u0003לא הוי גיטא\u0004 \u0005[היה\u0006 זה \u0005גט].\u0006 ואולם, \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל תנאי\u0004 \u0005[התנאים]\u0006 \u0003מהיכא גמרינן להו\u0004 \u0005[מהיכן אנחנו לומדים אותם]\u0006 את דיניהם? — \u0003מתנאי בני גד ובני ראובן,\u0004 שהתנה משה איתם שאם יעברו וילחמו עם שאר ישראל — יקבלו את עבר הירדן כנחלה, ואם לא ישלחו חלוצי צבא לא יקבלו את עבר הירדן (במדבר פרק לב),","\u0003מה התם\u0004 \u0005[שם]\u0006 בתנאים שהתנה משה, לשון ה\u0003תנאי קודם למעשה,\u0004 שקודם אמר שצריך שיתקיים התנאי (\"אם יעברו בני גד ובני ראובן\" וכו'. במדבר פרק כט), ואחר כך מפרש מה יהא המעשה כאשר יקויים התנאי (\"ונתתם להם את ארץ הגלעד לאחוזה\". במדבר פרק כט), \u0003אף כל תנאי\u0004 אין לו תוקף אלא כשהוא \u0003קודם למעשה, לאפוקי הכא\u0004 \u0005[להוציא\u0006 את המקרה \u0005כאן]\u0006 ש\u0003מעשה\u0004 נתינת הגט (\"הרי זה גיטך\") \u0003קודם לתנאי\u0004 (\"על מנת שתחזירי לי את הנייר\")!","\u0003אלא אמר רבא:\u0004 אכן, יש לפרש שהטעם שלא חל התנאי והאשה מגורשת, הוא \u0003משום\u0004 ש\u0003מעשה\u0004 נתינת הגט \u0003קודם לתנאי.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אדא בר אהבה:\u0004 לדבריך \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003מעשה קודם לתנאי\u0004 אין התנאי חל, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003תנאי קודם למעשה לא הוי גיטא\u0004 \u0005[היה\u0006 זה \u0005גט],\u0006 ואולם \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל תנאי\u0004 \u0005[התנאים]\u0006 \u0003מהיכא גמרינן להו\u0004 \u0005[מהיכן אנחנו למדים אותם]\u0006 — \u0003מתנאי בני גד ובני ראובן, מה התם\u0004 \u0005[שם]\u0006 \u0003תנאי\u0004 הוא \u0003בדבר אחד\u0004 (שיעברו וילחמו) \u0003ומעשה\u0004 הוא \u0003בדבר אחר\u0004 (שיקבלו את ארץ הגלעד), \u0003אף כל\u0004 התנאים צריכים להיות באותו אופן, \u0003לאפוקי הכא\u0004 \u0005[להוציא\u0006 את המקרה האמור \u0005כאן]\u0006"],["ש\u0003תנאי ומעשה בדבר אחד,\u0004 בנתינת הגט עצמה! \u0003אלא אמר רב אדא בר אהבה:\u0004 הסיבה שאין מתחשבים בתנאי היא \u0003משום\u0004 ש\u0003תנאי ומעשה בדבר אחד,\u0004 ולכן אין התנאי פועל.","\u0003רב אשי אמר: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי]?\u0006 — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר רב הונא אמר רב: כל האומר\u0004 תנאי בלשון \u0003\"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב]\u0006 והגט חל מיד, גם אם תצטרך לאחר מכן להחזיר לו את גוף השטר.","אגב ענין זה של אופן התנאים בגט מסופר: \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003שמואל בגיטא דשכיב מרע\u0004 \u0005[בגט של\u0006 אדם \u0005שנטה למות]\u0006 שיתנה בלשון זו: \u0003\"אם לא מתי\u0004 — \u0003לא יהא גט, ואם מתי\u0004 — \u0003יהא גט\".\u0004","ושואלים על סדר הדברים, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 בסדר ההגיוני: \u0003\"אם מתי\u0004 — \u0003יהא גט, ואם לא מתי\u0004 — \u0003לא יהא גט\"!\u0004 ומשיבים: \u0003לא מקדים איניש פורענותא לנפשיה\u0004 \u0005[אדם פורענות לעצמו]\u0006 ואינו מעמיד את האפשרות של מותו כאפשרות ראשונה.","ושואלים: \u0003ו\u0004עדיין יש לשאול: מדוע התקין שמואל דווקא בנוסח זה? \u0003לימא\u0004 \u0005[יאמר]\u0006 כך: \u0003\"לא יהא גט אם לא מתי,\u0004 יהא גט אם מתי \u0003\"!\u0004 ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בתנאים שיהא \u0003תנאי קודם למעשה\u0004 ואילו בנוסח זה המעשה (\"לא יהא גט\") הוא לפני התנאי (\"אם לא מתי\").","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מכדי כל תנאי מהיכא גמרינן\u0004 \u0005[הרי כל\u0006 כללי \u0005התנאים מהיכן אנו למדים]\u0006 את הלכותיהם? — \u0003מתנאי בני גד ובני ראובן, מה התם\u0004 \u0005[שם]\u0006 \u0003הן קודם ללאו,\u0004 שצריך להקדים את החלק החיובי, מה יהא אם יתקיים התנאי, ואחר כך יאמר את החלק השלילי, מה יהא אם לא יתקיים התנאי. \u0003אף כל\u0004 התנאים צריכים להיות כך, \u0003לאפוקי הכא\u0004 \u0005[להוציא כאן]\u0006 בנוסח שהתקין שמואל ש\u0003לאו קודם להן,\u0004 שהרי השלילה (\"לא יהא גט\") קודמת לחיוב!","\u0003אלא אמר רבא:\u0004 כך צריך לנסח את התנאי בגיטו של שכיב מרע: \u0003\"אם לא מתי\u0004 — \u0003לא יהא גט, אם מתי\u0004 — \u0003יהא גט,\u0004 \u0003אם לא מתי\u0004 — \u0003לא יהא גט\".\u0004","ומסבירים מפני מה אומרים נוסח מורכב זה: בראשונה הוא אומר \u0003\"אם לא מתי לא יהא גט\"\u0004 — כי \u0003לא מקדים איניש פורענותא לנפשיה\u0004 \u0005[אדם פורענות לעצמו],\u0006 ולכן פותח באפשרות שלא ימות, ואחר כך מוסיף תנאי כפול, ובסדר זה: \u0003\"אם מתי\u0004 — \u0003יהא גט אם לא מתי\u0004 — \u0003לא יהא גט\",\u0004 משום ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא \u0003הן קודם ללאו\u0004 בתנאים.","בעל האומר לאשתו \u0003\"הרי זה גיטיך על מנת שתשמשי\u0004 (תשרתי) \u0003את אבא\",\u0004 או \u0003\"על מנת שתניקי את בני\",\u0004 ולא נקב בתנאו כמה זמן תהא מניקתו, ועל כך אמרו חכמים \u0003כמה היא\u0004 צריכה שתהא \u0003מניקתו\u0004 ויתקיים התנאי? — \u0003שתי שנים\u0004 מלידתו, שהוא זמן ההנקה הקבוע. \u0003ר' יהודה אומר:\u0004 זמן יניקה הוא \u0003שמנה עשר חדש\u0004 בלבד. במקרה שהתנה תנאי כזה, \u0003מת הבן או שמת האב\u0004 — \u0003הרי זה גט,\u0004 גם במקרה שלא נתקיים התנאי.","אבל אם אמר לה בתנאו \u0003\"הרי זה גיטיך על מנת שתשמשי את אבא שתי שנים\",\u0004 או \u0003\"על מנת שתניקי את בני שתי שנים\",\u0004 אם \u0003מת הבן\u0004 ולא הניקתו שתי שנים, \u0003או שאמר האב \"אי אפשי\u0004 (אין רצוני) \u0003שתשמשני\",\u0004 אף אם אמר זאת \u0003שלא בהקפדה\u0004 (לא היא הכעיסה אותו ולא היא גרמה לו שיוותר על שימושה) מכל מקום — \u0003אינו גט,\u0004 לפי שלא התקיים התנאי.","\u0003רבן שמעון בן גמליאל אומר: כזה גט,\u0004 כלומר, אין כל בעיה בגט כזה וכשר הוא. \u0003כלל אמר רבן שמעון בן גמליאל: כל עכבה\u0004 (עיכוב) במילוי התנאי \u0003שאינה\u0004 נובעת \u0003הימנה\u0004 (כתוצאה ממנה) — \u0003הרי זה גט.\u0004","על דברי המשנה שמניקתו שתי שנים, שואלים: \u0003ומי בעינן כולי האי\u0004 \u0005[והאם צריך כל כך\u0006 הרבה זמן\u0005]\u0006 שתניק את הבן? \u0003ורמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ששנינו בברייתא: אם \u0003שמשתו\u0004 את האב \u0003יום אחד,\u0004 או \u0003הניקתו\u0004 את הבן \u0003יום אחד\u0004 — \u0003הרי זה גט!\u0004","\u0003אמר רב חסדא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 — כשיטת \u0003רבן שמעון בן גמליאל,\u0004 שנחלקו במשנה לעיל (גיטין עד,א) במי שהתנה ואמר \"הרי זה גיטך על מנת שתחזירי לי את אצטליתי\" ואבדה האצטלית, שלדעת חכמים אין לה דרך לקיים התנאי ולכן אינה יכולה להתגרש בגט זה. ולדעת רבן שמעון בן גמליאל יכולה במקרה כזה להתגרש אם תיתן לו את דמי האצטלית.","ומסביר: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 — כשיטת \u0003רבן שמעון בן גמליאל\u0004 הסבור כי הולכים אחר כוונתו ליהנות מן הדברים שמתנה בהם את הגט, ולכן אם אינה מניקה אותו כל זמן שנצרך לכך — אינו גט. \u0003וברייתא\u0004 כדברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו ואומרים שהולכים אחר דבריו, וכיון שנתקיימו דברי התנאי בדרך כלשהי — יצאה ידי חובתה.","ומקשים: כיצד אפשר לפרש כך? \u0003הא מדסיפא\u0004 \u0005[הרי מ\u0006כיון \u0005שסופה]\u0006 של משנתנו שיטה חולקת של \u0003רבן שמעון בן גמליאל הוי\u0004 \u0005[היא],\u0006 \u0003מכלל\u0004 הדבר אתה למד \u0003דרישא\u0004 \u0005[שראשה]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 כשיטת \u0003רבן שמעון בן גמליאל! אלא\u0004 יש לפרש להיפך את הסתירה שבין המשנה לברייתא: \u0003ברייתא\u0004 — כשיטת \u0003רבן שמעון בן גמליאל היא,\u0004 ש\u0003מיקל בתנאי\u0004 \u0005[בתנאים]\u0006 ואינו עומד על מילואם כלשונם, שהרי לשיטתו במשנה לעיל יכולה לקיים את התנאי גם על ידי מתן דמי האצטלית. ואילו \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 העומדים על מילוי התנאי כלשונו.","\u0003רבא אמר, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במשנה מדובר \u0003בסתם,\u0004 שלא קבע זמן, ולכן קבעו חכמים זמן לדבר, \u0003כאן\u0004 בברייתא מדובר \u0003במפרש\u0004 שתעשה זאת יום אחד.","\u0003רב אשי אמר: כל סתם נמי\u0004 \u0005[גם כן]\u0006 \u0003כמפרש יום אחד דמי\u0004 \u0005[נחשב],\u0006 שכיון שלא קבע זמן, במעשה כלשהו יש כדי לקיים את התנאי.","ומנסים להביא ראיה בענין זה, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה: \u0003כמה היא מניקתו?\u0004 — \u0003שתי שנים, ר' יהודה אומר: שמנה עשר חדש;\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005]\u0006 שבסתם הרי זה זמן ארוך כל צורכו של התינוק, \u0003אלא ל\u0004שיטת \u0003רב אשי, למה לי שתי שנים, למה לי שמנה עשר חדש? ביום אחד סגי\u0004 \u0005[די\u0006 לה\u0005]!\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 כמה היא מניקתו — \u0003יום אחד משתי שנים,\u0004 בתוך שתי שנים אלה של זמן הנקה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 אם הניקתו \u0003לאחר שתי שנים\u0004 — ש\u0003לא\u0004 מתקיים התנאי, או כדעת ר' יהודה \u0003יום אחד משמנה עשר חדש, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003לאחר שמנה עשר חדש\u0004 שלא.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב אשי ממה ששנינו: האומר לאשתו \u0003\"הרי זה גיטיך על מנת שתשמשי את אבא שתי שנים\",\u0004 או שאומר \u0003\"\u0004הרי זה גיטך \u0003על מנת שתניקי את בני שתי שנים\",\u0004 אם \u0003מת הבן, או שאמר האב \"אי אפשי\u0004 (איני רוצה) \u0003שתשמשני\",\u0004 אף \u0003שלא בהקפדה\u0004 (שלא היא גרמה להכעיסו) מכל מקום — \u0003אינו גט;\u0004"],["\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא רישא\u0004 \u0005[ראשה\u0006 של המשנה\u0005]\u0006 מדובר \u0003ב\u0004אופן ש\u0003לא פריש\u0004 \u0005[פירש]\u0006 זמן, שהרי אמר רק \"על מנת שתשמשי\" \u0003סיפא\u0004 \u0005[סופה]\u0006 מדובר באופן \u0003פריש\u0004 \u0005[סופה\u0006 מדובר \u0005שפירש]\u0006 ואמר \"שתי שנים\".","\u0003אלא לרב אשי,\u0004 הסבור שבסתם יוצאת ידי חובה ביום אחד, ולפיכך הוא צריך להסביר את המקרה הראשון במשנתנו, שמדובר כשלא החלה כלל בעשיית התנאי לשמש את אביו או להניק, אם כן \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה ראשה ומה שונה סופה]?\u0006 ומדוע במקרה הראשון מגורשת? ואומרים: אכן, לשיטתו \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר לאשתו \u0003\"הרי זה גיטך על מנת שתשמשי את אבא שתי שנים,\u0004 או שאומר \u0003\"\u0004הרי זה גיטך \u0003על מנת שתניקי את בני שתי שנים\", אף על פי שלא נתקיים התנאי\u0004 — \u0003הרי זה גט, לפי שלא אמר לה\u0004 תנאי כפול, המפרש מה יקרה אם תמלא את התנאי ומה יהא אם לא תמלאנו. שכך היה צריך לומר לה: \u0003\"אם תשמשי\u0004 — יהא זה גט \u0003\",\u0004 \u0003אם לא תשמשי\u0004 — לא יהא גט \u0003\", \"אם תניקי\u0004 — יהא זה גט \u0003\", ואם לא תניקי\u0004 — לא יהא גט \u0003\",\u0004 ואם לא נהג כך התנאי בטל והמעשה עצמו קיים,","אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 אין צורך בתנאי כפול כדי שייחשב לתנאי, ולכן אם \u0003נתקיים התנאי\u0004 — \u0003הרי זה גט, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינו גט. רבן שמעון בן גמליאל אומר: אין לך תנאי בכתובים שאינו כפול.\u0004","וכלפי מי מוסבים דברי רבן שמעון בן גמליאל? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003לר' מאיר קאמר ליה\u0004 \u0005[אמר לו],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003לרבנן קאמר להו\u0004 \u0005[לחכמים אמר להם].\u0006 ומפרשים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003לר' מאיר קאמר ליה\u0004 \u0005[אמר לו],\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]:\u0006 \u0003אין לך תנאי בכתובים שאינו כפול, והוו להו\u0004 \u0005[והרי הם]\u0006 כל אותם תנאים כפולים הכתובים בתורה \u0003שני כתובים הבאין כאחד,\u0004 שמלמדים אותנו ענין אחד, \u0003וכל שני כתובים הבאין כאחד\u0004 — \u0003אין מלמדין\u0004 לדברים אחרים, ולכן אין ללמוד מהם שכך צריך להיות כל תנאי.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003לרבנן קאמר להו, והכי קאמר להו\u0004 \u0005[לחכמים אמר להם, וכך אמר להם]:\u0006 \u0003אין לך תנאי בכתובים שאינו כפול, וגמרינן מינייהו\u0004 \u0005[ואנו למדים מהם]\u0006 שאין תנאי מתקיים אלא אם כן כפלוהו.","\u0003ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003\"הרי זה גיטיך על מנת שתשמשי את אבא שתי שנים\",\u0004 או שאומר \u0003\"\u0004הרי זה גיטך \u0003על מנת שתניקי את בני שתי שנים\",\u0004 אם \u0003מת האב או מת הבן\u0004 — \u0003אינו גט,\u0004 שהרי לא נתקיים התנאי, אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אף על פי שלא נתקיים התנאי\u0004 — \u0003הרי זה גט,\u0004 שכן \u0003יכולה היא שתאמר לו: \"תן לי\u0004 את \u0003אביך ואשמשנו\",\u0004 או \u0003\"תן לי\u0004 את \u0003בנך ואניקנו\".\u0004","על כל פנים \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר,\u0004 שמן הברייתא עולה שתנאי זה קיים, ומבטל את הגט למרות שאינו כפול. \u0003קשיא דרבנן אדרבנן\u0004 \u0005[קשה\u0006 מדברי \u0005חכמים על\u0006 דברי \u0005חכמים]!\u0006","ומשיבים: מדברי \u0003ר' מאיר\u0004 על דברי \u0003ר'\u0004 \u0003מאיר לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כשאמר שאינו תנאי מדובר בזמן ש\u0003לא כפליה לתנאיה\u0004 \u0005[כפל את תנאו],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003בדכפליה לתנאיה\u0004 \u0005[בשכפל את תנאו]\u0006 והתנא בברייתא רק קיצר את הלשון ולא כתב את התנאי הכפול.","\u0003ורבנן אדרבנן לא קשיא\u0004 \u0005[ו\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים לא קשה],\u0006 שיש לומר \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים דהכא\u0004 \u0005[של כאן]?\u0006 — דעת \u0003רבן שמעון בן גמליאל היא,\u0004 ש\u0003אמר: כל עכבה\u0004 (עיכוב, חוסר אפשרות למלא תנאו) \u0003שאינה הימנה\u0004 (ממנה), שלא באה מצידה — \u0003הרי זה גט.\u0004","ועוד בעניני תנאים בגט, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אמר לה בפני שנים: \"הרי זה גיטך על מנת שתשמשי את אבא שתי שנים\",\u0004 \u0003וחזר ואמר לה בפני שנים\u0004 אחרים: \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\"\u0004 — בכך \u0003לא ביטל דברי\u0004 התנאי \u0003האחרון את\u0004 התנאי \u0003הראשון,\u0004 אלא נתן לה אפשרות, שאם תמלא תנאי אחד מהם יהא זה גט, ולכן: אם \u0003רצתה\u0004 — \u0003משמשתו\u0004 ומגורשת, \u0003רצתה\u0004 — \u0003נותנת לו מאתים זוז\u0004 ומגורשת.","\u0003אבל\u0004 אם \u0003אמר לה בפני שנים \"הרי זה גיטך על מנת שתתני לי מאתים זוז\", וחזר ואמר לה בפני שנים \"הרי זה גיטך על מנת שתתני לי שלש מאות זוז\"\u0004 — \u0003ביטל דברי\u0004 התנאי \u0003האחרון את\u0004 התנאי \u0003הראשון\u0004 ולא תתגרש עד שתיתן לו שלוש מאות. \u0003ואין אחד מן\u0004 העדים \u0003הראשונים ואחד מן האחרונים מצטרפין\u0004 להעיד על התנאי.","על המשפט האחרון תוהים: \u0003אהייא\u0004 \u0005[על היכן,\u0006 למה מתייחס הדבר\u0005]?\u0006 \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על המקרה שבסוף],\u0006 כשתבע מאה זוזים נוספים — \u0003הרי\u0004 כבר אמר שהתנאי הראשון \u0003בטל,\u0004 ובודאי אין יכול אחד העדים הראשונים להצטרף ולהעיד עם עד אחד מהעדים האחרונים. ודבר זה אין צורך לאומרו כלל! \u0003אלא\u0004 בוודאי \u0003ארישא\u0004 \u0005[על\u0006 המקרה \u0005הראשון]\u0006 נאמר כגון זה, אולם דבר זה גם כן","\u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005]\u0006 שאין מצטרפים, שהרי אינם מעידים על אותו תנאי! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כל\u0004 אלה שבאים \u0003לקיומא\u0004 \u0005[לקיים]\u0006 את \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003מצטרפין\u0004 להעיד שהיה תנאי כלשהו בגט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן, וכשאינם מעידים על אותו תנאי עצמו אין מצטרפים.","בן ארץ יהודה שאמר לאשתו \u0003\"הרי זה גיטך אם לא באתי\u0004 (אבוא) \u0003מכאן\u0004 (מעכשיו) \u0003עד שלשים יום\",\u0004 \u0003והיה הולך מיהודה לגליל\u0004 ועל דעת כן התנה — אם ילך לגליל וישוב, אם \u0003הגיע ל\u0004יישוב \u0003אנטיפרס וחזר\u0004 מיד, בתוך שלושים הימים הללו — \u0003בטל\u0004 (לא התקיים) \u0003תנאו\u0004 ואינה מגורשת, שהרי הגיע לגליל וחזר ליהודה בתוך הזמן שאמר לה.","וכיוצא בזה, בן הגליל שאמר לאשתו \u0003\"הרי זה גיטך אם לא באתי מכאן עד שלשים יום\"\u0004 \u0003והיה הולך מגליל ליהודה\u0004 ועל דעת כן התנה — שילך ליהודה וישוב משם לגליל, \u0003והגיע לכפר עותנאי וחזר\u0004 בתוך אותם שלושים יום — \u0003בטל תנאו,\u0004 שכבר הגיע ליהודה וחזר בתוך הזמן.","וכיוצא בדבר, בן ארץ ישראל שאמר לאשתו \u0003\"הרי זה גיטך אם לא באתי מכאן עד שלשים יום\", והיה הולך למדינת הים, והגיע לעכו וחזר\u0004 בתוך שלושים יום — \u0003בטל תנאו.\u0004","\u0003\"הרי זה גיטך כל זמן שאעבור מכנגד פניך\u0004 (שלא אתראה איתך) \u0003שלשים יום\"\u0004 ו\u0003היה הולך ובא, הולך ובא, הואיל ולא נתיחד עמה\u0004 במשך שלושים יום אלה — \u0003הרי זה גט.\u0004","שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 \u0003ש\u0004\u0003אנטיפרס\u0004 \u0003בגליל הוה קיימא\u0004 \u0005[היתה עומדת]?\u0006 שלכאורה נראה מן המשנה שאנטיפרס היא קצה הגליל, ואותו אדם יצא מיהודה והגיע עד לגבול הגליל וחזר. \u0003ורמינהי\u0004 \u0005[משליכים\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אנטיפרס\u0004 היא \u0003ביהודה, וכפר עותנאי\u0004 הוא \u0003בגליל,\u0004 והשטח ש\u0003בינתים\u0004 — \u0003מטילין אותו לחומרא\u0004 כשייך גם ליהודה וגם לגליל, ולכן אם הגיע עד לאותו שטח, ולא המשיך הלאה, לא ברור אם נתקיים תנאו, ולכן \u0003מגורשת\u0004"],["\u0003ואינה מגורשת!\u0004","\u0003אמר אביי:\u0004 באמת אנטיפרס היא מיהודה וכפר עותנאי מן הגליל, ויש להסביר את לשון המשנה כלשון קצרה, ולומר כי \u0003תרי תנאי קאמר\u0004 \u0005[שני תנאים אמר]\u0006 \u0003לה: אי מטינא\u0004 \u0005[אם אגיע]\u0006 \u0003לגליל\u0004 — \u0003לאלתר ליהוי גיטא\u0004 \u0005[מיד יהיה\u0006 זה \u0005גט],\u0006 \u0003ואי משתהינא באורחא תלתין יומין\u0004 \u0005[ואם אשתהה בדרך שלשים יום]\u0006 \u0003ולא אתינא\u0004 \u0005[אבוא]\u0006 — \u0003ליהוי גיטא\u0004 \u0005[יהיה\u0006 זה \u0005גט],\u0006 \u0003הגיע לאנטיפרס וחזר\u0004 בתוך שלושים יום, שגם \u0003לא לגליל מטא\u0004 \u0005[הגיע]\u0006 \u0003ולא אשתהויי נמי אשתהי תלתין יומין\u0004 \u0005[השתהה גם כן שלושים יום]\u0006 — \u0003בטל תנאו.\u0004","שנינו במשנה: \u0003\"הרי זה גיטך אם לא באתי מכאן ועד שלשים יום\" כו'.\u0004 ושואלים (לפי ההבנה הראשונה בדברי המשנה שהגיע לקצה מדינת הים וחזר מיד): \u0003למימרא\u0004 \u0005[האם לומר],\u0006 ש\u0003עכו במדינת הים קיימא\u0004 \u0005[\u0006היא \u0005נמצאת]\u0006 ואינה נחשבת כארץ ישראל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב ספרא: כי הוו מיפטרי רבנן מהדדי\u0004 \u0005[כאשר היו נפרדים חכמים זה מזה]\u0006 כשהיו יוצאים לחוץ לארץ — \u0003בעכו הוו מפטרי\u0004 \u0005[היו נפרדים]\u0006 חבריהם מהם, \u0003משום\u0004 ש\u0003אסור לצאת מארץ לחוצה לארץ\u0004 ואותו חכם שליווה את חבירו לא יצא מתחום הארץ אלא הגיע לעכו בלבד. משמע שעכו היא ארץ ישראל!","\u0003אמר אביי:\u0004 צריך להבין את המשנה כך: \u0003תרי תנאי קאמר\u0004 \u0005[שני תנאים אמר]\u0006 \u0003לה:\u0004 \u0003אי מטינא\u0004 \u0005[אם אגיע]\u0006 \u0003למדינת הים\u0004 — \u0003לאלתר ליהוי גיטא\u0004 \u0005[מיד יהיה\u0006 זה \u0005גט],\u0006 \u0003אי משתהינא באורחא תלתין יומין\u0004 \u0005[אם אשתהה בדרך שלושים יום]\u0006 \u0003ולא אתינא\u0004 \u0005[אבוא]\u0006 — \u0003ליהוי גיטא\u0004 \u0005[יהא\u0006 זה \u0005גט],\u0006 ולכן, אם \u0003הגיע לעכו וחזר, שלא\u0004 \u0003למדינת הים מטא\u0004 \u0005[הגיע]\u0006 \u0003ולא אשתהויי נמי אשתהי תלתין יומין\u0004 \u0005[השתהה גם כן שלושים יום]\u0006 — \u0003בטל תנאו.\u0004","שנינו במשנה שאם נתן גט לאשתו ואמר לה \u0003\"הרי זה גיטך כל זמן שאעבור\u0004 מכנגד פניך (שלא אתראה איתך) שלושים יום \u0003\",\u0004 אפילו היה הולך ובא, אם לא התייחד עמה בתוך זמן זה — הרי זה גט. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא עבר\u0004 מכנגד פניה, אלא היה הולך ובא! \u0003אמר רב הונא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פניך\"\u0004 שאמר בתנאי? כוונתו \u0003תשמיש,\u0004 שהיתנה שאם לא ישמש עמה במשך שלושים יום יהא זה גט. \u0003ואמאי קרי ליה\u0004 \u0005[מדוע קורא לו]\u0006 לענין זה \u0003\"פניך\"\u0004 — \u0003לישנא מעליא נקט\u0004 \u0005[לשון מעולה,\u0006 נקיה, \u0005תפס],\u0006 וכיון שלא התייחד עמה — נתקיים התנאי ויחול הגט.","\u0003ור' יוחנן אמר: לעולם\u0004 הכוונה היא \u0003פניך ממש,\u0004 כלומר, שלא יתראה עמה למשך שלושים יום רצופים, אולם \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה \u0003\"הרי זו מגורשת\"\u0004 שחל הגט מיד? \u0003\"הרי זה גט\" קתני\u0004 \u0005[שנה],\u0006 לומר: שאף שלא נתקיים התנאי במשך שלושים יום אלה, אם לא נתייחד עמה \u0003לא הוי\u0004 \u0005[אין\u0006 זה נחשב\u0005]\u0006 \u0003גט ישן\u0004 שאמרו חכמים שאין מגרשים בו, \u0003ולכי מלו תלתין יומי הוי גיטא\u0004 \u0005[וכאשר ימלאו שלושים יום\u0006 ואכן יעבור מכנגד פניה \u0005יהא זה גט].\u0006","ומעירים \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 האומר לאשתו \u0003\"הרי זה גיטך כל זמן שאעבור מנגד פניך שלשים יום\", והיה הולך ובא, הולך ובא, הואיל ולא נתייחד עמה\u0004 — \u0003הרי זה גט, ולגט ישן אין חוששין שהרי לא נתייחד עמה,\u0004 וכדברי ר' יוחנן שהחשש הוא משום גט ישן.","ושואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא פייס\u0004 את אשתו במשך הזמן הזה שהיה הולך ובא, ונתייחד עמה! \u0003אמר רבה בר רב הונא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא מרי\u0004 \u0005[אבי מורי,\u0006 רב הונא\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: באומר\u0004 הבעל: \u0003נאמנת עלי לומר שלא באתי.\u0004 וכיון שמאמינה על כך, אם אמרה שלא נתייחד עמה — נשאר הגט בתוקפו.","\u0003איכא דמתני לה אמתניתין\u0004 \u0005[יש ששונים\u0006 את הדבר \u0005הזה על משנתנו\u0006 להלן\u0005]:\u0006 אם אמר \u0003\"\u0004הרי זה גיטך \u0003מעכשיו אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש\u0004 — \u0003הרי זה גט.\u0004 ויש לשאול: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא פייס\u0004 את אשתו בינתיים ונתייחד עמה! \u0003אמר רבה בר רב הונא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא מרי משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רב, באומר\u0004 הבעל: \u0003נאמנת עלי לומר שלא באתי.\u0004","ומעירים: \u0003מאן דמתני לה אמתניתין\u0004 \u0005[מי ששונה אותה\u0006 שמועה \u0005על משנתנו],\u0006 \u0003כל שכן\u0004 שכך הוא מסביר את ה\u0003ברייתא\u0004 שבה ידוע שהגיע לעירו, שחייבים לומר שנתן לה נאמנות לומר שלא נתייחד ולא פייס.","אבל \u0003מאן דמתני לה\u0004 \u0005[מי ששונה אותה]\u0006 על ה\u0003ברייתא\u0004 יש לומר: \u0003אבל אמתניתין\u0004 \u0005[על משנתנו]\u0006 אינו צריך לכך, שכן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא אתא\u0004 \u0005[בא],\u0006 ואין מקום לחשוש שמא בכל זאת חזר ובא לביתו ופייסה בלא שידע איש על כך.","האומר לאשתו \u0003\"הרי זה גיטך אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש\u0004 — \u0003אינו גט,\u0004 שהרי הגט יחול רק כעבור שנים עשר חדש, וכיון שמת בינתיים — לא חל הגט, והאשה היא אלמנה, וחלה עליה חובת יבום.","אבל אם אמר לה \u0003\"הרי זה גיטך מעכשיו אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש\u0004 — \u0003הרי זה גט,\u0004 שהרי חלות הגט היא מעכשיו, וכיון שלסוף שנה לא בא — נמצא שהתקיים התנאי.","אמר \u0003\"אם לא באתי מכאן ועד שנים עשר חדש כתבו ותנו גט לאשתי\",\u0004 אם \u0003כתבו גט בתוך שנים עשר חדש ונתנו לאחר שנים עשר חדש\u0004 — \u0003אינו גט,\u0004 שהרי הורה לכתוב את הגט רק לאחר זמן זה.","ואם אמר \u0003\"כתבו ותנו גט לאשתי אם לא באתי מכאן עד שנים עשר חדש\",\u0004 אם \u0003כתבו בתוך שנים עשר חדש ונתנו לאחר שנים עשר חדש\u0004 — \u0003אינו גט,\u0004 לפי שמשמעות דבריו שיכתבו רק לאחר שנתברר שלא בא בתוך שנים עשר חודש. \u0003ר' יוסי אומר: כזה גט,\u0004 שהרי לא פירש להם מתי לכתוב את הגט, אלא את זמן הנתינה.","אף לשיטת סתם משנה, אם \u0003כתבו לאחר שנים עשר חדש ונתנו לאחר שנים עשר חדש, ומת\u0004 הבעל, \u0003אם\u0004 מסירת \u0003הגט\u0004 היתה \u0003קודם למיתה\u0004 — \u0003הרי זה גט, ואם מיתה קדמה ל\u0004מסירת ה\u0003גט\u0004 — \u0003אינו גט, ואם אין ידוע\u0004 מה קדם למה — \u0003זו היא שאמרו\u0004 חכמים \u0003מגורשת ואינה מגורשת.\u0004","על האמור במשנה שאם נתן לה גט והתנה \"אם לא באתי מכאן עד שנים עשר חודש\", ומת בתוך אותם שנים עשר חודש, שאינו גט, וחלה עליה חובת יבום, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003רבותינו התירוה לינשא\u0004 בלא להיזקק לחליצה, לפי שהם סבורים שהיא מגורשת בגט זה.","ומבררים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003רבותינו\u0004 אלה? \u0003אמר רב יהודה אמר שמואל: בי דינא דשרו מישחא\u0004 \u0005[בית הדין שהתירו שמן]\u0006 של הגויים באכילה. ומה טעמם להתירה להינשא בגט זה? — \u0003סברי לה\u0004 \u0005[סבורים הם]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו\u0004 וכל שטר שיש בו תאריך מניחים שהכוונה של נותן השטר היא שיחול מאותו זמן שנכתב אף אם לא נאמר במפורש \"על מנת\" או \"מעכשיו\".","\u0003אמר ר' אבא בריה\u0004 \u0005[בנו\u0006 של\u0005]\u0006 \u0003ר' חייא בר אבא אמר ר' יוחנן: ר' יהודה נשיאה\u0004 (הנשיא) \u0003בנו של רבן גמליאל בר ר' יהודה\u0004 (הנשיא) \u0003הורה\u0004 דבר זה, \u0003ולא הודו לו כל סיעתו,\u0004 בני החבורה שלו, שאף בבית מדרשו לא הסכימו אתו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שלא הודו לו \u0003כל שעתו,\u0004 כלומר, כל ימי חייו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר לההוא סבא\u0004 \u0005[לזקן אחד]\u0006 שהיה חבר בבית דינו של ר' יהודה נשיאה: \u0003כי שריתוה\u0004 \u0005כאשר התרתם אותה]\u0006 את אשה זו — האם \u0003לאלתר שריתוה\u0004 \u0005[מיד היתרתם אותה],\u0006 \u0003או לאחר שנים עשר חדש שריתוה\u0004 \u0005[היתרתם אותה]?\u0006 האם \u0003לאלתר שריתוה\u0004 \u0005[מיד התרתם אותה]\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אתי\u0004 \u0005[בא],\u0006 שהגט חל מייד, ואין צורך להמתין עד שנים עשר חדש — שהרי ודאי לא יוכל הבעל לבוא עוד, שהרי מת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לאחר שנים עשר חדש שריתוה\u0004 \u0005[התרתם אותה]\u0006 — \u0003דהא איקיים ליה תנאו\u0004 \u0005[שהרי התקיים\u0006 אז \u0005התנאי]\u0006 שלא חזר כעבור שנים עשר חודש?","ושואלים: \u0003ותיבעי ליה מתניתין\u0004 \u0005[ותישאל לו\u0006 שאלה זו לגבי \u0005משנתנו]:\u0006 שהאומר לאשתו \u0003\"\u0004הרי זה גט \u0003מעכשיו אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש\u0004 — \u0003הרי זה גט,\u0004 האם \u0003לאלתר הוי\u0004 \u0005[מיד חל\u0006 הגט\u0005]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אתי,\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 רק \u0003לאחר שנים עשר חדש\u0004 — \u0003דהא איקיים ליה תנאיה\u0004 \u0005[שהרי\u0006 רק אז \u0005התקיים לו תנאו]?\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 ובאמת אפשר לשאול שאלה זו על המשנה, \u0003ומשום דהוה בההוא מעשה\u0004 \u0005[שהיה\u0006 אותו זקן \u0005באותו מעשה]\u0006 שאל אותו, שיוכל לברר את הדברים מתוך מעשה שהיה.","\u0003אמר אביי: הכל מודים, היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר\u0004 לאשתו בלילה שהגט שהוא נותן לה יהא גט \u0003לכשתצא חמה מנרתיקה\u0004 —"],["\u0003לכי נפקא קאמר\u0004 \u0005[לכשתצא\u0006 השמש \u0005אמר]\u0006 \u0003לה,\u0004 \u0003וכי מיית בליליא\u0004 \u0005[וכאשר מת בלילה]\u0006 לפני שיצאה השמש \u0003הוי\u0004 \u0005[יהא]\u0006 זה \u0003גט לאחר מיתה\u0004 ואינו כשר.","ואם אמר לה \u0003\"על מנת שתצא חמה מנרתיקה\"\u0004 — \u0003מעכשיו קאמר\u0004 \u0005[אמר]\u0006 \u0003לה\u0004 שיחול הגט למפרע כאשר תצא החמה, ש\u0003אמר רב הונא אמר רב: כל האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006","\u0003לא נחלקו אלא ב\u0004אומר \u0003\"אם תצא\u0004 חמה מנרתיקה \u0003\",\u0004 \u0003מר סבר לה\u0004 \u0005[חכם זה\u0006 \"רבותינו\" \u0005סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו, והוה ליה\u0004 \u0005[והרי זה]\u0006 \u0003כ\u0004אומר \u0003\"מהיום אם מתי\",\u0004 או \u0003כ\u0004אומר \u0003\"מעכשיו\u0004 \u0003אם מתי\".\u0004 ואילו \u0003מר\u0004 \u0005[חכם זה,\u0006 סתם משנתנו\u0005]\u0006 \u0003לא סבר כ\u0004שיטת \u0003ר' יוסי, והוה ליה\u0004 \u0005[והרי זה]\u0006 \u0003כ\u0004אומר \u0003\"אם מתי\" גרידא\u0004 \u0005[בלבד],\u0006 שמשמעותו לאחר מיתה.","שנינו במשנה, האומר \u0003\"כתבו ותנו גט לאשתי אם לא באתי מכאן ועד שנים עשר חדש\",\u0004 אם \u0003כתבו\u0004 את הגט בתוך שנים עשר חודש, אף שנתנוהו לאחר שנים עשר חודש — לדעת חכמים הגט פסול, ולדעת ר' יוסי כשר הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: לימא קסבר\u0004 \u0005[האם לומר\u0006 ש\u0005סבור]\u0006 \u0003ר' יוסי\u0004 בכלל שאם \u0003כתב גט על תנאי\u0004 — \u0003כשר?\u0004 ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 ש\u0003פסול, ושאני הכא\u0004 \u0005[ושונה כאן],\u0006 \u0003מדהוה ליה למימר\u0004 \u0005[מ\u0006תוך \u0005שהיה לו לומר]\u0006 \u0003\"אם לא באתי\u0004 בתוך שנים עשר חודש \u0003כתבו ותנו\"\u0004 להדגיש שגם הכתיבה תיעשה רק אם לא בא, \u0003ואמר\u0004 בלשון אחרת \u0003\"כתבו ותנו אם לא באתי\",\u0004 משמע ש\u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך נתכוון לומר: \u0003כתבו מעכשיו, ותנו אם לא באתי. ורבנן\u0004 \u0005[חכמים]\u0006 מה הם סבורים? \u0003לא שנא הכי ולא שנא הכי\u0004 \u0005[אינו שונה כך ואינו שונה כך],\u0006 ואין לחלק לפי דיוקי הלשון הללו. מתוך שדנים במשנה על קביעת זמנים, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר \u0003\"לאחר שבוע\u0004 (שמיטה, שבע שנים) \u0003\"\u0004— \"לאחר\" משמעו לפחות \u0003שנה\u0004 אחרי סוף אותו שבוע, אם אמר \u0003\"לאחר שנה\"\u0004 כוונתו — \u0003חדש\u0004 לאחר גמר השנה, \u0003\"לאחר חדש\"\u0004 פירושו — \u0003שבת\u0004 (שבוע ימים).","","ומתוך כך שואלים: אם אמר \u0003\"לאחר שבת\", מאי\u0004 \u0005[מה\u0006 הכוונה\u0005]?\u0006 מספרים: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' זירא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אסי,\u0004 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' אסי\u0004 שישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן, וקאמר\u0004 \u0005[ואמר]\u0006 כך: \u0003חד בשבא, ותרי, ותלתא\u0004 — \u0005[אחד\u0006 יום ראשון \u0005בשבת, ושני ושלישי]\u0006 — נקראים \u0003בתר שבתא\u0004 \u0005[אחר השבת].\u0006 \u0003ארבעה, וחמשה ומעלי שבתא\u0004 \u0005[רביעי וחמישי וערב שבת]\u0006 נקראים \u0003קמי שבתא\u0004 \u0005[לפני שבת].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 אם אדם אומר \u0003\"לאחר הרגל\"\u0004 — משמעו \u0003שלשים יום\u0004 לאחר הרגל. \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003ר' חייא דרשה\u0004 את ההלכה הזו בציבור \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבי וקלסוה\u0004 \u0005[ושיבחו אותו],\u0006 דרשה \u0003משמיה דרבים,\u0004 כלומר, דרשה סתם ולא אמר שהיא דעת היחיד של רבי — \u0003ולא קלסוה\u0004 \u0005[שיבחו אותו],\u0006 \u0003אלמא לית הילכתא כוותיה\u0004 \u0005[מכאן\u0006 ש\u0005אין הלכה כמותו]\u0006 בענין זה, ולכן לא הודו חכמים לר' חייא כשאמרה כהלכה סתם.","","\u0003הזורק גט לאשתו, והיא\u0004 נמצאת אז \u0003בתוך ביתה או בתוך חצרה\u0004 — \u0003הרי זו מגורשת,\u0004 ונחשב הדבר כאילו נתנו לה בידה. \u0003זרקו לה בתוך ביתו או בתוך חצרו\u0004 שלו, \u0003אפילו הוא\u0004 (הגט) \u0003עמה במטה\u0004 — \u0003אינה מגורשת.\u0004 זרקו ונפל הגט \u0003לתוך חיקה או לתוך קלתה\u0004 (הסל שלה) — \u0003הרי זו מגורשת\u0004 גם אם היא באותה שעה בביתו של בעלה.","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 ששנינו במשנה שאם נפל הגט בביתה או בחצירה הרי אלו גירושין? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בגט \u0003\"ונתן בידה\"\u0004 (דברים כד, א), \u0003אין לי אלא\u0004 שנתן בתוך \u0003ידה\u0004 ממש. אם נתן גט בתוך \u0003גגה,\u0004 או \u0003חצרה ו\u0004כן \u0003קרפיפה\u0004 (מגרש מגודר שלה), \u0003מנין\u0004 שגם כן הוא גט? — \u0003תלמוד לומר: \"ונתן\"\u0004 — משמע: \u0003מכל מקום,\u0004 בכל אופן שנתן.","\u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גנב:\u0004 נאמר בתורה \"אם המצא תמצא בידו הגנבה\" (שמות כב, ג), ממה שנאמר \u0003\"ידו\"\u0004 — \u0003אין לי אלא\u0004 שנמצאה ממש ב\u0003ידו\u0004 לאחר הגניבה. אבל אם נמצאה ב\u0003גגו, חצרו וקרפיפו,\u0004 שהגיע חפץ לרשותו ונעל אותו מתוך כוונה לגנוב, \u0003מנין\u0004 שהוא חייב? — \u0003תלמוד לומר: \"המצא תמצא\", מכל מקום.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לחזור ולומר דין זה בשתי ההלכות הללו, משום \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003גט\u0004 היינו אומרים \u0003משום\u0004 ש\u0003בעל כרחה מגרשה\u0004 \u0005[\u0006היא \u0005מתגרשת]\u0006 לכן נתינה כל שהיא תועיל, \u0003אבל גנב דליתיה בעל כורחיה\u0004 \u0005[שאינו בעל כורחו],\u0006 שהרי מתחייב רק על מה שגונב מרצונו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ודווקא אם גנב בידו ממש מתחייב, אבל אם רק הגיע הדבר לחצירו והוא מתכוון לגונבו יהיה פטור.","\u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003גנב\u0004 היינו אומרים שזה דינו של גנב \u0003משום דקנסיה רחמנא\u0004 \u0005[שקנסה אותו התורה]\u0006 על הגניבה ומענישים אותו גם על מה שאינו בידו ממש, \u0003אבל גט\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחול הגט אלא אם כן ניתן בידיה ממש, על כן \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005]\u0006 בשתי ההלכות.","עד כאן בבירור מקור הדברים בתורה, ומעתה באים לברר את הצד המשפטי שבהלכה. נאמר במשנה שאם זרק לה בתוך \u0003חצרה\u0004 הריהו גט. ויש לשאול: כיצד יכולה להיות לה חצר משלה? והלא כל \u0003מה שקנתה אשה קנה בעלה,\u0004 והוא זכאי להשתמש בכל רווחיהם (פירותיהם) של נכסיה, ואם כן בהיותה נשואה חצירו היא! \u0003אמר ר' אלעזר,\u0004 מדובר \u0003בכותב לה:\u0004 \u0003\"דין ודברים אין לי בנכסיך\",\u0004 שסילק עצמו מבעלות על רכושה.","","ושואלים: \u0003וכי כתב לה הכי מאי הוי\u0004 \u0005[וכאשר כותב לה כך מה יש\u0006 בזה\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו\u0004 שותפו בבעלות על שדה: \u0003\"דין ודברים אין לי על שדה זו\", ו\u0004כן \u0003\"אין לי עסק בה\", ו\u0004כן \u0003\"ידי מסולקת הימנה\"\u0004 — \u0003לא אמר כלום,\u0004 שאין לשונות אלה מועילות להיחשב כוויתור על זכותו בשדה!","ומתרצים: \u0003אמרי דבי\u0004 \u0005[אומרים בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 מדובר \u0003בכותב לה ועודה ארוסה,\u0004 לפני שהיתה לו בעלות על רכושה, כי זכותו ליהנות מרכוש אשתו מתחילה רק מזמן הנישואין ואילך. \u0003וכ\u0004דברי \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא:\u0004 \u0003נחלה הבאה לו לאדם ממקום אחר\u0004 ואינה ממש ירושת אבותיו — \u0003אדם מתנה עליה\u0004 מראש \u0003שלא ירשנה,\u0004 ותנאי זה מועיל לבטל את זכותו. משמע שכל עוד לא הגיע הרכוש לידו יכול הוא לוותר על זכותו בו. \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא, האומר:\u0004",""],["\u0003אי אפשי\u0004 (אין רצוני) \u0003בתקנת חכמים\u0004 שתיקנו לטובתי \u0003כגון זו\u0004 — \u0003שומעין לו.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כגון זו\",\u0004 כלומר, למה התייחסו דברי רבא, שהוא אומר שלא רק באותו מקרה אלא גם במקרים אחרים זה הדין? ומסבירים שהתייחס למה שאמר \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: יכולה אשה שתאמר לבעלה \"איני ניזונית\u0004 משלך \u0003ואיני עושה\u0004 עבודה בשבילך\", שכן תקנה היא שתיקנו לטובתה שתיזון ממנו תמורת מלאכתה, ויכולה היא לוותר על זכותה זו. והוסיף רבא ואמר שלגבי כל תקנה דומה שנתקנה לתועלתו של אדם יכול הוא לומר שאינו רוצה בתקנת חכמים זו, לפי שלגביו אינה מביאה תועלת.","\u0003רבא אמר\u0004 שיש לפתור את השאלה לגבי קניינה בחצרה באופן אחר, מהותי יותר: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ידה מי לא קניא ליה\u0004 \u0005[האם אינה קנויה לו]\u0006 \u0003לבעל\u0004 למעשה ידיה? ובכל זאת היא מתגרשת בקבלת גט לידה! \u0003אלא\u0004 בעל כורחך אתה צריך לומר ש\u0003גיטה וידה\u0004 (כלומר, בעלותה המלאה על ידה) \u0003באין כאחד\u0004 (בבת אחת), שכיון שהגט מפריד ומשחרר אותה משיעבודה לבעלה, הרי באותה שעה עצמה היא קונה את זכותה בידה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בחצר, יש לומר כי \u0003גיטה וחצרה באין כאחד,\u0004 שהרי זכותו של הבעל ברכושה מסתיימת בגירושיה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: רבא\u0004 שתירץ כפי שתירץ, בענין \u0003יד\u0004 של אשה \u0003קא קשיא ליה\u0004 \u0005[קשה לו]?!\u0006 מה הקושי בכך? \u0003נהי דקני ליה\u0004 \u0005[אף שקנויה לו,\u0006 לבעל\u0005]\u0006 הזכות \u0003למעשה ידיה\u0004 של אשתו, אולם \u0003ידה גופה\u0004 \u0005[עצמה]\u0006 \u0003מי קני ליה\u0004 \u0005[האם קנויה לו]?\u0006 ולכן מתגרשת האשה בקבלת הגט לידה, ואין צורך לכלל של גיטה וידה באים כאחד, וכן לכלל של גיטה וחצירה באים כאחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003רבא, יד העבד קא קשיא ליה\u0004 \u0005[היה קשה לו];\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שעבד משתחרר \u0003בשטר על ידי עצמו\u0004 (הניתן לו עצמו), יש לשאול: הלא \u0003יד עבד כיד רבו דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שגופו של העבד קנוי לו, וכשנותן ליד העבד — כאילו נותן לאדון, ואם כן אין השטר נחשב כמגיע לרשות העבד, אלא כאילו נשאר בידי האדון! \u0003אלא\u0004 צריך לומר ש\u0003גטו וידו באין כאחד, הכי נמי\u0004 \u0005[כאן גם כן]\u0006 בחצר של אשה, \u0003גיטה וחצירה באין כאחד.\u0004","מסופר: \u0003ההוא שכיב מרע\u0004 \u0005[אדם אחד שנטה למות]\u0006 \u0003דכתב לה גיטא לדביתהו בהדי פניא דמעלי שבתא\u0004 \u0005[שכתב גט לאשתו בין השמשות של ערב שבת]\u0006 \u0003ולא הספיק למיתביה\u0004 \u0005[לתת אותו]\u0006 \u0003לה, למחר תקף ליה עלמא\u0004 \u0005[לו העולם],\u0006 כלומר, התגברה עליו מחלתו ולא יכול היה ללכת ולתת לה את הגט. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לשאול מה לעשות. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו\u0004 \u0005[לכו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003ליקניה ניהלה לההוא דוכתא דיתיב ביה גיטא\u0004 \u0005[שיקנה לה\u0006 לאשתו \u0005אותו המקום שנמצא בו הגט],\u0006 \u0003ותיזל איהי ותיחוד\u0004 \u0005[ותלך היא ותאחוז,\u0006 תסגור את הפתח\u0005]\u0006 ותפתח אותו \u0003ו\u0004על ידי כך \u0003תחזיק\u0004 (תעשה מעשה של חזקה) \u0003ביה\u0004 \u0005[בו]\u0006 במקום, ותקנה אותו ואת הגט שבו.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 מי ש\u0003נעל\u0004 או \u0003גדר,\u0004 או \u0003פרץ כל שהוא\u0004 — \u0003הרי זו חזקה\u0004 שעל ידה קונים קרקע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עיליש לרבא:\u0004 מה יועיל הדבר שקנתה לה את המקום? הרי \u0003מה שקנתה\u0004 \u0003אשה קנה בעלה! איכסיף\u0004 \u0005[התבייש\u0006 רבא\u0005]\u0006 על שפסק שלא כדין.","\u0003לסוף איגלי מילתא\u0004 \u0005[התגלה הדבר]\u0006 ש\u0003ארוסה הואי\u0004 \u0005[היתה]\u0006 אותה אשה, \u0003אמר רבא:\u0004 יפה פסקתי מתחילה, שכן \u0003אם אמרו בנשואה\u0004 שכל מה שקנתה קנה בעלה, \u0003יאמרו\u0004 כמו כן אף \u0003בארוסה?\u0004 שהרי בארוסה ודאי אין ידה כיד בעלה. \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא:\u0004 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 ב\u0003ארוסה\u0004 \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 בנשואה, \u0003גיטה וחצירה באין כאחד.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה רבא\u0004 להלכה זו \u0003מעיקרא\u0004 \u0005[מתחילה]!\u0006 ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמרה רבא\u0004 להלכה זו — \u0003אהאי\u0004 \u0005[על זה]\u0006 \u0003מעשה\u0004 זה \u0003אמרה.\u0004","שנינו במשנה שיכול לתת לה גט \u0003והיא בתוך ביתה. אמר עולא: והוא\u0004 (ובלבד) \u0003שעומדת בצד ביתה ובצד חצרה\u0004 שאז קונים לה ביתה וחצירה. \u0003ר' אושעיא אמר: אפילו היא\u0004 נמצאת \u0003בטבריא\u0004 (טבריה) \u0003וחצרה\u0004 היתה \u0003בציפורי,\u0004 או ש\u0003היא בציפורי וחצרה בטבריא\u0004 — \u0003מגורשת.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"היא בתוך ביתה ובתוך חצרה\" קתני\u0004 \u0005[שנה]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך התכוון לומר: \u0003\"והיא\u0004 נחשבת \u0003כמי שבתוך ביתה\", \"והיא כמי שבתוך חצרה\",\u0004 שכיון שחצר זו \u0003משתמרת לדעתה היא,\u0004 הרי זה כאילו היתה שם, ו\u0003מתגרשת.\u0004","ושואלים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 שבנושא \u0005זה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 עולא, \u0005סבור]:\u0006 \u0003חצר משום ידה אתרבאי\u0004 \u0005[התרבתה]\u0006 במדרש המקראות, ומשום כך דינה כדין יד, וכשם שידה סמוכה לה — אף חצירה צריכה להיות סמוכה לה כדי שתקנה לה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אושעיא, \u0005סבור]:\u0006 \u0003חצר משום שליחות אתרבאי\u0004 \u0005[נתרבתה]\u0006 ודינה כדין שליח, ולכן קונה לה חצירה גם בריחוק מקום?","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 — \u0003חצר משום ידה איתרבאי\u0004 \u0005[נתרבתה],\u0006 ונחלקו בדרך הלימוד מידה, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 עולא \u0005סבור]:\u0006 דינה לגמרי \u0003כידה, מה ידה\u0004 הכתובה בתורה, מדובר \u0003בסמוכה\u0004 לה — \u0003אף חצרה\u0004 הנלמדת ממנה, מדובר \u0003בסמוכה\u0004 לה.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' אושעיא סבור: \u0003אי\u0004 \u0005[אם]\u0006 לומד אתה באופן זה, יהא עליך לומר: \u0003מה ידה בדבוקה\u0004 לה, \u0003אף חצרה בדבוקה,\u0004 ובוודאי אין אתה יכול לומר שחצירה תהא דבוקה בה כדי שתקנה לה! \u0003אלא\u0004 כך יש ללמוד: חצירה דינה \u0003כידה, מה ידה משתמרת לדעתה\u0004 — \u0003אף חצרה המשתמרת לדעתה, לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 אופן של \u0003חצרה המשתמרת שלא לדעתה,\u0004 שאין לה שליטה עליה, שבמקרה זה אינה קונה מה שנמצא בחצר, לפי שאינה דומה לידה.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003זרק לה גיטא\u0004 \u0003לדביתהו\u0004 \u0005[גט לאשתו],\u0006 \u0003הוה קיימא\u0004 \u0005[היתה\u0006 האשה \u0005עומדת]\u0006 \u0003בחצר, אזל גיטא\u0004 \u0005[הלך הגט]\u0006 תוך הזריקה, ו\u0003נפל בפיסלא\u0004 \u0005[על חתיכת עץ].\u0006 \u0003אמר רב יוסף: חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי הויא\u0004 \u0005[אם היתה]\u0006 חתיכת העץ הזו בעלת שטח של \u0003ארבע אמות על ארבע אמות\u0004 — \u0003פלג ליה רשותא לנפשיה\u0004 \u0005[חלקה לה רשות לעצמה]\u0006 ואינה בכלל החצר שהאשה נמצאת בה, ולכן אינה מתגרשת בו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003חדא רשותא\u0004 \u0005[רשות אחת]\u0006 \u0003היא\u0004 חלק מן החצר, ומתגרשת בו.","ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בחצר דידה\u0004 \u0005[שלה],\u0006 \u0003כי הוי\u0004 \u0005[כאשר יהיה]\u0006 המקום בן \u0003ארבע אמות מאי הוי\u0004 \u0005[מה יהיה\u0006 בכך\u0005]?\u0006 הלא גם חלק זה שלה הוא ולמה לא תתגרש בו! \u0003אלא\u0004 תאמר שמדובר \u0003בחצר דידיה\u0004 \u0005[שלו],\u0006 \u0003כי לא הוי\u0004 \u0005[\u0006גם כאשר איננו] בן \u0003ארבע אמות מאי הוי\u0004 \u0005[מה יהיה\u0006 בכך\u0005]?\u0006 הלא הכל אינו שלה ומדוע מתגרשת בו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאושלה\u0004 \u0005[שהשאיל לה]\u0006 \u0003מקום\u0004 את החצר כדי שתקנה בו את הגט, \u0003דחד מקום מושלי אינשי\u0004 \u0005[שמקום אחד משאילים אנשים],\u0006 ואילו \u0003תרי\u0004 \u0005[שני]\u0006 \u0003מקומות לא מושלי אינשי\u0004 \u0005[משאילים אנשים],\u0006 ואם המקום בו נפל הגט נחשב רשות לעצמה, איננו בכלל החצר שהשאיל לה.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו ]\u0006 דין זה \u0003אלא\u0004 באופן שהמקום שנפל בו הגט \u0003לא גבוה עשרה\u0004 טפחים מן החצר, \u0003אבל\u0004 אם המקום שנפל בו הגט \u0003גבוה עשרה\u0004 טפחים — \u0003אף על גב דלא הוי\u0004 \u0005[אף על פי שאינו]\u0006 בן \u0003ארבע אמות\u0004 הריהו חלוק כרשות לעצמה.","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 למקום שנפל בו הגט"],["\u0003שם לווי,\u0004 שלחתיכת העץ הזו אין שם או כינוי המיוחד לעצמה, \u0003אבל\u0004 אם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003שם לווי,\u0004 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא גבוה עשרה\u0004 טפחים מן החצר, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 \u0003דלא הוי\u0004 \u0005[שאינו]\u0006 \u0003ארבע אמות\u0004 הרי הוא כרשות לעצמה ואין האשה מתגרשת בו.","שנינו במשנה שאם נתן לה את הגט סמוך לה \u0003אפילו הוא עמה במטה\u0004 אינה מגורשת. \u0003אמר רבא: לא שנו אלא\u0004 שנתן את הגט \u0003במטה שלו, אבל\u0004 אם נתן את הגט \u0003במטה שלה\u0004 — \u0003מגורשת.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' אליעזר אומר:\u0004 אם נתן את הגט \u0003במטה שלו\u0004 — \u0003אינה מגורשת, במטה שלה\u0004 — \u0003מגורשת.\u0004","ותוהים: \u0003ו\u0004אם נתן את הגט \u0003במטה שלה\u0004 האם היא \u0003מגורשת?!\u0004 הלא \u0003כליו של לוקח\u0004 (קונה) \u0003ברשות מוכר הוא!\u0004 שאף שהמיטה היא שלה, מכל מקום המיטה עצמה נמצאת ברשות הבעל. האם \u0003שמעת מינה\u0004 \u0005[למד אתה מכאן]:\u0006 ש\u0003כליו של לוקח ברשות מוכר\u0004 — \u0003קנה לוקח?\u0004 והלא דבר זה שנוי במחלוקת, ויש אומרים שדבר הנכנס בכליו של הלוקח כשהיו הכלים מונחים ברשות המוכר — לא קנה הלוקח!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה ש\u0003גבוה,\u0004 כלומר, גבוהה המיטה \u0003עשרה\u0004 טפחים, שאז היא נחשבת כרשות לעצמה. ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מקום כרעי\u0004 \u0005[הרגליים\u0006 של המיטה\u0005]\u0006 שהוא ברשותו של הבעל! ומשיבים: על \u0003מקום כרעי\u0004 \u0005[רגלי\u0006 המיטה\u0005]\u0006 \u0003לא קפדי אינשי\u0004 \u0005[מקפידים אנשים]\u0006 מפני שהוא מקום קטן ביותר, וכיון שהמיטה היא כרשות לעצמה, אינה נחשבת כמצויה ברשות הבעל.","שנינו במשנה שאם זרק את הגט \u0003לתוך חיקה או לתוך קלתה\u0004 אפילו היתה בתוך ביתו או חצירו — הריהי \u0003מגורשת.\u0004 ומקשים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 מגורשת אם נתן את הגט לתוך קלתה? הלא מקרה זה \u0003כליו של לוקח ברשות מוכר הוא,\u0004 והרי דבר זה שנוי במחלוקת אם כליו של קונה ברשות מוכר קונים לו!","\u0003אמר רב יהודה אמר שמואל:\u0004 במשנתנו מדובר \u0003כגון שהיתה קלתה תלויה בה,\u0004 על גופה של האשה, ואז אינה מונחת ברשותו של הבעל. \u0003וכן אמר ר' אלעזר אמר ר' אושעיא: כגון שהיתה קלתה תלויה בה. ור' שמעון בן לקיש אמר:\u0004 אם היתה \u0003קשורה\u0004 בה, \u0003אף על פי שאינה תלויה\u0004 —","דיו. \u0003רב אדא בר אהבה אמר: כגון שהיתה קלתה מונחת לה בין ירכותיה\u0004 (רגליה) שאז מונחת הקלת במקום מושבה של האשה עצמה, ועל כך אינו מקפיד. \u0003רב משרשיא בר רב דימי אמר: כגון שהיה בעלה מוכר קלתות\u0004 (סלים), ולכן איננו מקפיד על מקום הקלת, לפי שכל חצרו עשויה לכך.","\u0003ר' יוחנן אמר:\u0004 אין צורך בהסברים אלה, אלא \u0003מקום חיקה קנוי לה, מקום קלתה קנוי לה. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן?\u0004 — \u0003לפי שאין אדם מקפיד\u0004 על אשתו \u0003לא על מקום חיקה ולא על מקום קלתה,\u0004 והרי זה כאילו הקנה אותם לה לכל שימוש.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 אם \u0003זרקו\u0004, את הגט, \u0003לה לתוך חיקה או לתוך קלתה, או לתוך כל דבר שהוא כקלתה\u0004 — \u0003הרי זו מגורשת.\u0004","ומתוך שהבאנו ברייתא זו מדייקים בלשונה: \u0003\"כל דבר שהוא כקלתה\" לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה]?\u0006 — \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003טסקא דאכלה בה תמרי\u0004 \u0005[סל ש\u0006היא \u0005אוכלת בו תמרים]\u0006 שגם על מקומו אינו מקפיד.","\u0003אמר לה\u0004 לאשתו \u0003\"כנסי\u0004 (קחי) \u0003שטר חוב זה\"\u0004 והיה זה גט, \u0003או שמצאתו מאחוריו,\u0004 ולא אמר לה מה הוא ורק כשהיא \u0003קוראה\u0004 מה שכתוב בו \u0003והרי הוא גיטה\u0004 — \u0003אינו גט, עד שיאמר לה \"הא גיטיך\".\u0004","אם \u0003נתן בידה והיא\u0004 היתה אז ישנה, ו\u0003ניעורה,\u0004 ו\u0003קוראה והרי הוא גיטה\u0004 — \u0003אינו גט, עד שיאמר לה \"הא גיטיך\".\u0004","על האמור במשנה שאם מצאה את הגט מאחוריו אינו גט עד שיאמר לה \"הא גיטיך\", שואלים: \u0003כי אמר\u0004 \u0005[כאשר יאמר]\u0006 \u0003לה \"הא גיטיך\"\u0004 \u0003מאי הוי\u0004 \u0005[מה יהיה]\u0006 על ידי כך? הרי אין זו נתינת גט כהלכתה, ו\u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 כאילו היה אומר לה \u0003\"טלי גיטיך מעל גבי קרקע\",\u0004","\u0003ואמר רבא:\u0004 האומר לאשתו \u0003\"טלי גיטיך מעל גבי קרקע\"\u0004 — \u0003לא אמר כלום\u0004 שאינה מגורשת אלא כאשר ניתן לה מן הבעל! ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 לא שהיה הגט מונח על הקרקע מאחוריו, אלא \u0003ששלפתו\u0004 (הוציאה אותו) \u0003מאחוריו\u0004 שהיה תחוב בחגורתו, והרי ניתן לה הגט ממנו.","ומקשים: במקרה ש\u0003שלפתו נמי\u0004 \u0005[גם כן]\u0006 אינו גט, שכן \u0003הא בעינא\u0004 \u0005[הרי צריכים]\u0006 שיתקיים \u0003\"ונתן בידה\"\u0004 (דברים כד, ב) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אף על פי שהגט בידה — לא הוא שנתנו לה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה \u0003דערק\u0004 \u0005[שכפף,\u0006 פשט\u0005]\u0006 \u0003לה\u0004 את \u0003חרציה\u0004 \u0005[מותניו]\u0006 \u0003ושלפתיה\u0004 \u0005[ושלפה אותו],\u0006 משום שפשיטת מותניו הרי היא כמעשה של נתינת הגט מצידו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אמר לה\u0004 לאשתו \u0003\"כנסי שטר חוב זה\", או ששלפתו מאחוריו, קראתו והרי הוא גיטה\u0004 — \u0003אינו גט, עד שיאמר לה \"הא גיטיך\",\u0004 אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר: לעולם אינו גט, עד שיטלנו הימנה, ויחזור ויתננו לה, ויאמר לה \"הא גיטיך\".\u0004","כיוצא בו אם \u0003נתנו בידה והיא ישנה,\u0004 ואחר כך \u0003ניעורה וקוראה והרי הוא גיטה\u0004 — \u0003אינו גט, עד שיאמר לה \"הא גיטיך\",\u0004 אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר:\u0004 אינו גט \u0003עד שיטלנו הימנה, ויחזור ויתננו לה, ויאמר לה \"הא גיטיך\".\u0004","ומעירים \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמר מחלוקת זו בשני המקרים, \u0003דאי איתמר בהך קמייתא\u0004 \u0005[שאילו\u0006 היה \u0005נאמר רק בזו הראשונה],\u0006 היינו אומרים כך: \u0003בההיא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רבי, משום\u0004 ש\u0003בת איגרושי\u0004 \u0005[גירושין]\u0006 \u0003היא,\u0004 שהרי היא ערה ומבינה וראויה לקבל גט אף שלא פירש לה שזה גיטה, \u0003אבל\u0004 כאשר \u0003נתן בידה והיא ישנה דלאו\u0004 \u0005[שלא]\u0006 \u0003בת איגרושי\u0004 \u0005[גירושין]\u0006 \u0003היא,\u0004 שהרי עכשיו הריהי כחסרת דעת שאינה יכולה לקבל גט — \u0003אימא מודי ליה\u0004 \u0005[אמור,\u0006 ש\u0005מודה לו]\u0006 רבי \u0003לר' שמעון בן אלעזר\u0004 שנתינה ראשונה אינה נחשבת נתינה כלל, לכן הוצרך הדבר להיאמר שאף בזו רבי חולק עליו.","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואילו\u0006 היה \u0005נאמר\u0006 רק \u0005בזו\u0006 בישנה\u0005],\u0006 היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 שצריך לחזור ולתת לה את הגט, \u0003אבל בהך\u0004 \u0005[באחרת]\u0006 כשהיא ערה — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 שהוא \u0005מודה לו]\u0006 לרבי, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים.","\u0003אמר רבא: כתב לה גט ונתנו ביד עבדה\u0004 שהיה \u0003ישן ו\u0004היא \u0003משמרתו\u0004 — \u0003הרי זה גט,\u0004 שהעבד נחשב כקרקע השייכת לבעלים, והנותן לידו כנותן בחצרה. ואם היה עבדה \u0003ניעור\u0004 — \u0003אינו גט,\u0004 משום \u0003דהויא ליה\u0004 \u0005[שהרי הוא]\u0006 כ\u0003חצר המשתמרת שלא לדעתה\u0004 שאינה קונה לה, שהרי הוא שומר את עצמו.","ושואלים: אם \u0003ישן ומשמרתו\u0004 — \u0003הרי זה גט, אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003חצר מהלכת היא, וחצר מהלכת לא קנה!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003ישן שאני\u0004 \u0005[שונה],\u0006 שהרי עכשיו אינו מהלך, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: כל\u0004 מקרה \u0003שאילו\u0004 היה \u0003מהלך לא קנה,\u0004 גם אם הוא \u0003עומד\u0004 או \u0003יושב\u0004 — \u0003לא קנה!\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 זו שאמר רבא שהרי זה גט אינה אלא \u0003ב\u0004עבד \u0003כפות\u0004 (קשור) וישן, שאז הנותן בידו הרי זה כנותן בידה.","\u0003היתה\u0004 האשה \u0003עומדת\u0004 \u0003ברשות הרבים\u0004 ונטל הבעל גט \u0003וזרקו לה,\u0004 אם נפל הגט \u0003קרוב לה\u0004 — \u0003מגורשת,\u0004 אם נפל \u0003קרוב לו\u0004 — \u0003אינה מגורשת.\u0004 אם היה \u0003מחצה על מחצה\u0004 — \u0003מגורשת ואינה מגורשת. וכן לענין קדושין\u0004 שזרק לה.","\u0003וכן לענין החוב,\u0004 אם \u0003אמר לו בעל חובו\u0004 (המלווה) \u0003\"זרוק לי\u0004 פרעון \u0003חובי\"\u0004 \u0003וזרקו לו\u0004, אם נפל החוב \u0003קרוב למלוה\u0004 — \u0003זכה המלוה\u0004 ונפטר הלווה, גם אם משום מה לא הגיע אחרי כן הכסף לידי המלווה (כגון שנגנב או אבד הכסף לאחר הזריקה, לפני שנטלו המלווה). ואם היה \u0003קרוב ללוה\u0004 ואבד הכסף — \u0003הלוה\u0004 עדיין \u0003חייב.\u0004 ואם היה \u0003מחצה על מחצה\u0004 — \u0003שניהם יחלוקו. \u0004","ומבררים את האמור במשנה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 \u0003קרוב לה, והיכי דמי\u0004 \u0005[וכיצד בדיוק הוא]\u0006 \u0003קרוב לו? אמר רב:\u0004 אם נפל בתוך \u0003ארבע אמות שלה\u0004 — \u0003זהו קרוב לה,\u0004 בתוך \u0003ארבע אמות שלו\u0004 — \u0003זהו קרוב לו.\u0004","ושואלים: אם כן \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 \u0003מחצה על מחצה? אמר ר' שמואל בר רב יצחק: כגון שהיו שניהן עומדין ב\u0004תוך אותן \u0003ארבע אמות.\u0004","ושואלים: \u0003וליחזי הי מינייהו קדים\u0004 \u0005[ונראה מי מהם קדם]\u0006 לאותם ארבע אמות? שזה שקדם — ארבע אמות אלה נחשבות כשלו, והוא הקונה בהן. \u0003וכי תימא דאתו תרוייהו בהדי הדדי\u0004 \u0005[ואם תאמר שבאו שניהם בבת אחת],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא ש\u0003אי אפשר לצמצם\u0004 (לדייק) עד כדי כך שיהיו שני דברים בזמן אחד ממש, אלא ודאי אחד מהם קדם!","\u0003אלא אמר רב כהנא: הכא\u0004 \u0005[כאן]\u0006 \u0003בשמונה אמות מצומצמות\u0004 (במדוייק) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שארבע אמות שלה וארבע אמות שלו צמודים אלו לאלו,"],["\u0003וגט\u0004 היה \u0003יוצא מארבע אמות שלו לארבע אמות שלה,\u0004 שמקצתו כאן ומקצתו כאן, ולכן במקרה שכזה דינה כמגורשת ואינה מגורשת.","ושואלים: \u0003והא אגיד גביה\u0004 \u0005[והרי\u0006 הגט עדיין \u0005מחובר אליו],\u0006 שהרי מקצתו בתוך ארבע האמות שלו, ואין כאן איפוא נתינה שלימה ממנו! \u0003אלא\u0004 יש לחזור מהסבר זה, \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 הסבר אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשתי כיתי\u0004 (קבוצות) \u0003עדים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003אחת\u0004 מהן \u0003אומרת\u0004 שהיה הגט \u0003קרוב לו, ואחת\u0004 מהן \u0003אומרת\u0004 שהיה הגט \u0003קרוב לה,\u0004 וזהו \"מחצה על מחצה\" השנוי במשנתנו, לא במרחק אלא בדעות.","\u0003ר' יוחנן אומר\u0004 שלא כדברי רב ש\"קרוב\" במשנתנו פירושו ארבע אמות, שכן \u0003\"קרוב לה\" שנינו,\u0004 כלומר כל שהגט קרוב יותר אליה — \u0003אפילו\u0004 היה רחוק ממנה \u0003מאה אמה, ו\"קרוב לו\" שנינו\u0004 — \u0003אפילו מאה אמה.\u0004","ושואלים: אם כן לפירושו זה של ר' יוחנן \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 \u0003מחצה על מחצה? אמר רב שמן בר אבא: לדידי מיפרשא לה מיניה\u0004 \u0005[לי נתפרש הדבר ממנו]\u0006 מ\u0003ר' יוחנן\u0004 עצמו: אם \u0003הוא יכול לשומרו והיא אינה יכולה לשומרו\u0004 — \u0003זהו קרוב לו,\u0004 אם \u0003היא יכולה לשומרו והוא אינו יכול לשומרו\u0004 — \u0003זהו קרוב לה,\u0004 אם \u0003שניהם יכולין לשומרו,\u0004 או \u0003שניהם אין יכולין\u0004 — \u0003זהו מחצה על מחצה.\u0004","כאשר \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יונתן הכי\u0004 \u0005[כך]\u0006 באותו הסבר, \u0003אמר\u0004 בהתפעלות: \u0003ידעין חברין בבלאי לפרושי כי האי טעמא\u0004 \u0005[יודעים חברינו הבבליים לפרש כטעם זה]?\u0006 שהתפעל ממה שגם הם כיוונו לדעתו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' אליעזר אומר: כל\u0004 גט \u0003שהוא קרוב לה\u0004 יותר \u0003מ\u0004אשר \u0003לו, ובא כלב ונטלו\u0004 ולא הגיע הגט לידה — \u0003אינה מגורשת.\u0004 ויש לתהות: מדוע \u0003אינה מגורשת? כל היכי תינטריה ותיזיל\u0004 \u0005[כל כך,\u0006 כל הזמן, \u0005תשמרנו ותלך]?\u0006 שהרי כבר חלו הגירושין, ושוב אין האשה צריכה לשמור את הגט, וגם אם אבד לאחר מכן הרי היא מגורשת.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל שקרוב\u0004 הגט \u0003לה מלו, ואילו בא כלב ונטלו, והוא,\u0004 הבעל, היה \u0003יכול לשומרו והיא אינה יכולה לשומרו\u0004, במקרה כזה — \u0003אינה מגורשת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 מה שאמרו \"קרוב לה\" כוונתו \u0003כדי שתשוח\u0004 (תתכופף) \u0003ותטלנו, ואת\u0004 \u0005[ואתה]\u0006 \u0003לא תעביד עובדא\u0004 \u0005[תעשה מעשה]\u0006 להתיר אשת איש, ולפטור אותה מחליצה אם מת הבעל לאחר מכן, \u0003עד דמטי גיטא\u0004 \u0005[שיגיע הגט]\u0006 \u0003לידה\u0004 ממש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הוה עובדא הכי\u0004 \u0005[היה מעשה כך]\u0006 שהגיע הגט סמוך אליה, ואבד, \u0003ואצרכוה\u0004 \u0005[הצריכו\u0006 את האשה\u0005]\u0006 \u0003חליצה\u0004 מספק, ולא רצו לסמוך על מה שהיה הגט קרוב לה.","שנינו במשנה דין הזורק גט קרוב לו או לה, והוסיפה המשנה: \u0003וכן\u0004 הוא הדין \u0003לענין קדושין. אמר ר' אסי אמר ר' יוחנן: לגיטין אמרו\u0004 דין זה, \u0003ולא לדבר אחר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לר' אסי:\u0004 הלא במפורש שנינו: \u0003וכן לענין קדושין!\u0004 השיב לו: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין קידושין \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויצאה... והיתה\"\u0004 (דברים כד, ב) שהשווה הכתוב דין קידושין (\"והיתה\") לדין גירושין (\"ויצאה\"), אבל אין ללמוד מכאן לעניינים אחרים.","\u0003איתיביה\u0004 \u0005[הקשה לו],\u0006 הרי נאמר במשנה: \u0003וכן לענין החוב,\u0004 שאם אמר המלוה ללווה \u0003\"זרוק לי חובי\"\u0004 \u0003וזרקו לו,\u0004 אם נפל \u0003קרוב למלוה\u0004 — \u0003זכה הלוה\u0004 ואינו צריך עוד לשלם, אם נפל \u0003קרוב ללוה\u0004 ואבד החוב — \u0003הלוה חייב\u0004 לשלמו, \u0003מחצה על מחצה\u0004 — \u0003שניהם יחלוקו\u0004 והרי זה כגט וכקידושין!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המלווה ללווה במפורש \u0003\"זרוק לי חובי ותיפטר\u0004 על ידי כך \u0003\".\u0004 ומקשים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 צורך \u0005לומר\u0006 דבר זה\u0005]?\u0006 כיון שעשה תנאי מפורש בדבר, הרי בכגון זה הכל הולך אחר תנאו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המלווה ללווה \u0003\"זרוק לי חובי בתורת גיטין\",\u0004 כלומר, זרוק לי, שיהא בו אותו דין הקיים לגבי גט.","ומקשים: \u0003ואכתי מאי למימרא\u0004 \u0005[ועדיין מה\u0006 צורך \u0005לומר]\u0006 דבר זה, ולחדש בכך? הלא אמר המלווה במפורש \"בתורת גיטין\"! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 המלוה \u0005לומר לו,\u0006 ללווה\u0005]\u0006 \u0003משטה אני בך,\u0004 ששחקתי בך, ומה שאמרתי אין לו תוקף משפטי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם אמר שיזרקנו בתורת גיטין חל התנאי.","\u0003אמר רב חסדא:\u0004 היה \u0003גט בידה ומשיחה\u0004 (חוט) שהגט היה קשור בה היתה \u0003בידו,\u0004 שכך נתן לה את הגט, \u0003אם\u0004 עדיין \u0003יכול\u0004 הבעל על ידי החוט שבידו \u0003לנתקו\u0004 (למושכו) את הגט מידה \u0003ולהביאו אצלו\u0004 — \u0003אינה מגורשת, ואם לאו\u0004 \u0005[לא]\u0006 שכבר אינו יכול לעשות זאת — הריהי \u0003מגורשת.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שאף שנתן את הגט לידה אינה מגורשת? — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בגט שיהיה \u0003כריתות,\u0004 ניתוק גמור, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי עדיין יש לבעל אחיזה מסויימת בגט.","\u0003אמר רב יהודה:\u0004 אם \u0003היתה ידה עשויה כקטפרס\u0004 \u0005[כמדרון],\u0006 מונחת בשיפוע, \u0003וזרקו לה, אף על פי שהגיע גט לידה\u0004 — \u0003אינה מגורשת,\u0004 משום שהגט אינו יכול להישאר בתוך היד.","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הא כי נפיל\u0004 \u0005[הרי כאשר\u0006 הגט \u0005נופל\u0006 מידה\u0005]\u0006 — \u0003בארבע אמות דידה קא נפיל\u0004 \u0005[שלה הוא נופל]!\u0006 ומשיבים: מדובר בש \u0003לא נח\u0004 הגט בתוך ארבע אמותיה, אלא נפל רחוק יותר.","ושואלים: \u0003ותיגרש\u0004 \u0005[ותתגרש]\u0006 \u0003מ\u0004פני שהיה הגט ב\u0003אוירא\u0004 \u0005[באויר,\u0006 בחלל\u0005]\u0006 של \u0003ארבע אמות\u0004 שלה! ואם אין אתה אומר כן \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן אותה שאלה עקרונית \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' אלעזר: ארבע אמות\u0004 של אדם שאמרו לגבי דיני קנין, \u0003יש להן אויר או אין להן אויר?\u0004 כלומר, \u0003האם האויר שמעליהן נחשב כמותן?\u0004 \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן ש\u0003אין להן אויר!\u0004","ודוחים: לא ניתן לפתור מכאן את הבעיה העקרונית, שכן יש לומר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנחנו עוסקים]\u0006 — \u0003ב\u0004ש\u0003עומדת\u0004 האשה \u0003על גב\u0004 (סמוך) \u0003הנהר, דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003לאיבוד קאי\u0004 \u0005[הוא עומד]\u0006 שאם לא יישאר בידה ממש הרי הוא נופל למים, ובמקרה כזה לכל הדעות אין אויר ארבע אמות קונה לאדם."],["\u0003היתה\u0004 האשה \u0003עומדת על ראש הגג\u0004 והבעל למטה \u0003וזרקו לה, כיון\u0004 (משעה) \u0003שהגיע\u0004 הגט \u0003לאויר\u0004 (חלל) \u0003הגג\u0004 — \u0003הרי זו מגורשת.\u0004 היה \u0003הוא מלמעלה\u0004 (על הגג) \u0003והיא מלמטה, וזרקו לה, כיון שיצא מרשות הגג,\u0004 גם אם \u0003נמחק או נשרף\u0004 לפני שנפל לקרקע — \u0003הרי זו מגורשת.\u0004","ושואלים: מדוע כשהגיע הגט לאוויר הגג הריהי מגורשת? \u0003והא\u0004 \u0005[והרי]\u0006 אוויר הגג \u0003לא מינטר\u0004 \u0005[נשמר],\u0006 שהרי הגט הנמצא בו יכול לעוף למקום אחר על ידי הרוח, והרי זה בגדר חצר שאינה משתמרת שאינה קונה! \u0003אמר רב יהודה אמר שמואל: בגג שיש לו מעקה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 כאן, ומשום כך הריהו כחצר המשתמרת, שהגט אינו יכול לעוף משם.","\u0003עולא בר מנשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003אבימי אמר\u0004 תירוץ אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 שנמצא הגט \u0003בפחות משלשה\u0004 טפחים \u0003סמוך ל\u0004רצפת ה\u0003גג עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ש\u0003כל פחות משלשה סמוך לגג\u0004 — \u0003כגג דמי\u0004 \u0005[נחשב],\u0006 לפי הכלל שכל הנמצא תוך שלושה טפחים לדבר אחר הריהו כלבוד = צמוד.","שנינו במשנתנו: היה \u0003הוא\u0004 הבעל \u0003מלמעלה\u0004 והיא, האשה, מלמטה וזרקו לה — הרי זו מגורשת. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בדרך זו הגט \u0003לא מינטר\u0004 \u0005[שמור]\u0006 שהרי הרוח יכולה לשאת את הגט אל מחוץ לחצר! \u0003אמר רב יהודה אמר שמואל:\u0004 מדובר כאן \u0003כגון שהיו מחיצות התחתונות\u0004 של החצר \u0003עודפות\u0004 (גבוהות יותר) \u0003על העליונות\u0004 של מעקה הגג, שבהכרח יפול הגט לתוך החצר.","\u0003וכן אמר ר' אלעזר אמר ר' אושעיא: כגון שהיו מחיצות התחתונות עודפות על העליונות. וכן אמר עולא אמר ר' יוחנן: כגון שהיו מחיצות התחתונות עודפות על העליונות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לעולא: כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 הולכת הלכה זו שעצם כניסת הגט לרשות האשה, אף שאבד לפני שנח על הקרקע, נחשבת כנתינה — האם \u0003כ\u0004דעתו של \u0003רבי,\u0004 ש\u0003אמר\u0004 לענין הוצאה מרשות לרשות בשבת: \u0003קלוטה,\u0004 כלומר, מה שעובר באויר של רשות אחרת אף שאינו נח בתוכה, באותה שעה הוא \u0003כמי שהונחה דמיא\u0004 \u0005[נחשבת]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על רבי, \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003רבי אלא לענין שבת,\u0004 שאין אומרים שקלוטה נחשבת כמונחת, משום שהם סבורים שלענין דיני שבת צריך החפץ להיות מונח בפועל באותה רשות אליה נכנס. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 רק \u0003משום אינטורי\u0004 \u0005[שמירה]\u0006 \u0003הוא, והא קא מינטר\u0004 \u0005[והרי הוא שמור]\u0006 גם בזמן שהוא באוויר המחיצות.","\u0003וכן אמר ר' אסי אמר ר' יוחנן:\u0004 מדובר כאן \u0003כגון שהיו מחיצות התחתונות עודפות על העליונות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרבי אסי: כמאן?\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 הולכת הלכה זו — \u0003כ\u0004שיטת \u0003רבי,\u0004 שאמר: \u0003קלוטה\u0004 \u0003כמי שהונחה דמיא\u0004 \u0005[נחשבת]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו],\u0006 על \u0003רבי\u0004 — \u0003אלא לענין שבת.\u0004 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 רק \u0003משום אינטורי\u0004 \u0005[שמירה]\u0006 \u0003הוא, והא קא מינטר\u0004 \u0005[והרי הוא שמור].\u0006","שנינו במשנה שאם לאחר שיצא הגט מרשות הגג \u0003נמחק\u0004 לפני שהגיע לידה — בכל זאת הריהי מגורשת בו. \u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו אלא שנמחק דרך ירידה,\u0004 כאשר היה הגט בשעה שנמחק כבר מעבר למעקה הגג, שהוא יורד אז לתוך רשותה, \u0003אבל\u0004 אם \u0003נמחק דרך עלייה,\u0004 כאשר זרקו כלפי מעלה כדי להוציאו מן הגג, שיפול אחר כך למטה — \u0003לא.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 עד שלא החל לרדת מוגדר הגט כמי ש\u0003לא למינח קאי\u0004 \u0005[להנחה\u0006 הוא \u0005עומד]\u0006 אלא לעוף למקום אחר, ובאותה שעה עדיין אינו נחשב כמונח בחצר.","שנינו במשנה שאם \u0003נשרף\u0004 הגט לאחר שיצא מרשות הגג — הריהי מגורשת בו. ואף כאן \u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו אלא שקדם\u0004 זריקת הגט \u0003לדליקה, אבל\u0004 אם \u0003קדמה\u0004 ה\u0003דליקה ל\u0004זריקת ה\u0003גט\u0004 — \u0003לא\u0004 מגורשת האשה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לשריפה קאזיל\u0004 \u0005[הוא הולך]\u0006 ולא היתה כאן נתינה כלל.","\u0003אמר רב חסדא: רשויות חלוקות בגיטין,\u0004 שאם יש רשויות שונות באותה רשות, כגון בית וחצר, או חצר וגג — אין הן נחשבות כרשות אחת לענין גט, וכל אחת עומדת לעצמה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לרבא: מנא ליה לסבא הא\u0004 \u0005[מנין לו לזקן,\u0006 לרב חסדא, דבר \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 ששנינו בה: \u0003היתה עומדת על ראש הגג וזרקו לה, כיון שהגיע\u0004 ה\u0003גט לאויר הגג\u0004 — \u0003הרי זו מגורשת.\u0004","ויש לברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בגג דידה\u0004 \u0005[שלה]\u0006 \u0003וחצר ד\u0004\u0003ידה\u0004 \u0005[שלה],\u0006 \u0003למה לי\u0004 שיגיע הגט ל\u0003אויר הגג\u0004 על מנת שתתגרש בו? אפילו נשאר הגט בחצר מתגרשת בו, שהרי זו חצירה.","\u0003אלא\u0004 תאמר שמדובר \u0003בגג דידיה\u0004 \u0005[שלו]\u0006 \u0003וחצר דידיה\u0004 \u0005[שלו],\u0006 ואולם, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003הגיע\u0004 הגט \u0003לאויר הגג מאי הוי\u0004 \u0005[מה היה\u0006 בכך] ולמה מתגרשת בו? הרי עדיין לא יצא הגט מרשותו!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר במקרה זה \u0003בגג דידה\u0004 \u0005[שלה]\u0006 \u0003וחצר דידיה\u0004 \u0005[שלו].\u0006 ואולם \u0003אימא\u0004 \u0005[אמור]\u0006 את ה\u0003סיפא\u0004 \u0005[הסוף]\u0006 של המשנה, ששנינו: \u0003הוא מלמעלה והיא מלמטה וזרקו לה, כיון שיצא מרשות הגג, נמחק או נשרף\u0004 — \u0003הרי זו מגורשת. ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בגג דידה\u0004 \u0005[שלה]\u0006 \u0003וחצר דידיה\u0004 \u0005[שלו]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן היא \u0003מגורשת? אלא\u0004 צריך לומר שמדובר \u0003בגג דידיה\u0004 \u0005[שלו]\u0006 \u0003וחצר דידה\u0004 \u0005[שלה].\u0006","ומעתה יש לתמוה: \u0003רישא\u0004 \u0005[ראשה\u0006 של המשנה] בגג \u0003דידה\u0004 \u0005[שלה]\u0006 \u0003וחצר דידיה\u0004 \u0005[שלו],\u0006 \u0003סיפא\u0004 \u0005[סופה\u0006 של המשנה\u0005]\u0006 \u0003בגג דידיה\u0004 \u0005[שלו]\u0006 \u0003וחצר ד\u0004\u0003ידה\u0004 \u0005[שלה]?\u0006 כיצד דנה אותה משנה בשני דינים כאשר כל אחד עוסק במציאות שונה ואינה מזכירה את הדבר?","\u0003אלא\u0004 יש להציע פתרון אחר: \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר שגם הגג וגם החצר הם שלו, ומדובר \u0003דאושלה\u0004 \u0005[שהשאילה]\u0006 \u0003מקום\u0004 אחד ברשותו שתקבל בו את גיטה ובו עומדת האשה, במקרה הראשון השאיל לה את הגג ובמקרה השני השאיל לה את החצר, ולפיכך רק משעה שהגיע לאותה רשות הריהי מגורשת, \u0003דחד מקום מושלי אינשי\u0004 \u0005[שמקום אחד משאילים אנשים],\u0006 \u0003תרי\u0004 \u0005[שתי]\u0006 \u0003מקומות לא מושלי אינשי\u0004 \u0005[משאילים אנשים].\u0006 ומכאן למד רב חסדא שכאשר יש רשויות חלוקות אין זה נחשב למקום אחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר חמא לרבא: \u0003מידי איריא\u0004 \u0005[וכי שייכים\u0006 הדברים\u0005]?\u0006 \u0003דלמא הא כדאיתא והא כדאיתא\u0004 \u0005[שמא זה כעניינו וזה כעניינו];\u0006 \u0003רישא\u0004 \u0005[בתחילת\u0006 המשנה\u0005]\u0006 מדובר באמת \u0003בגג דידה\u0004 \u0005[שלה]\u0006 \u0003וחצר דידיה\u0004 \u0005[שלו],\u0006 \u0003סיפא\u0004 \u0005[סופה]\u0006 \u0003בגג דידיה\u0004 \u0005[שלו]\u0006 \u0003וחצר ד\u0004\u0003ידה\u0004 \u0005[שלה],\u0006 שפעמים מדברת המשנה בשני מקרים שונים ואין מכאן הוכחה גמורה.","\u0003אמר רבא: שלש מדות בגיטין\u0004 שיש בהם הבדל בין גט לדיני שבת. \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבי: קלוטה כמי שהונחה, ופליגי רבנן עליה\u0004 \u0005[וחולקים חכמים עליו],\u0006 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים שנחלקו דווקא \u0003לענין שבת, אבל הכא\u0004 \u0005[כאן]\u0006 רק \u0003משום אינטורי\u0004 \u0005[שמירה]\u0006 \u0003הוא, והא מינטר\u0004 \u0005[והרי\u0006 הוא \u0005שמור].\u0006","\u0003והא\u0004 \u0005[וזו]\u0006 ש\u0003אמר רב חסדא\u0004 בהלכות שבת: אם \u0003נעץ קנה ברשות היחיד ובראשו טרסקל\u0004 (סל) \u0003וזרק\u0004 חפץ מרשות הרבים \u0003ונח על גביו, אפילו\u0004 אם היה הקנה \u0003גבוה מאה אמה\u0004 — \u0003חייב, לפי שרשות היחיד עולה עד לרקיע,\u0004 ונמצא שהחפץ נח ברשות היחיד — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לענין שבת,\u0004 שם יש הגדרה של רשויות באופן אחר, לפי המחיצות שיש להן ולפי דרך שימושן. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 רק \u0003משום אינטורי\u0004 \u0005[שמירה]\u0006 \u0003הוא, והא\u0004 \u0005[והרי]\u0006 הוא \u0003לא מינטר\u0004 \u0005[שמור].\u0006"],["\u0003ו\u0004הדבר השלישי, הלכה \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: לא יעמוד אדם\u0004 בשבת \u0003בגג זה ויקלוט מי גשמים מגגו של חבירו\u0004 אם אין עירוב, \u0003שכשם שדיורין\u0004 (דיירים) \u0003חלוקין מלמטה,\u0004 שכל אחד מהם יש לו רשות לעצמו, ומדברי חכמים אסור להעביר אף מרשות יחיד לרשות יחיד אחרת בלי עירוב, \u0003כך דיורין חלוקין מלמעלה,\u0004 שאף הגגות, למרות שאינם נפרדים זה מזה לגמרי, ואין דרים בהם, נחשבים כל אחד כרשות לעצמה.","\u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לענין שבת, אבל לענין גט,\u0004 אם נפל לגג אחר הסמוך לגג שהשאיל לה לצורך זה — הריהי מגורשת, כיון שהסיבה שאינה מתגרשת אם נפל הגט למקום אחר של הבעל \u0003משום קפידא\u0004 \u0005[הקפדה]\u0006 \u0003הוא, וכולי האי לא קפדי אינשי\u0004 \u0005[וכל כך אין אנשים מקפידים]\u0006 ולא איכפת להם שמשתמשים שימוש ארעי כזה בגגם.","\u0003אמר אביי:\u0004 היו \u0003שתי חצרות זו לפנים מזו\u0004 (זו בתוך זו), והיתה החצר ה\u0003פנימית שלה וחיצונה שלו,\u0004 \u0003ומחיצות החיצונות עודפות\u0004 בגובהן \u0003על הפנימיות, וזרקו לה\u0004 את הגט מחצירו לחצירה, \u0003כיון שהגיע לאויר\u0004 שמעל החצר הפנימית שלה, אף שעדיין לא נכנס בתוך האוויר של גובה מחיצותיה, אבל כבר נמצא בתוך גובה \u0003מחיצות החיצונה\u0004 — \u0003הרי זו מגורשת,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — חצר \u0003פנימית גופה\u0004 \u0005[עצמה]\u0006 \u0003במחיצות החיצונה קא מינטרה\u0004 \u0005[נשמרת]\u0006 ויש להחשיב מה שנשמר על ידי המחיצות החיצוניות כשייך לחצר הפנימית, אם הגיע לאווירה.","\u0003מה שאין כן בקופות\u0004 (סלים), אם היו \u0003שתי קופות זו בתוך זו\u0004 ברשות שאינה של שניהם, \u0003פנימית שלה וחיצונה שלו, וזרקו לה, אפילו הגיע\u0004 הגט \u0003לאויר\u0004 הקופה ה\u0003פנימית\u0004 ונשרף או נלקח לפני שנח בתוכה — \u0003אינה מגורשת,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0005—\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא נח\u0004 עדיין הגט בקופה, ובמקרה זה אף אין אומרים שמחיצות הקופה החיצונית מועילות גם לקופה הפנימית.","ותוהים: \u0003וכי נח מאי הוי\u0004 \u0005[וכאשר ינוח\u0006 שם \u0005מה יהיה]?\u0006 הלא עדיין \u0003כליו של לוקח\u0004 (קונה) \u0003ברשות מוכר הוא,\u0004 שהרי הקופה שלה מצויה בתוך הקופה שלו, שהיא רשותו, וכיצד היא יכולה לקנות במה שנפל לתוך הקופה שלה?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בקופה שאין לה שוליים\u0004 (תחתית), וכיון שאין לה לקופה החיצונית תחתית, נמצא שהפנימית מונחת על גבי קרקע, ולא בתוך הקופה החיצונה, ולכשייכנס הגט בקופה הפנימית אכן תהיה מגורשת.","\u0003בית שמאי אומרים: פוטר\u0004 (מגרש) \u0003אדם\u0004 את \u0003אשתו בגט ישן, ובית הלל אוסרין. ואיזהו גט ישן\u0004 — \u0003כל שנתייחד עמה מאחר\u0004 (לאחר) \u0003שכתבו לה.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון, \u0005נחלקו]?\u0006 — \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שיש לפסול גט זה משום \u0003גזרה שמא יאמרו\u0004 האנשים \u0003גיטה קודם לבנה,\u0004 שהרי יתכן שיתן לה את הגט זמן רב לאחר שכתבו, ובינתיים יוולדו לה ילדים ממנו, ועלולים אנשים לומר שנתגרשה באותו זמן הכתוב בגט — לפני שנולדו הילדים, ומזנות נולדו.","\u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003גזרה שמא יאמרו גיטה קודם לבנה,\u0004 ולכן יש לפסול כל גט שהתייחדה האשה עם בעלה לאחר כתיבתו.","\u0003אמר ר' אבא אמר שמואל:\u0004 אף לדעת בית הלל, \u0003אם נישאת\u0004 האשה על סמך גט ישן, שנתנו לה בעלה בלא לשאול דעת חכמים — \u0003לא תצא,\u0004 שאין גזירה זו חמורה כל כך כדי לבטל את הגט גם במקרה שכזה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 ש\u0003אמר ר' אבא אמר שמואל: אם נתגרשה\u0004 בגט כזה, שלא שאל הבעל את דעת החכמים, ונתנו לה — יכולה האשה אף ש\u0003תינשא לכתחלה\u0004 על סמך גט זה, ואין מחייבים אותה להמתין עד שיכתוב לה הבעל גט חדש.","\u0003כתב\u0004 בגט תאריך \u0003לשום\u0004 (לשם) למנין שנות \u0003מלכות שאינה הוגנת\u0004 (מלכות אחרת שאינה שולטת באותו מקום), או כתב \u0003לשום מלכות מדי,\u0004 או \u0003לשום מלכות יון\u0004 שכבר בטלו מן העולם, או כתב תאריך \u0003ל\u0004מנין שנות \u0003בנין הבית\u0004 (בית המקדש), או \u0003לחורבן הבית,\u0004 בכל אלה, כיון שהיתה המלכות מקפידה שיכתבו בשטרות את התאריך הרשמי שלה, תיקנו חכמים שיעשו כך בגיטין, וכל המשנה עבר על תקנת חכמים בגיטין ופסל את הגט.","וכן אם \u0003היה במזרח וכתב\u0004 שמקום הגט \u0003במערב,\u0004 או היה \u0003במערב וכתב\u0004 שמקום הגט \u0003במזרח\u0004 — בכל אלה הגט פסול, ואם גירשה בגט זה ונישאה לאחר — \u0003תצא מזה ומזה,\u0004 גם מבעלה הראשון וגם מן השני, \u0003וצריכה גט מזה ומזה.\u0004","\u0003ואין לה לא כתובה ולא פירות\u0004 של נכסיה שאכל הבעל, \u0003ולא\u0004 טענה ל\u0003מזונות, ולא\u0004 ל\u0003בלאות\u0004 (בלאי) של בגדיה שהשתמש בהם שיחזירם לה, \u0003לא על זה,\u0004 הבעל הראשון, \u0003ולא על זה,\u0004 הבעל השני.","\u0003אם נטלה\u0004 דברים אלה \u0003מזה ומזה\u0004 — \u0003תחזיר\u0004 מה שנטלה. \u0003והולד\u0004 שנולד — \u0003ממזר מזה ומזה. ולא זה וזה,\u0004 לא בעל ראשון ולא שני \u0003מטמאין לה\u0004 במותה, ככל בעל על אשתו, אם היו כהנים, \u0003ולא זה וזה זכאין לא במציאתה ולא במעשה ידיה ולא בהפרת נדריה.\u0004","ואם \u0003היתה בת ישראל\u0004 הרי היא \u0003נפסלת\u0004 על ידי כך \u0003מן הכהונה\u0004 משום איסור זונה,"],["ואם היתה \u0003בת לוי\u0004 — הריהי נפסלת בכך \u0003מן המעשר\u0004 הניתן ללויים, ואם היתה \u0003בת כהן\u0004 — הריהי נפסלת \u0003מן התרומה\u0004 אף כשחוזרת לבית אביה הכהן.","\u0003ואין יורשין של\u0004 בעל \u0003זה ויורשין של\u0004 בעל \u0003זה\u0004 \u0003יורשים\u0004 את \u0003כתובתה\u0004 אם מתה. \u0003ואם מתו\u0004 הבעלים — אחד מ\u0003אחיו של זה ו\u0004אחד מ\u0003אחיו של זה חולצין\u0004 לה, שהרי היו בה קידושין מן השני, \u0003ולא מייבמין.\u0004","ועוד הלכה דומה הקשורה בכתיבה לא נכונה של גט: אם \u0003שינה\u0004 את \u0003שמו\u0004 וכתב שם אחר בגט, או שינה את \u0003שמה,\u0004 או שינה את \u0003שם עירו\u0004 או את \u0003שם עירה\u0004 והלכה ונישאה לאחר על סמך גט זה — \u0003תצא מזה ומזה,\u0004 \u0003וכל הדרכים האלו\u0004 של קנסות שמנינו שייכות \u0003בה\u0004 גם בגט שכזה.","אגב כך מביאים עוד דין אחר: \u0003כל עריות שאמרו\u0004 שאם מת אחיו בלא בנים, והניח אלמנה האסורה עליו באיסור ערווה (כגון שהיא אחות אשתו), לא זו בלבד שלא חלה עליה חובת יבום, אלא גם \u0003צרותיהן\u0004 (נשותיו האחרות של האח שמת) \u0003מותרות\u0004 ואין בהן דין יבום וחליצה.","אם \u0003הלכו הצרות האלו ונישאו\u0004 לאחר בלא חליצה, \u0003ונמצאו אלו\u0004 העריות \u0003איילונית,\u0004 ובכך נתברר למפרע שלא היו נישואיהן לאחיו נישואין מתחילה, ומשום כך צרות אלה לא נפטרו מן היבום (משום \"צרת ערוה\") אלא היתה עליהן חובת יבום, והיו אסורות להינשא לאדם אחר בלא חליצה — \u0003תצא מזה,\u0004 מן הבעל שנישאה לו \u0003ומזה,\u0004 שאסורה ליבם, \u0003וכל הדרכים האלו\u0004 ששנינו לעיל, שייכות \u0003בה.\u0004","וכן \u0003הכונס\u0004 (נושא) \u0003את יבמתו, והלכה צרתה ונישאת לאחר, ונמצאת זו\u0004 היבמה שכנסוה \u0003שהיתה איילונית,\u0004 שלא חל עליה כלל דין יבום וממילא אין יבומה פוטר את צרתה — \u0003תצא\u0004 הצרה \u0003מזה\u0004 מבעלה \u0003ומזה,\u0004 שאסורה ליבם, \u0003וכל הדרכים האלו\u0004 ששנינו לעיל, שייכות \u0003בה.\u0004","ועוד דין דומה, \u0003כתב סופר גט לאיש\u0004 (עבור האיש) שיתן אותו לאשתו בגירושיה, \u0003ושובר\u0004 (קבלה) \u0003לאשה,\u0004 שכאשר תקבל מבעלה את כתובתה תיתן לו שובר שקיבלה ממנו את הכתובה, \u0003וטעה\u0004 הסופר \u0003ונתן\u0004 את ה\u0003גט לאשה ו\u0004את ה\u0003שובר לאיש,\u0004 והם לא ידעו מה היה כתוב בשטרות שבידיהם \u0003ונתנו זה לזה\u0004 את מה שקיבלו מהסופר, ונמצא שהאשה נתנה לבעלה את הגט, והבעל נתן לאשה את השובר, ואם כן לא היו כאן גירושין כלל,","\u0003ולאחר זמן הרי הגט יוצא מיד האיש ושובר מיד האשה,\u0004 אם נישאה האשה לאחר — \u0003תצא מזה ומזה, וכל הדרכים האלו בה.\u0004","\u0003ר' אלעזר אומר: אם לאלתר\u0004 (מייד) \u0003יצא\u0004 הגט מתחת ידי הבעל — \u0003אין זה גט,\u0004 שהרי ברור שלא נתנו לה, אבל \u0003אם לאחר זמן יצא\u0004 — \u0003הרי זה גט, לא כל הימנו\u0004 (אין זה בכוחו) \u0003מן\u0004 (של) הבעל \u0003הראשון\u0004 \u0003לאבד זכותו של\u0004 הבעל ה\u0003שני\u0004, ואנו אומרים שמן הסתם מסר לה את הגט כדינו, ואחר כך נזדמן שחזר ולקחו ממנה.","שנינו במשנה שאחד מן הדברים הפוסלים את הגט הוא אם כתבו לשם מלכות שאינה הוגנת. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מלכות שאינה הוגנת\"?\u0004 ומשיבים: \u0003מלכות הרומיים,\u0004 והוא כתב את הגט במדינה כגון בבל, שאין הרומאים מושלים בה. \u0003ואמאי קרי לה\u0004 \u0005[ומדוע קוראים לה]\u0006 \u0003\"מלכות שאינה הוגנת\"?\u0004 — \u0003משום\u0004 ש\u0003אין להם לא כתב\u0004 משלהם \u0003ולא לשון\u0004 משלהם, אלא לקחו אותם מאומות אחרות.","\u0003אמר עולא: מפני מה תקינו\u0004 \u0005[תיקנו]\u0006 חכמים שיכתבו בזמן הגט את שנות ה\u0003מלכות בגיטין\u0004 — \u0003משום שלום מלכות,\u0004 שהמלכות מקפידה שהשטרות החשובים הניתנים בה יהיו כתובים בתאריך של אותה מלכות.","ותוהים: \u0003ו\u0004כי בגלל תקנה שתיקנו חכמים רק \u0003משום שלום מלכות,\u0004 ואירע שלא כתב כהוגן, יחמירו כל כך ש\u0003תצא\u0004 האשה מן הבעל \u0003והולד ממזר?!\u0004","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ר' מאיר\u0004 (שסתם משנה היא שיטת ר' מאיר) הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב המנונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: אומר היה ר' מאיר: כל המשנה ממטבע\u0004 (מתבנית, נוסח) \u0003שטבעו חכמים בגיטין,\u0004 אפילו אם עשה שינוי בלתי חשוב — אינו גט, ואם נישאה האשה על סמך גט כזה — \u0003הולד ממזר.\u0004","שנינו במשנה: אם כתב גט \u0003לשום מלכות יון\u0004 וכו' — הגט פסול. ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 להיאמר גם הלכה זו וגם שאר ההלכות, \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 דין זה רק בשינה לשם \u0003מלכות שאינה הוגנת,\u0004 היינו אומרים שהגט נפסל \u0003משום דמליכא\u0004 \u0005[ש\u0006מלכות זו \u0005מולכת]\u0006 כעת, והמלכות שהוא נמצא בה מקפידה על כך. \u0003אבל מלכות מדי ומלכות יון\u0004 — אין להחמיר בדבר, משום ש\u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 שבטלו מלכויות אלה ואין השלטונות מקפידים על הזכרתן בשטר.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 דין זה רק ב\u0003מלכות מדי ומלכות יון,\u0004 יש להבין את ההקפדה שבדבר \u0003משום דמלכותא הוו\u0004 \u0005[שמלכויות היו],\u0006 ומקפידים השלטונות על איזכור בשטר של מלכות אחרת, \u0003אבל\u0004 אם כתב בגט את התאריך מזמן \u0003בנין הבית\u0004 היינו אומרים \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ואין מקפידים על כך, ולכן השמיע שאף בזה יש להחמיר.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק במקרה שכתב ל\u0003בנין הבית,\u0004 היינו סבורים שגם על כך מקפידים, משום \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 השלטונות: \u0003קמדכרי שבחייהו\u0004 \u0005[מזכירים\u0006 את \u0005שיבחם]\u0006 של ישראל, במקום כבוד המלכות המושלת, \u0003אבל חורבן הבית דצערא\u0004 \u0005[שצער]\u0006 \u0003הוא\u0004 לנו — \u0003אימא\u0004 \u0005[אמור]\u0006 שלא מקפידה מלכות על כך, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה כל הדוגמאות הללו.","שנינו במשנה בין הגיטין הפסולים: \u0003היה במזרח וכתב\u0004 הסופר בגט \u0003במערב.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 זה שמדובר בו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששינה את מקומו של \u0003בעל, היינו\u0004 \u0005[הרי זה]\u0006 כמו שמפרש הלאה במשנה: \u0003שינה שמו ושמה, שם עירו ושם עירה!\u0004","\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר ב\u0003סופר\u0004 ששינה את מקום כתיבת הגט, ולא כתב מקום שהיה בו בזמן כתיבתו. \u0003כדאמר להו\u0004 \u0005[כמו שהיה אומר להם]\u0006 \u0003רב לספריה\u0004 \u0005[לסופריו],\u0006 \u0003וכן אמר להו\u0004 \u0005[\u0006היה \u0005אומר להם]\u0006 \u0003רב הונא לספריה\u0004 \u0005[לסופריו]:\u0006 \u0003כי יתביתו\u0004 \u0005[כאשר אתם יושבים]\u0006 \u0003ב\u0004מקום הנקרא \u0003שילי, כתובו\u0004 \u0005[כתבו]\u0006 את מקום השטר \u0003בשילי,\u0004 \u0003ואף על גב דמימסרן לכו מילי\u0004 \u0005[ואף על פי שנמסרו לכם הדברים]\u0006 במקום אחר, כגון \u0003ב\u0004מקום הנקרא \u0003היני, וכי יתביתו\u0004 \u0005[וכאשר אתם יושבים]\u0006 \u0003בהיני כתובו\u0004 \u0005[כתבו]\u0006 \u0003בהיני,\u0004 \u0003ואף על גב דמימסרן לכו מילי\u0004 \u0005[ואף על פי שנמסרו לכם הדברים]\u0006 \u0003בשילי,\u0004 שיש להקפיד ולכתוב את מקום השטר בדיוק במקום שנכתב, ולא במקום אחר, שאם לא כן נחשב הדבר כשינוי.","\u0003אמר רב יהודה אמר שמואל:\u0004"],["\u0003זו דברי ר' מאיר\u0004 שמקפיד על שלום מלכות בגט, \u0003אבל חכמים אומרים: אפילו לא כתב\u0004 תאריך בגט \u0003אלא לשם,\u0004 על פי זמן שררתו של \u0003סנטר\u0004 (ממונה על שמירה) \u0003שבעיר\u0004 — \u0003הרי זו מגורשת,\u0004 שאין כל חשיבות לשם מי נכתב התאריך.","מסופר: \u0003ההוא גיטא דהוה כתיב ביה\u0004 \u0005[גט אחד שהיה כתוב בו]\u0006 \u0003לשם איסטנדרא\u0004 \u0005[המושל]\u0006 של העיר \u0003בשכר\u0004 שנקבו את התאריך הכתוב בו לפי זמן הממשלה שלו, \u0003שלחה\u0004 את הבעיה הזו \u0003רב נחמן בר רב חסדא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבה: כי האי גוונא מאי\u0004 \u0005[כגון זה מה]\u0006 הדין?","\u0003שלח ליה\u0004 \u0005[לו]\u0006 כתשובה: \u0003בהא\u0004 \u0005[בזו]\u0006 \u0003אפילו ר' מאיר מודי\u0004 \u0005[מודה]\u0006 שהגט כשר, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003מאותה מלכות הוא,\u0004 ואין מושל המלכות מקפיד בדבר זה.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 הדבר \u0003מסנטר שבעיר?\u0004 ומשיבים: \u0003התם זילא להו מילתא\u0004 \u0005[שם מזולזל להם הדבר]\u0006 שכותב לשם פקיד קטן, \u0003הכא שביחא להו מילתא\u0004 \u0005[כאן משובח להם הדבר]\u0006 שהוא כותב לשמו של מושל חשוב.","\u0003אמר ר' אבא אמר רב הונא אמר רב\u0004 משנתנו \u0003זו דברי ר' מאיר\u0004 היא, שהוא מחמיר בגט זה וסבור שהוולד ממזר, \u0003אבל חכמים אומרים: הולד כשר. ומודים חכמים לר' מאיר, שאם שינה\u0004 בגט את \u0003שמו\u0004 או את \u0003שמה,\u0004 או את \u0003שם עירו\u0004 או את \u0003שם עירה\u0004 — \u0003שהולד ממזר.\u0004","\u0003אמר רב אשי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה. ששנינו במשנתנו: \u0003שינה שמו ושמה, שם עירו ושם עירה\u0004 ונישאה לאחר על פי גט זה — \u0003תצא מזה ומזה, וכל הדרכים האלו\u0004 של קנסות שקונסים אשת איש שנישאה לאחר, שנימנו למעלה, קיימים \u0003בה.\u0004","ויש לברר \u0003הא מאן קתני לה\u0004 \u0005[\u0006הלכה \u0005זו מי שנה אותה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ר' מאיר\u0004 הוא ששנה אותה — אם כן \u0003ליערבינהו וליתנינהו\u0004 \u0005[שיערב וישנה\u0006 את הדברים\u0005]\u0006 גם בשינוי מלכות וגם בשינוי שם, כהלכה אחת! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזו היא שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא, שעד כאן הובאו במשנתנו דברי ר' מאיר, ומכאן הוסיפו את דברי חכמים בשינוי עיקרי כזה שאף לדעתם פוסל את הגט.","שנינו במשנה: \u0003כל עריות שאמרו\u0004 שהן מותרות שנישאו צרותיהן לאחרים, ונתברר שלא היו בגדר צרת ערווה — הרי אלו יוצאות מבעליהן וכו'. ומעירים: יש לדייק בלשון המשנה שדווקא אם \u0003נישאו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חלים עליהן דינים אלה, אבל אם \u0003זינו\u0004 אותן צרות, שנתברר שהיו זקוקות ליבם — \u0003לא,\u0004 שאין חלים עליהן קנסות אלה.","\u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא זו קושיה חמורה]\u0006 על שיטת \u0003רב המנונא,\u0004 ש\u0003אמר רב המנונא: שומרת יבם\u0004 (מצפה ליבם) \u0003שזינתה\u0004 שכיון שהיתה זקוקה ליבום הריהי כעין אשת איש שזנתה תחת בעלה ו\u0003אסורה ליבמה!?\u0004","ודוחים: \u0003לא,\u0004 אין מכאן הוכחה, שכן אפשר לומר כך במשנה: \u0003נישאו\u0004 — \u0003והוא הדין לזינו, והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003נישאו\u0004 — \u0003לישנא מעליא נקט\u0004 \u0005[לשון מעולה,\u0006 נקיה, \u0005תפס]\u0006 ולא רצה לדבר על זנות.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שמועה זו באופן אחר: מה שאמרו במשנה שצרת ערווה שנישאת ונתברר שהיתה הערווה איילונית שקונסים אותה — \u0003נישאו והוא הדין לזינו.\u0004","ושואלים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שדבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב המנונא,\u0004 ש\u0003אמר רב המנונא: שומרת יבם שזינתה\u0004 — \u0003אסורה ליבמה!?\u0004","ודוחים: \u0003לא, נישאו דווקא\u0004 הן שאסורות \u0003משום דמיחלפא\u0004 \u0005[שמתחלפת]\u0006 היבמה \u0003באשה שהלך בעלה למדינת הים\u0004 ונישאה לאחר, שאז ודאי אסורה לראשון ולשני, וכיוצא בה גזרו ביבמה שנישאה. אבל בזנות, שאין הדברים דומים — אין לגזור.","שנינו במשנה \u0003הכונס את יבמתו\u0004 ונמצא שהיתה איילונית, ובינתיים נישאה צרתה לאחר בלא חליצה שתצא מזה ומזה וכו'. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לומר גם את ההלכה הזו, אף שלכאורה ענין אחד הוא עם ההלכה הקודמת לה; \u0003דאי אשמעינן בהך קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005בזו הראשונה],\u0006 בצרת ערווה, היינו אומרים שדין זה הוא \u0003משום\u0004 ש\u0003לא איקיים\u0004 \u0005[התקיימה]\u0006 \u0003מצות יבום\u0004 כלל, שבמה שנישאת לאחר נמצא שליבם לא היה כלל את מי לייבם.","\u0003אבל הכא דאיקיים\u0004 \u0005[כאן שהתקיימה]\u0006 \u0003מצות יבום\u0004 בדרך כלשהי כאשר כנס אותה, אף שלאחר מכן נתברר שלא היה כאן יבום — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נקנוס את הצרה, שלא היתה צריכה לחשוש לדבר זה.","\u0003ו\u0004מן הצד השני \u0003אי אשמעינן הכא\u0004 \u0005[אם היה משמיע לנו\u0006 רק \u0005כאן],\u0006 ביבמה שנמצאת איילונית, היינו אומרים: דווקא כאן יש מקום לגזור \u0003משום דקא רמיא קמיה\u0004 \u0005[שהיא מוטלת לפניו]\u0006 לפני היבם, בדיוק כפי שצרתה האיילונית עומדת לפניו, והיה עליה להמתין, \u0003אבל התם דלא רמיא קמיה\u0004 \u0005[שם,\u0006 במקרה שהיתה צרת ערווה, \u0005שאינה מוטלת לפניו],\u0006 ששתיהן פטורות היו לגמרי מן היבום — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נקנוס, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה שתי ההלכות.","שנינו במשנה \u0003כתב הסופר וטעה ונתן גט לאשה ושובר לאיש\u0004, ונתן האיש לאשה שובר והיא נתנה לו את הגט, ר' אלעזר אומר: אם לאלתר יצא הגט מתחת ידי האיש ודאי שאין אלו גירושין, אבל אם יצא לאחר זמן אומרים שנתגרשה כדין, והחזירה לו את הגט.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003לאלתר, והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 \u0003לאחר זמן?\u0004 \u0003אמר רב יהודה אמר שמואל: כל זמן שיושבין ועסוקין באותו ענין\u0004 של גירושין — \u0003זהו\u0004 הנקרא \u0003לאלתר,\u0004 אם \u0003עמדו\u0004 משם — \u0003זהו\u0004 נקרא \u0003לאחר זמן.\u0004","\u0003ורב אדא בר אהבה אמר:\u0004 אם \u0003לא נישאת\u0004 — \u0003זהו לאלתר,\u0004 שהרי יכולים לתקן את הדבר ויתן גט כראוי, אם \u0003נישאת\u0004 — \u0003זהו לאחר זמן.\u0004","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדברי ר' אלעזר: \u0003לא כל הימנו\u0004 (אין זה בכוחו) של \u0003הראשון לאבד\u0004 את \u0003זכותו של\u0004 ה\u0003שני.\u0004 ומעתה \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב אדא בר אהבה\u0004 — \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003\"שני\",\u0004 שהרי מדובר פה במקרה שנישאה ויש בעל שני, \u0003אלא ל\u0004דעת \u0003שמואל מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שני\"?\u0004 הרי אם רק עמדו משם — נחשב הדבר כ\"לאחר זמן\", אף שעדיין לא נישאה, ואין כאן איפוא שני!"],["ומשיבים: כוונתו לא שהיתה נשואה כבר לשני, אלא \u0003זכות הראויה לשני,\u0004 שאינו יכול לשלול זכותו של אדם שני שירצה לשאת אותה.","\u0003כתב\u0004 גט \u0003לגרש\u0004 בו \u0003את אשתו, ונמלך\u0004 ולא נתן לה את הגט, \u0003בית שמאי אומרים:\u0004 מכל מקום \u0003פסלה מן הכהונה.\u0004 שאף שכתיבת הגט כשלעצמה אינה מוציאה אותה מרשות בעלה, מכל מקום נחשבת היא בכך כגרושה במקצת להיאסר לכהן. \u0003ובית הלל אומרים:\u0004 לא רק אם כתב גט ולא נתנו לה, אלא \u0003אף על פי שנתנו לה\u0004 אלא שהיה זה גט \u0003על תנאי, ולא נעשה\u0004 (התקיים) \u0003התנאי\u0004 ולכן לא חל הגט — \u0003לא פסלה מן הכהונה\u0004 עד שיחולו הגירושין בפועל ותיקרא גרושה לכל דבר.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנשה מדויל לשמואל\u0004 שאלה זו: \u0003ילמדנו רבינו\u0004 הלכה בענין זה: \u0003יצא עליו,\u0004 על אדם, קול (שמועה): \u0003איש פלוני כהן כתב גט לאשתו, ו\u0004אולם רואים אנו שהיא עדיין \u0003יושבת תחתיו ומשמשתו, מהו\u0004 דינה, האם יש לחשוש לקול השמועה שיצא?","\u0003שלח ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003תצא\u0004 מבעלה, \u0003והדבר צריך בדיקה\u0004 קודם לכן. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 בדיקה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהבדיקה היא \u0003דאי מבטלינן קלא\u0004 \u0005[שאם אנו מבטלים קול\u0006 שיצא\u0005]\u0006 ואומרים שכיון שלא היתה בזה עדות — אין ממש בדבר, \u0003או\u0004 שמא \u0003לא מבטלינן\u0004 \u0005[מבטלים אנו]\u0006 אלא חוששים לשמועה (ריטב\"א). ואולם מה מקום לשאלה זו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נהרדעא אתריה\u0004 \u0005[מקומו]\u0006 של \u0003שמואל היא\u0004 והיו פוסקים שם כשיטתו, \u0003ובנהרדעא לא מבטלי קלא\u0004 \u0005[אין מבטלים קול]\u0006 ובוודאי על פי שיטת שמואל הם נוהגים! \u0003אלא\u0004 מה שצריך לבדוק הוא, \u0003דאי קרו\u0004 \u0005[שאם קוראים]\u0006 אנשים \u0003לנתינה\u0004 של גט \u0003\"כתיבה\".\u0004","ושואלים: \u0003וכי קרו\u0004 \u0005[ו\u0006אף \u0005כאשר קוראים]\u0006 \u0003לנתינה כתיבה,\u0004 ואולם \u0003לכתיבה גופה\u0004 \u0005[עצמה]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא קרו\u0004 \u0005[קוראים]\u0006 \u0003לה כתיבה?\u0004 ולפיכך גם אם יימצא שקוראים לנתינה כתיבה לא נדע בבירור אם באמת נתן לאשה את הגט או שרק כתב לה גט!","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דאי מיגליא מילתא\u0004 \u0005[שאם מתגלה,\u0006 מתברר, \u0005הדבר]\u0006 \u0003דקרו\u0004 \u0005[שקוראים]\u0006 \u0003לנתינה כתיבה, דלמא\u0004 \u0005[שמא]\u0006 ש\u0003נתן\u0004 גט \u0003קאמרי\u0004 \u0005[אמרו],\u0006 וחוששים לקול זה, שמא היא גרושה ממש.","ועל דברי שמואל שתצא מבעלה תוהים: \u0003תצא?! והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב אשי: כל קלא\u0004 \u0005[קול]\u0006 שיוצא \u0003דבתר\u0004 \u0005[לאחר]\u0006 \u0003נישואין לא חיישינן ליה\u0004 \u0005[אין אנו חוששים לו]!\u0006 שאף שחוששים לקול שיצא על אשה שנתקדשה ואין מניחים לה להינשא לאחר אלא אחרי שתקבל גט מן הראשון — לא אמרו זאת אלא כשלא נישאה עדיין, אבל לאחר שנישאה — אין חוששים לקול, ולא תצא מבעלה. ואף כאן, אשה זו שיצא עליה קול שנתגרשה יושבת תחת בעלה!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תצא\"\u0004 שאמר שמואל — הכוונה היא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003תצא משני,\u0004 שאם ימות בעלה הראשון והיא תינשא לכהן אחר, הרי בגלל הקול שיצא על הגט שנתן לה בעלה הראשון — תצא ממנו.","ומקשים: \u0003אם כן אתה מוציא לעז על בניו של ראשון!\u0004 שאם יוצאת מן השני משום גרושה, אם כן אף בעלה הראשון היה עמה לאחר גירושיה, ובניה ממנו — חללים הם! ומשיבים: \u0003כיון\u0004 שמן הבעל ה\u0003שני הוא דמפקינן לה\u0004 \u0005[שאנו מוציאים אותה]\u0006 \u0003ומראשון לא מפקינן לה\u0004 \u0005[אין אנו מוציאים אותה],\u0006 אם כן \u0003אתי למימר\u0004 \u0005[יבואו לומר]\u0006 ולהסביר שכך היה המעשה: \u0003סמוך למיתה גרשה\u0004 בעלה הראשון, ובניה ממנו כשרים הם, אבל אינה רשאית להינשא לכהן אחר. ואין חשש להוצאת לעז על בניה שמן הראשון.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יהודה בר אילעי: בא וראה שלא כדורות הראשונים דורות האחרונים,\u0004 שהיו הראשונים מדקדקים יותר בטהרת יוחסין.","ומסבירים: \u0003דורות הראשונים\u0004 הכוונה היא — \u0003בית שמאי,\u0004 שכל כך הקפידו בקדושת כהונה עד שאמרו במשנתנו שאפילו בכתיבת גט בלבד אשת כהן נאסרת עליו. ואילו \u0003דורות האחרונים\u0004 — \u0003ר' דוסא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנוינו\u0006 בברייתא\u0005]:\u0006 אשת כהן שהיתה \u0003שבוייה, אוכלת בתרומה\u0004 ואין חוששים לה שמא נאנסה בהיותה בשבי ועל ידי כך נאסרה לבעלה הראשון ונפסלה מאכילת תרומה, אלו \u0003דברי ר' דוסא.\u0004","וכהסבר לדבר \u0003אמר ר' דוסא: וכי מה\u0004 כבר \u0003עשה לה ערבי זה\u0004 ששבה אותה, וכי \u0003מפני שמיעך לה בין דדיה\u0004 (שדיה) בדרך פריצות \u0003פסלה\u0004 בכך \u0003מן הכהונה?!\u0004 וכל זמן שלא התברר בפירוש שנבעלה ממש על ידי שוביה — אין לאסור אותה בתרומה. הרי שדורות אחרונים מקילים הרבה בקדושת כהונה.","\u0003ו\u0004כיוצא בזה עוד \u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יהודה בר אילעי: בא וראה שלא כדורות הראשונים דורות האחרונים;\u0004 \u0003דורות הראשונים\u0004 היו \u0003מכניסין פירותיהן\u0004 מן השדה לבית בכוונה \u0003דרך טרקסמון\u0004 (פתח חשוב) \u0003כדי לחייבן\u0004 בכך \u0003במעשר,\u0004 ואילו \u0003דורות האחרונים\u0004 \u0003מכניסים פירותיהם\u0004 מן השדה לבית \u0003דרך גגות ודרך קרפיפות\u0004 (חצר אחורית) \u0003כדי לפוטרן\u0004 בכך \u0003מ\u0004\u0003ן המעשר.\u0004","ומסבירים את הדברים על פי מה ש\u0003אמר ר' ינאי: אין הטבל מתחייב במעשר עד שיראה פני הבית, שנאמר\u0004 בווידוי מעשרות: \u0003\"בערתי הקדש מן הבית\"\u0004 (דברים כו, יג) וכל עוד אין הטבל מוכנס לבית בכניסה הראשית שבחזית הבית (\"פני הבית\") מותר לאכול ממנו בדרך ארעי בלא להפריש מעשר, ומשום כך היו מכניסים את המעשר שלא דרך הפתח כדי להיפטר לפי שעה מן המעשר.","\u0003ור' יוחנן אמר\u0004 לגופו של דבר: \u0003אפילו חצר קובעת\u0004 לענין חיוב המעשר, שהימצאות הטבל בחצר כבר מחייבת להפריש ממנו מעשר לפני כל אכילה, \u0003שנאמר: \"ואכלו בשעריך ושבעו\"\u0004 (דברים כו יב) משמע שאף אכילה שלא בבית אלא בחצר (\"בשעריך\") יש בה חיוב מעשר.","\u0003המגרש את אשתו ו\u0004אחר כך \u0003לנה עמו\u0004 בלילה \u0003בפונדקי\u0004 (פונדק, מלון), \u0003בית שמאי אומרים: אינה צריכה הימנו גט שני, ובית הלל אומרים: צריכה הימנו גט שני\u0004 שמא בא עליה בפונדק, וחזר וקידשה בביאה זו.","\u0003אימתי\u0004 אמרו דין זה — \u0003בזמן שנתגרשה מן הנשואין. ו\u0004אולם \u0003מודים\u0004 גם בית הלל \u0003בנתגרשה מן האירוסין\u0004 — \u0003שאינה צריכה הימנו גט שני, מפני שאין לבו גס\u0004 (רגיל) \u0003בה\u0004 ואין לחשוש שבא עליה, למרות שלנו יחד באותו פונדק.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 בית שמאי ובית הלל היא \u0003דווקא\u0004 \u0003ב\u0004מקרה \u0003שראוה שנבעלה,\u0004"],["ש\u0003בית\u0004 \u0003שמאי סברי\u0004 \u0005[סבורים]:\u0006 פעמים \u0003אדם עושה בעילתו בעילת זנות,\u0004 ולכן אף שראוה שנבעלה אין אומרים שבעל אותה לשם קידושין שהרי זה עתה נתגרשו, אלא אומרים אנו שבא עליה לשם זנות בלבד. ולכן אינו צריך לתת לה גט שני.","\u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003אין אדם עושה בעילתו בעילת זנות,\u0004 ובוודאי לשם קידושין בעל, וצריך לחזור ולתת לה גט. \u0003אבל\u0004 אם \u0003לא ראוה שנבעלה,\u0004 אף שלנה עמו בפונדק — \u0003דברי הכל אינה צריכה הימנו גט שני,\u0004 שאין אנו חוששים שנבעלה.","על העמדה זאת של המשנה מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ומודים\u0004 בית הלל \u0003בנתגרשה מן האירוסין\u0004 — \u0003שאינה צריכה הימנו גט שני,\u0004 לפי \u0003שאין לבו גס בה. ואי\u0004 \u0005[ואם]\u0006 מדובר במשנה \u0003בשראוה שנבעלה, מה לי מן האירוסין ומה לי מן הנשואין?\u0004 הרי ראוה שנבעלה!","\u0003אלא\u0004 יש לומר כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 באמת מדברת \u0003בשלא ראוה שנבעלה, ור' יוחנן\u0004 ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה]\u0006 אמר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו בית שמאי ובית הלל על\u0004 אשה זו \u0003שלא ראוה שנבעלה,\u0004 שהכל מודים \u0003שאינה צריכה הימנו גט שני,\u0004","\u0003על מה נחלקו? על שראוה שנבעלה, שבית שמאי\u0004 אומרים: \u0003אדם עושה בעילתו בעילת זנות, ובית הלל אומרים:\u0004 \u0003אין אדם עושה בעילתו בעילת זנות.\u0004 ור' שמעון בן אלעזר חולק על משנתנו.","ושואלים: \u0003ומתניתין דאוקימנא\u0004 \u0005[ומשנתנו שהעמדנו אותה]\u0006 \u0003ב\u0004מקרה ש\u0003לא ראוה שנבעלה, במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 ומשיבים: במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדי יחוד\u0004 שמעידים שנתייחדו בחדר אחד, \u0003וליכא\u0004 \u0005[ואין]\u0006 \u0003עדי ביאה,\u0004","\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003הן הן עדי יחוד והן הן עדי ביאה,\u0004 אלא אף שהעדים מעידים שהתייחדו אין זאת אומרת שבא עליה. \u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003הן הן עדי יחוד והן הן עדי ביאה\u0004 ומניחים שבוודאי בא עליה, ולכן צריכה ממנו גט שני.","\u0003ומודים\u0004 בית הלל \u0003בנתגרשה מן האירוסין\u0004 — \u0003שאינה צריכה הימנו גט שני,\u0004 אף אם נתייחד עימה, שכיון ש\u0003אין לבו גס בה.\u0004 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003הן הן עדי ביאה.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שאין בית הלל מצריכים גט שני אלא במקרה שראוה שנבעלה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: הלכה\u0004 בכל מקום \u0003כסתם משנה, ואוקימנא למתניתין\u0004 \u0005[והעמדנו את משנתנו]\u0006 שמדובר בה \u0003בשלא ראוה שנבעלה,\u0004 וכיצד פוסק ר' יוחנן שלא כמשנה! ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[אמוראים הם\u0006 שנחלקו בדבר\u0005]\u0006 \u0003ואליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003ר' יוחנן,\u0004 שיש מהם הסבורים שאין ר' יוחנן פוסק בכל מקום כסתם משנה.","אשה ש\u0003כנסה\u0004 ונשאה בעלה השני על סמך גירושיה מבעלה הראשון \u0003בגט קרח,\u0004 שהוא גט מקושר שאין בו עדים די הצורך, וכפי שיבואר להלן — \u0003תצא מזה ומזה\u0004 בין מבעל ראשון בין משני שנישאה לו על סמך גט זה, \u0003וכל הדרכים האלו\u0004 של קנסות שקונסים אשת איש שנישאה לאחר, שנימנו למעלה, קיימים \u0003בה.\u0004","\u0003גט קרח\u0004 — \u0003הכל משלימין עליו,\u0004 כלומר, כל אדם, אפילו פסול לעדות, רשאי לחתום עליו כתוספת לעדים העיקריים על מנת שלא יישאר קרח, אלו \u0003דברי בן ננס. ר' עקיבא אומר:\u0004 לא הכל רשאים ו\u0003אין\u0004 פסולי עדות \u0003משלימין עליו אלא\u0004 אם כן היו אלה \u0003קרובים, הראויין\u0004 (כשרים) \u0003להעיד במקום אחר.\u0004 שהתיר להשלים בעדים הפסולים רק מפני קירבתם, אבל מכל מקום צריכים הם להיות אנשים כשרים הראויים להעיד.","\u0003ואיזהו גט קרח?\u0004 — שהיו עושים לעיתים \"גט מקושר\", שהוא גט (או שטר אחר) שמקפלים אותו ותופרים כל קפל, ועדים, מרובים יותר על שני העדים הנצרכים לשטר, חותמים על כל קשר. וגט קרח הוא \u0003כל שקשריו מרובין מעדיו,\u0004 שיש בו חלקים קשורים שאין עליהם חתימות עדים.","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003גט קרח,\u0004 מדוע נפסל גט זה, שהרי יש בו די עדים המעידים על אמיתותו! ומשיבים: \u0003גזירה משום\u0004 מי שאמר \u0003\"כולכם\u0004 חתמו \u0003\"\u0004ואז אין הגט כשר אלא אם כן חתמו כולם. ומי שעשה גט מקושר מן הסתם רוצה שיחתמו על כל קשר וקשר שבו, ויש לחשוש שמא ציווה \"כולכם חתמו\", וכיון שלא עשו כן הרי זה כאילו לא התקיים התנאי.","שנינו במשנה שבן ננס סבור כי \u0003גט קרח\u0004 — \u0003הכל משלימין עליו\u0004 ור' עקיבא מכשיר עדים שפסולים מחמת קירבה בלבד.","ושואלים: \u0003ור' עקיבא, עבד\u0004 שפסול \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 הכשיר בו, וכפי שמפורש להלן? ומשיבים: מחשש \u0003דאתו למימר\u0004 \u0005[שיבואו לומר]\u0006 שכיון שעשאוהו עד הרי הוא \u0003כשר לעדות\u0004 בכל מקום, ויש לחשוש שישתמשו בו כעד של ממש במקום אחר. ומקשים: אם כן, \u0003קרוב נמי אתו למימר\u0004 \u0005[גם כן יבואו לומר]\u0006 שהוא \u0003כשר לעדות\u0004 לקרובו גם במקום בו נצרכת עדות של ממש!","אלא יש להסביר באופן אחר: \u0003עבד היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שפסול — \u0003דדלמא אתו לאסוקיה\u0004 \u0005[שמא יבואו להעלות אותו]\u0006 \u0003ליוחסין,\u0004 שיאמרו: כיון שראו שחתם על גט, מן הסתם אדם מישראל הוא.","ושואלים: אם זו היא סיבת הפסול, אם כן \u0003גזלן דבר\u0004 \u0005[שבן]\u0006 \u0003יוחסין הוא\u0004 שלענין יוחסין אין בו פסול \u0003ליתכשר\u0004 \u0005[שיהיה כשר]\u0006 להשלים בו חתימות של גט מקושר, גם לדברי ר' עקיבא! \u0003אלמה תנן\u0004 \u0005[ומפני מה שנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' עקיבא אומר: אין משלימין עליו אלא קרובים הראויין להעיד במקום אחר,\u0004 ונדייק מכאן: \u0003קרוב\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003גזלן\u0004 — \u0003לא!\u0004","\u0003אלא, עבד היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שפסול — משום \u0003דאתו למימר\u0004 \u0005[שיבואו לומר]:\u0006 \u0003שחרורי שחרריה\u0004 \u0005[שיחרר אותו]\u0006 וחתם משום שהוא עתה כאחד מישראל. ושואלים: אם זו היא סיבת הפסול, אם כן \u0003גזלן נמי אתו למימר\u0004 \u0005[גם כן יבואו לומר]\u0006 כי \u0003תשובה עבד\u0004 \u0005[עשה]\u0006 ויכשירו אותו להעיד, ולכן פוסל ר' עקיבא אותם גם כאן. אבל \u0003קרוב מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מה יש לחשוש בו? ומשיבים: \u0003קרוב כולי עלמא ידעי\u0004 \u0005[הכל יודעים]\u0006 ש\u0003קרוב הוא\u0004 ואין לחשוש שמא יכשירוהו להעיד לקרוביו.","\u0003אמר ר' זירא אמר רבה בר שאילתא אמר רב המנונא סבא\u0004 \u0005[הזקן]\u0006 \u0003אמר רב אדא בר אהבה: גט קרח\u0004 שהיו קשריו מרובים מעדיו, הוא כגון שהיו \u0003קשריו שבעה ועדיו ששה\u0004 או קשריו \u0003ששה ועדיו חמשה,\u0004 או קשריו \u0003חמשה ועדיו ארבעה,\u0004 או קשריו \u0003ארבעה ועדיו שלשה\u0004 — \u0003עד כאן,\u0004 כלומר, במקרים כגון אלו, \u0003מחלוקת בן ננס ור' עקיבא.\u0004 \u0003אבל\u0004 אם היו \u0003קשריו שלשה ועדיו שנים\u0004 — \u0003דברי הכל\u0004 וגם בן ננס מודה ש\u0003אין משלימים עליו אלא קרוב\u0004 ולא פסול גמור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרבה בר שאילתא: מכדי\u0004 \u0005[הלא]\u0006 \u0003כל שלשה\u0004 עדים \u0003במקושר כשנים ב\u0004גט \u0003פשוט דמי\u0004 \u0005[נחשבים],\u0006 שאמרו חכמים שבגט מקושר צריך לפחות שלושה עדים, \u0003מה התם\u0004 \u0005[שם]\u0006 בגט פשוט \u0003קרוב לא\u0004 יעיד כאחד משני העדים, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003קרוב לא\u0004 יעיד כחלק מן העדות העיקרית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר שאילתא: \u0003אף לדידי קשיא\u0004 \u0005[לי היתה קשה]\u0006 \u0003לי\u0004 שאלה זו \u0003ושאילתיה\u0004 \u0005[ושאלתי אותה\u0006 שאלה\u0005]\u0006 \u0003לרב המנונא, ורב המנונא\u0004 שאל אותה \u0003לרב אדא בר אהבה\u0004 שהוא בעל שמועה זו, \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנח לשלשה במקושר, דלאו דאורייתא\u0004 \u0005[שאינו מן התורה],\u0006 שהדין שצריך שיחתמו לפחות שלושה עדים על גט מקושר אינו מן התורה כחתימת שני עדים על גט אחר, משום כך אין מקפידים אם העד השלישי אינו עד כשר לגמרי.","ומעירים \u0003תניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטת רב אדא בר אהבה: \u0003גט קרח\u0004 — \u0003קשריו שבעה ועדיו ששה, ששה ועדיו חמשה, חמשה ועדיו ארבעה, ארבעה ועדיו שלשה\u0004 — \u0003עד כאן מחלוקת בן ננס ור' עקיבא.\u0004","\u0003השלים עליו עבד\u0004 בחתימה נוספת ונישאה האשה לאחר על סמך גט זה, \u0003בן ננס אומר: הולד\u0004 מן הבעל השני \u0003כשר, ור' עקיבא אומר: הולד ממזר. אבל קשריו\u0004 אם היו \u0003שלשה ועדיו שנים\u0004 — \u0003דברי הכל אין משלימין עליו אלא קרוב.\u0004","\u0003רב יוסף מתני\u0004 \u0005[היה שונה\u0006 כאן\u0005]\u0006 במקום \"אין משלימים עליו אלא קרוב\", ש\u0003\"\u0004אין משלימים עליו אלא \u0003כשר\".\u0004 ומקשים \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא במפורש\u0005]:\u0006 \u0003קרוב! אמר רב פפא, תני\u0004 \u0005[שנה]\u0006 ותקן שם: \u0003כשר.\u0004","\u0003אמר ר' יוחנן: לא הוכשרו בו\u0004 בגט מקושר להשלים חתימות כמספר הקשרים \u0003אלא עד אחד קרוב בלבד, אבל תרי\u0004 \u0005[שניים]\u0006 \u0003לא,\u0004 ומדוע? \u0003דלמא אתי לקיומי בתרי\u0004 \u0005[שמא יבואו לקיים בשני]\u0006 עדים \u0003קרובים וחד\u0004 \u0005[ואחד]\u0006 \u0003כשר,\u0004 שאולי יהא פקפוק על גט זה, ויצטרכו לקיים את השטר, ובית הדין אינם יודעים מי הם העדים, ויאמתו חתימת שניים מן הקרובים ועד אחר שהיה כשר, ונמצא שקיימו את הגט על פי עדים פסולים. אבל אם היה בו רק עד קרוב אחד, כיון שמקיימים אותו על פי שלושה — יהיו שניים מהם לפחות כשרים.","\u0003אמר רב אשי: מתניתא נמי דיקא\u0004 \u0005[הברייתא גם כן מדוייקת\u0006 כשיטה זו\u0005],\u0006"],["\u0003דקא מדלג ותני חד חד\u0004 \u0005[שהוא מדלג ושונה אחד אחד],\u0006 כלומר, שבעה קשרים וששה עדים וכיוצא בזה, ולא מזכיר מקרה של שניים חסרים (כגון שבעה קשרים וחמשה עדים) משמע שכל המחלוקת בין ר' עקיבא ובן עזאי היא רק על חתימתו של עד פסול אחד. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי קרוב\u0004 \u0005[קרוב זה]\u0006 שהכשירו בגט מקושר \u0003חתים\u0004 \u0005[חותם]\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 \u0003בין בתחילה,\u0004 בראש החותמים, \u0003בין באמצע בין בסוף.\u0004","\u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיחים זאת — \u0003מדלא\u0004 \u0005[ממה שלא]\u0006 \u0003קבע ליה\u0004 \u0005[לו]\u0006 \u0003מקום\u0004 היכן צריך העד הפסול לחתום. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 גם כן: \u0003מכל תלתא\u0004 \u0005[שלושה]\u0006 עדים החתומים על גט מקושר \u0003מקיימינן\u0004 \u0005[מקיימים אנו]\u0006 אותו, מאשרים את הגט על פי חתימות העדים, \u0003ולא בעינן\u0004 \u0005[ואין אנו צריכים]\u0006 שיקיימו דווקא חתימת שלושה עדים \u0003רצופין\u0004 וסמוכים זה לזה.","\u0003דאי סלקא דעתך בעינן\u0004 \u0005[שאם עולה על דעתך שאנו צריכים]\u0006 \u0003רצופין,\u0004 אם כן \u0003לקבע ליה\u0004 \u0005[יקבעו לו]\u0006 \u0003מקום להאי קרוב\u0004 \u0005[לקרוב זה]\u0006 שיחתום \u0003בתחילה או באמצע או בסוף, ולכשר ביה טובא\u0004 \u0005[ויכשירו בו אפילו\u0006 פסולים \u0005הרבה],\u0006 שהרי כל שלושה רצופים בהכרח ששנים מהם כשרים, והיו יכולים לתקן שכל שלישי יהא עד פסול. אלא ודאי אפשר להכשיר לפי חתימות שאינן רצופות, ואז יש לחשוש שמא יסמכו על שני עדים פסולים.","ולענין הלכה במחלוקת שבמשנה, מסופר \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' אמי\u0004 בגט מקושר קרח, שצריכים להשלים בו עדים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 למחתים: \u0003צא והשלים עליו\u0004 אפילו \u0003עבד מן השוק,\u0004 וכדעת בן ננס.","","\u0003המגרש את אשתו, ואמר לה\u0004 כשגירשה: \u0003הרי את מותרת\u0004 להינשא בגט זה \u0003לכל אדם אלא לפלוני\u0004 — \u0003ר' אליעזר מתיר\u0004 להינשא בגט זה, שלדעתו גט כשר הוא, \u0003וחכמים אוסרים,\u0004 וסבורים שגט כזה, שאינו מתיר את האשה לכל, ואין הקשר בינו ובין אשתו ניתק לגמרי — פסול הוא. \u0003כיצד יעשה\u0004 כדי להכשיר את הגט — \u0003יטלנו הימנה, ויחזור ויתננו לה, ויאמר לה: הרי את מותרת\u0004 בו \u0003לכל אדם.\u0004 אם \u0003כתבו\u0004 את התנאי הזה שאינה מותרת בו לכל \u0003בתוכו\u0004 של הגט, \u0003אף על פי שחזר ומחקו\u0004 — \u0003פסול,\u0004 לפי שגט זה נכתב מעיקרו בפסול.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003האי\u0004 \u0005[\u0006הביטוי \u0005הזה]\u0006 שאמר הבעל \u0003\"אלא\",\u0004 כיצד יש להבין את משמעותו המשפטית, האם \u0003\"חוץ\" הוא,\u0004 וכוונתו שמתחילה אינו מתירה לכל אדם, אלא לאנשים מסויימים בלבד, \u0003או \"על מנת\" הוא\u0004 ועצם הגט מתירה לכל אדם, אלא שהוסיף תנאי על כך, שלא תינשא לפלוני, והרי זה כשאר תנאים שמתנה עם אשתו בגט? ומתוך כך נברר מהי מחלוקת ר' אליעזר וחכמים: האם \u0003\"חוץ\" הוא\u0004 \u0003ו\u0004דווקא \u0003ב\"חוץ\" הוא דפליגי רבנן עליה\u0004 \u0005[שחלוקים חכמים עליו],\u0006 על דבריו של \u0003ר' אליעזר,\u0004 וסוברים שהגט פסול הוא, ומדוע? — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שייר לה בגט,\u0004 שלא היה זה גט כריתות גמור, שהרי לא התירה לכל, \u0003אבל\u0004 אם התנה בלשון \u0003\"על מנת\" מודו ליה\u0004 \u0005[מודים לו]\u0006 חכמים שהוא גט כשר, \u0003מידי דהוה אכל\u0004 \u0005[כמו שהוא בכל]\u0006 \u0003תנאי דעלמא\u0004 \u0005[סתם]\u0006 שיכול להתנות נתינת הגט בכל תנאי שירצה.","","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \"אלא\" שאמר \u0003\"על מנת\" הוא, ו\u0004דווקא במקרה של \u0003\"על מנת\" הוא דפליג\u0004 \u0005[שחולק]\u0006 \u0003ר' אליעזר אדרבנן\u0004 \u0005[על חכמים]\u0006 ומתיר את הגט, \u0003אבל ב\"חוץ\" מודה\u0004 אף הוא שהגט פסול, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שייר לה בגט,\u0004 שאיננו כורת ומנתק אותה לגמרי ממנו. \u0003אמר רבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה מה היא לשון \"אלא\", מברייתא זו: \u0003כל הבתים מטמאין בנגעים\u0004 (צרעת הבית) \u0003אלא של גוים. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שלשון \"אלא\" \u0003\"חוץ\" הוא\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 מתפרש המשפט, שכוונתו: כל הבתים מיטמאים חוץ מבתים של גויים, \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי משמעות המלה \"אלא\" \u0003\"על מנת\" הוא,\u0004 כיצד אם כן יתפרש משפט זה? האם תאמר: רק \u0003על מנת\u0004 ש\u0003לא מיטמו\u0004 \u0005[יטמאו]\u0006 \u0003בתי גוים הוא דמיטמו\u0004 \u0005[שנטמאים]\u0006 \u0003בתי ישראל,\u0004 ותוכל להסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם כן \u0003מיטמו\u0004 \u0005[מיטמאים]\u0006 \u0003בתי גוים לא מטמאי\u0004 \u0005[מיטמאים]\u0006 \u0003בתי ישראל?!\u0004","","\u0003ועוד\u0004 יש להקשות: \u0003בתי גוים מי מטמאי\u0004 \u0005[האם\u0006 הם \u0005מיטמאים]\u0006 כלל? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ונתתי נגע צרעת בבית ארץ אחוזתכם\"\u0004 (ויקרא יד, לד), בא לומר: \u0003ארץ אחוזתכם\u0004 שהיא שייכת לכם \u0003מטמאה בנגעים, ואין בתי גוים מטמאין בנגעים! אלא שמע מינה\u0004 שלשון \"אלא\" \u0003\"חוץ\" הוא!\u0004 ומעירים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא. ומעירים: לפי הסבר זה \u0003מתניתין\u0004 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר ר' יוסי בר' יהודה: לא נחלקו ר' אליעזר וחכמים על המגרש את אשתו, ואמר לה: \"הרי את מותרת לכל אדם חוץ מפלוני\"\u0004 — \u0003שאינה מגורשת. על מה נחלקו? על המגרש אשתו, ואמר לה: \"הרי את מותרת לכל אדם על מנת שלא תנשאי לפלוני\",\u0004",""],["\u0003שר' אליעזר מתיר\u0004 אותה \u0003לכל אדם חוץ מאותו האיש\u0004 שעליו התנה, \u0003וחכמים אוסרים\u0004 עליה להינשא, לפי שלדעתם גט זה אינו כשר.","ומבררים במה נחלקו ר' אליעזר וחכמים לדעת ר' יוסי בר' יהודה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 — תנאי זה הריהו \u0003מידי דהוה אכל\u0004 \u0005[כמו שהוא בכל]\u0006 \u0003תנאי דעלמא\u0004 \u0005[סתם],\u0006 שרשאי להתנות בהם את הגירושין והגט כשר. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? — ב\u0003כל תנאי דעלמא\u0004 \u0005[סתם]\u0006 \u0003לא שייר ליה\u0004 \u0005[אינו משייר לו]\u0006 \u0003בגט\u0004 עצמו, ואין התנאים שמתנה נוגעים לעצם הגירושין, \u0003הכא\u0004 \u0005[כאן]\u0006 התנאי \u0003שייר ליה\u0004 \u0005[משייר]\u0006 \u0003בגט\u0004 עצמו, שגירושה וניתוקה ממנו אינם שלמים, ולכן הגט פסול בתנאי שכזה.","ושואלים עוד: \u0003ומתניתין דאוקימנא\u0004 \u0005[ומשנתנו שהעמדנו]\u0006 את מובנה שאומר לה הבעל: \"הרי את מותרת לכל אדם \u0003חוץ\u0004 מפלוני\", \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 שמכשיר את הגט? והרי אין כאן כריתות!","\u0003אמר ר' ינאי משום\u0004 (בשם) \u0003זקן אחד: אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת גירושין: \u0003\"ויצאה מביתו והלכה והיתה לאיש אחר\"\u0004 (דברים כד, ב), ללמדנו ש\u0003אפילו\u0004 אם \u0003לא התירה אלא לאיש אחר\u0004 מסויים בלבד — \u0003הרי זו מגורשת. ורבנן אמרי טעמא\u0004 \u0005[וחכמים אומרים,\u0006 ביחס ל\u0005טעם]\u0006 של \u0003ר' אליעזר: האי\u0004 \u0005[זה]\u0006 שכתוב \u0003\"איש\u0004 אחר \u0003\"\u0004אין כוונתו איש אחד, אלא — \u0003לכל איש ואיש.\u0004","\u0003ור' יוחנן אמר, טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר בכהנים: \u0003\"ואשה גרושה מאישה לא יקחו\"\u0004 (ויקרא כא, ז), ללמדנו: \u0003אפילו לא נתגרשה אלא מאישה\u0004 אף שלא הותרה באותו גט לאחרים — \u0003נפסלה מן הכהונה, אלמא הוי גיטא\u0004 \u0005[מכאן שגט הוא],\u0006 וכל שכן גט שבו הותרה לכולם חוץ מאדם אחד.","ושואלים: \u0003ורבנן\u0004 \u0005וחכמים]\u0006 מה הם משיבים על כך? ומשיבים: \u0003איסור כהונה שאני\u0004 \u0005[שונה]\u0006 שאמנם לענין דיני כהונה היא נאסרת כגרושה, אבל אין גט זה נחשב כגט כשר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבא:\u0004 אם התנה תנאי כזה \u0003בקידושין,\u0004 שאמר שהיא נאסרת בקידושין אלא לכל אדם חוץ מפלוני, \u0003היאך\u0004 (איך) יהיה הדין? וצדדי השאלה: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003ל\u0004דעת \u0003ר' אליעזר, תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ומפרטים: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר,\u0004 שאפשר לומר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר הכא\u0004 \u0005[כאן]\u0006 להכשיר בגירושין כאלה, \u0003אלא משום דכתיבי קראי\u0004 \u0005[שנאמרו כתובים]\u0006 שמהם למדים (כדעת ר' ינאי או ר' יוחנן) שגט כזה נחשב לגט. \u0003אבל התם\u0004 \u0005[שם],\u0006 בקידושין, \u0003קנין מעליא בעינן\u0004 \u0005[מעולה אנחנו צריכים]\u0006 ואם משייר בקדושין ואינו אוסרה לכל אדם — אין זה קנין מעולה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש להתבסס על הגזירה השווה \u0003\"ויצאה... והיתה\"\u0004 (\"ויצאה מביתו והלכה והיתה לאיש אחר\". דברים כד, ב) ולפיה משווים דיני הגירושין לדיני הקידושין, וכשם שבגירושין תנאי כזה כשר לר' אליעזר — אף בקידושין יהיה כשר.","וכן \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה לדעת \u0003רבנן\u0004 \u0005[חכמים]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן הכא\u0004 \u0005[אמרו חכמים כאן]\u0006 ואסרו בגט זה \u0003אלא\u0004 משום \u0003דבעינן\u0004 \u0005[שאנו צריכים]\u0006 שתהא בגט \u0003כריתות,\u0004 הפסק גמור בין האיש לאשתו, \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 \u0003אבל התם\u0004 \u0005[שם],\u0006 בקידושין, \u0003קנין כל דהו\u0004 \u0005[שהוא]\u0006 מספיק. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כיון שנאמר \u0003\"ויצאה... והיתה\"\u0004 הרי מה שאינו כשר בגירושין אינו כשר גם בקידושין.","\u0003לבתר דאיבעיא ליה\u0004 \u0005[לאחר שנשאלה לו\u0006 השאלה\u0005],\u0006 \u0003הדר פשטה\u0004 \u0005[חזר\u0006 ו\u0005פתר אותה]\u0006 כך: \u0003בין לר' אליעזר בין לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיתקיים \u0003\"ויצאה... והיתה\"\u0004 וכמחלוקתם בגט כן חולקים גם בקידושין.","\u0003אמר אביי: אם תמצא לומר\u0004 כי \u0003איתא\u0004 \u0005[יש\u0006 לקבל\u0005]\u0006 להלכה את דברי \u0003ר' אבא,\u0004 ודין הקידושין כדין הגירושין, הרי לשיטת ר' אליעזר אם","\u0003בא ראובן\u0004 לאישה \u0003וקידשה חוץ משמעון\u0004 אחיו, שהתנה שקידושיו אינם אוסרים אותה על שמעון, \u0003ובא שמעון\u0004 אחיו \u0003וקידשה חוץ מראובן, ומתו שניהם\u0004 בלא בנים — הרי זו \u0003מתיבמת ללוי\u0004 אחיהם, \u0003ואין אני קורא בה \"אשת שני מתים\",\u0004 שאמרו חכמים שאשה שמת בעלה ונזקקה ליבום, ועמד אחד מאחיו וקידשה, ומת גם הוא — אסורה על האח השלישי, לפי שהתורה אמרה \"אשת המת\", ואשה זו — אשת שני מתים היא.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינה נחשבת במקרה זה אשת שני מתים? — \u0003קידושי\u0004 \u0005[קידושין]\u0006 של \u0003ראובן\u0004 אמנם \u0003אהנו\u0004 \u0005[הועילו]\u0006 וחלו בה, אבל \u0003קידושי\u0004 \u0005[קידושין]\u0006 של \u0003שמעון לא אהנו\u0004 \u0005[הועילו]\u0006 כלל, שהרי לא אסרה בקידושיו על כל אדם יותר משאסרה כבר ראובן בקידושיו.","ושואלים: \u0003ואלא אשת שני מתים היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 במקרה שדיבר עליו ר' אבא? ומשיבים: \u0003כגון שבא ראובן וקידשה חוץ משמעון, ובא שמעון וקידשה סתם, דקידושי\u0004 \u0005[שקידושין]\u0006 של \u0003ראובן אהנו למיסרא אעלמא\u0004 \u0005[הועילו לאסור אותה על הכל]\u0006 חוץ משמעון, \u0003וקידושי\u0004 \u0005[וקידושין]\u0006 של \u0003שמעון אהנו למיסרא\u0004 \u0005[הועילו לאסור אותה]\u0006 על \u0003ראובן,\u0004 וחלו איפוא הקידושין של שני האחים, ואם מתו שניהם — אסורה להתייבם לאח השלישי משום \"אשת שני מתים\".","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי:\u0004 \u0003אמר לה\u0004 לאשה שמגרש אותה \u0003\"הרי את מותרת לכל אדם חוץ מראובן ושמעון\", וחזר ואמר לה \"\u0004הרי את מותרת \u0003לראובן ושמעון\", מהו\u0004 הדין?","\u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003אסר\u0004 קודם \u0003שרא\u0004 \u0005[התיר]\u0006 עכשיו ומותרת לכל, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003אסר\u0004 קודם \u0003שרא\u0004 \u0005[התיר]\u0006 שמותרת לראובן ושמעון, \u0003ומאי דשרא\u0004 \u0005[ומה שהתיר]\u0006 \u0003אסר,\u0004 וכוונתו שאסורה לכל אדם חוץ מראובן ושמעון? \u0003אם תמצא לומר\u0004"],["רק \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003אסר שרא\u0004 \u0005[התיר]\u0006 והיא מותרת לכל, אם אמר בפעם השניה שמתירה רק \u0003לראובן, מהו\u0004 הדין? האם הכוונה היא \u0003לראובן והוא הדין לשמעון\u0004 שגם אותו הוא מתיר, \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003לראובן\u0004 — \u0003משום\u0004 ש\u0003פתח ביה\u0004 \u0005[בו]\u0006 ואסרו תחילה, וכוונתו היתה גם לשמעון, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לראובן דוקא?\u0004","\u0003ואם תמצא לומר\u0004 שאם אומר \u0003\"לראובן\"\u0004 כוונתו \u0003דוקא\u0004 לו, אם אמר \u0003\"לשמעון\" מהו?\u0004 האם הכוונה \u0003לשמעון והוא הדין לראובן, והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003\"שמעון\"\u0004 — \u0003משום דסליק מיניה\u0004 \u0005[שגמר בו]\u0006 בדבריו הראשונים \"חוץ מראובן ושמעון\", \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לשמעון דוקא?\u0004","כהמשך לשאלות אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם אמר שמותרת \u0003אף לשמעון, מהו?\u0004 האם \u0003\"אף\"\u0004 על \u0003ראובן קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005]\u0006 וכוונתו שמותרת לראובן ואף לשמעון, \u0003או דלמא \"אף\" אעלמא קאי\u0004 \u0005[על הכל עומד,\u0006 מתייחס\u0005]\u0006 שמותרת לכל אדם ואף לשמעון, אבל לא לראובן? לכל השאלות הללו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 השאלות במקומן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לאחר פטירתו של ר' אליעזר, נכנסו ארבעה זקנים\u0004 (חכמים) \u0003להשיב\u0004 (להקשות ולדחות) \u0003על דבריו, אלו הן: ר' יוסי הגלילי, ור' טרפון, ור' אלעזר בן עזריה, ור' עקיבא.\u0004","\u0003נענה ר' טרפון ואמר: הרי שהלכה זו\u0004 שהתנה עימה בעלה בגט שלא תינשא לאדם מסויים \u0003ונישאת לאחיו של זה שנאסרה עליו, ומת בלא בנים,\u0004 הרי לא תוכל האשה להתייבם לאחי המת, שהרי אסור הוא עליה מכוח תנאו של הבעל הראשון, ואם כן \u0003לא נמצא זה\u0004 הבעל הראשון שגירשה \u0003עוקר דבר מן התורה\u0004 בתנאי שהתנה בגירושיה? \u0003הא למדת\u0004 (הרי אתה למד) מכאן \u0003שאין זה כריתות\u0004 ואינה מגורשת בגט זה, שבוודאי לא אמרה תורה להתיר גירושין הגורמים לבטל מצוה שמן התורה.","\u0003נענה ר' יוסי הגלילי ואמר: היכן מצינו\u0004 שיהיה דבר אחד שהוא \u0003אסור לזה ומותר לזה? האסור\u0004 — \u0003אסור לכל, והמותר\u0004 — \u0003מותר לכל\u0004 ואשה זו, לדברי ר' אליעזר שהגט כשר, מותרת לאנשים מסויימים ואסורה לאחר! \u0003הא\u0004 \u0003למדת, שאין זה כריתות.\u0004","\u0003נענה ר' אלעזר בן עזריה ואמר:\u0004 מה ענין \u0003\"כריתות\"\u0004 האמור בתורה לגבי גט — \u0003דבר הכורת בינו לבינה\u0004 לגמרי, אבל אשה זו עדיין קשורה לבעלה משום התנאי שאסורה להינשא לאדם מסויים, \u0003הא למדת, שאין זה כריתות.\u0004","\u0003נענה ר' עקיבא ואמר: הרי שהלכה זו ונשאת לאחד מן השוק והיו לה בנים\u0004 ממנו, \u0003ונתארמלה\u0004 (נתאלמנה) מן הבעל השני \u0003או נתגרשה\u0004 ממנו, \u0003ועמדה ונישאת לזה שנאסרה עליו\u0004 על ידי בעלה הראשון, ומשום שעברה על התנאי \u0003לא נמצא גט\u0004 שנתן לה מתחילה \u0003בטל,\u0004 \u0003ו\u0004נמצא כי \u0003בניה\u0004 מבעלה השני שנישאה לו בהיתר הם בעצם \u0003ממזרים? הא למדת\u0004 \u0003שאין זה כריתות,\u0004 ובוודאי לא התירה התורה גירושין המביאים לידי מכשול.","\u0003 דבר אחר: \u0004\u0003הרי שהיה זה שנאסרה עליו כהן, ומת המגרש, לא נמצאת\u0004 אותה אשה \u0003אלמנה אצלו\u0004 (לגביו), שהרי לגביו גם לאחר גירושיה היא עדיין אשת איש ולא גרושה, \u0003וגרושה אצל כל אדם?\u0004","\u0003וקל וחומר\u0004 הוא: \u0003מה גרושה שהיא קלה,\u0004 שאסורה רק לכהנים, והאיסור הוא בלאו, \u0003אסורה\u0004 לכהן זה \u0003בשביל צד גירושין שבה,\u0004 שכיון שגירשה בעלה אסורה משום כך גם לכהן זה, אף שלגביו היא אלמנה ולא גרושה, \u0003אשת איש שהיא חמורה לא כל שכן\u0004 שתיאסר לכל אדם, אם היא נחשבת כאשת איש לגבי אדם אחד! \u0003הא למדת שאין זה כריתות,\u0004 שאינה מותרת לאף אדם בגירושין אלה.","\u0003אמר להן ר' יהושע:\u0004 אף על פי שטענותיכם טענות \u0003אין משיבין את הארי לאחר מיתה,\u0004 שלאחר מותו של חכם אין דוחים את דבריו מפני קושיה, כי יתכן שהיתה בידו תשובה לדבר אילו היה שומע הדברים בחייו.","\u0003אמר רבא: כולהו אית להו פירכא\u0004 \u0005[כולם יש להם פירכה]\u0006 שאפשר להפריך את נימוקיהם, \u0003לבר\u0004 \u0005[חוץ]\u0006 מזו שאמר \u0003ר' אלעזר בן עזריה, דלית ליה פירכא\u0004 \u0005[שאין לו פירכה].\u0006 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמר ר' יוסי: רואה אני את דברי ר' אלעזר בן עזריה\u0004 עדיפים \u0003מדברי כולן.\u0004","ועתה באים לבאר ברייתא זו לפרטיה: \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003נענה ר' טרפון ואמר: הרי שהלכה זו ונשאת לאחיו של זה שנאסרה עליו, ומת בלא בנים, לא נמצא זה\u0004 הבעל הראשון שגירשה \u0003עוקר\u0004 בתנאו \u0003דבר מ\u0004\u0003ן התורה?\u0004 ותמהים: \u0003עוקר?!\u0004 וכי \u0003איהו\u0004 \u0005[הוא]\u0006 זה ש\u0003עקר\u0004 \u0005[עוקר]?\u0006 \u0003אלא\u0004 הכוונה היא שנמצא שהבעל \u0003מתנה\u0004 תנאי \u0003שיש בו כדי\u0004 \u0003לעקור דבר מן התורה.\u0004","ואף על כך מקשים: וכי הוא \u0003מתנה?! מי קאמר\u0004 \u0005[האם אמר]\u0006 \u0003לה: לא סגי\u0004 \u0005[די]\u0006 \u0003לה\u0004 ש\u0003לא מינסבא ליה לאחוה דההוא גברא\u0004 \u0005[תינשא\u0006 אלא \u0005לאחיו של אותו אדם]\u0006 שאסר אותו עליו? ואם כן הבעל שעשה תנאי זה לא עקר דבר, אלא האשה היא שגרמה לכך, בזה שנישאה דווקא לאחיו של אותו אדם! \u0003אלא\u0004 יש לפרש: שנמצא הבעל בתנאו \u0003גורם לעקור דבר מן התורה.\u0004","ותוהים: אם רק \u0003גורם\u0004 הוא, מה בכך? \u0003אלא מעתה,\u0004 שמא תאמר גם ש\u0003בת אחיו לא ישא\u0004 אדם, \u0003שמא ימות בלא בנים, ונמצא גורם לעקור דבר מן התורה,\u0004 שהרי היא צריכה יבום, וכיון שהיבם הוא אביה (שהוא אחי בעלה) בטלה על ידי כך מצות היבום! והרי שיבחו חכמים את הנושא בת אחיו! ומעירים: אכן \u0003היינו פירכא\u0004 \u0005[זוהי הפירכה]\u0006 שאמר רבא, שיש על דברי ר' טרפון.","ועוד מבררים: \u0003ובמאי\u0004 \u0005[ובמה]\u0006 היה התנאי לפיו הקשה ר' טרפון? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ב\"חוץ\",\u0004 שאמר הבעל שמותרת לכל \"חוץ מפלוני\", הלא במקרה זה \u0003משרא שרא\u0004 \u0005[מתיר]\u0006 \u0003ר' אליעזר\u0004 לאותו פלוני לשאתה או לייבמה לאחר שנישאה לאחר!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודה ר' אליעזר במגרש את אשתו ואמר לה \"הרי את מותרת לכל אדם חוץ מפלוני\", והלכה וניסת לאחד מן השוק, ונתארמלה\u0004 (נתאלמנה) \u0003או נתגרשה\u0004 ממנו, \u0003שמותרת\u0004 עכשיו גם \u0003לזה שנאסרה עליו\u0004 מתחילה על ידי בעלה הראשון!","\u0003אלא\u0004 הכוונה היא שהתנה \u0003ב\"על מנת\"\u0004 שמגרש אותה על מנת שלא תינשא לפלוני, ותנאי זה קיים גם לאחר שנישאה לאחר, ואם לא התקיים התנאי — התבטל הגט שנתן לה בעלה הראשון.","ועוד בפירוש הברייתא, \u0003נענה ר' יוסי הגלילי ואמר: היכן מצינו אסור לזה ומותר לזה? האסור\u0004 — \u0003אסור לכל, והמותר\u0004 — \u0003מותר לכל.\u0004 ותוהים: \u0003ולא?!\u0004 וכי לא מצאנו דבר כזה? \u0003והרי תרומה וקדשים, שאסורה לזה,\u0004 לישראל, \u0003ומותרת לזה,\u0004 לכהן! ומשיבים: \u0003באיסור אשה קא אמרינן\u0004 \u0005[אנו אומרים].\u0006","ומקשים: \u0003והרי עריות!\u0004 שאשה אסורה לקרוביה ומותרת לאחרים! ומשיבים: \u0003ב\u0004דברים הבאים על ידי קשר \u0003אישות\u0004 וקשר נישואין \u0003קאמרינן\u0004 \u0005[אנו אומרים].\u0006","ומקשים: \u0003הרי אשת איש\u0004 שאסורה לכל אדם ומותרת לבעלה! ואומרים: אכן, \u0003היינו פירכא\u0004 \u0005[זוהי הפירכה]\u0006 שבדברי ר' יוסי הגלילי, שרמז לה רבא בדבריו.","ומבררים עוד: \u0003ובמאי\u0004 \u0005[ובמה]\u0006 מדובר? באיזה מקרה הקשה ר' יוסי הגלילי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתנה עמה \u0003ב\u0004לשון \u0003\"על מנת\u0004 שלא תינשא לפלוני \u0003\"\u0004— הרי אינה אסורה עליו לגמרי, ש\u0003הרי הותרה אצלו בזנות\u0004 שהרי אמר רק שלא תינשא לפלוני, אבל אם תיבעל לו בזנות — עדיין חל הגט! \u0003אלא\u0004 יש לומר שהקשה \u0003ב\u0004מקרה שאומר לה שהגט חל \u0003\"חוץ\u0004 מאדם פלוני\u0003\",\u0004 ובכך אסרה לגמרי על אותו פלוני.","עוד שנינו בברייתא, \u0003נענה ר' עקיבא ואמר: הרי שהלכה זו ונישאת לאחד מן השוק והיו לה בנים, ונתארמלה או נתגרשה\u0004 מבעלה השני, \u0003ועמדה ונשאת לזה שנאסרה עליו,\u0004 וכי \u0003לא נמצא\u0004 אז \u0003גט בטל ובניה ממזרין?\u0004","ואומרים \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה חושש לביטול התנאי — אם כן \u0003בכולה תנאי דעלמא\u0004 \u0005[בכל תנאי סתם]\u0006 שעושה אדם עם אשתו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תנסיב\u0004 \u0005[תינשא],\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא מקיימא ליה לתנאיה\u0004 \u0005[יתקיים לו התנאי]\u0006 \u0003ונמצא גט בטל ובניה ממזרין!\u0004 ואומרים: אכן, \u0003היינו פירכא\u0004 \u0005[זוהי הפירכה]\u0006 בדברי ר' עקיבא שרמז לה רבא.","ועוד שואלים: \u0003ובמאי\u0004 \u0005[ובמה\u0006 מדובר\u0005]?\u0006 באיזה מקרה הקשה ר' עקיבא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהתנה \u0003ב\u0004לשון \u0003\"חוץ\u0004 מפלוני \u0003\",\u0004 הלא \u0003משרא שרא\u0004 \u0005[מתיר]\u0006 \u0003ר' אליעזר\u0004 בזה!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודה היה ר' אליעזר במגרש את אשתו ואמר לה \"הרי את מותרת לכל אדם חוץ מפלוני\", והלכה ונשאת לאחד מן השוק ונתארמלה או נתגרשה, שמותרת לזה שנאסרה עליו! אלא\u0004 יש לומר שאסר אותה בתנאו \u0003ב\u0004לשון \u0003\"על מנת\".\u0004","ועוד בפירוש הברייתא: \u0003דבר אחר\u0004 אמר ר' עקיבא: \u0003הרי שהיה זה שנאסרה עליו כהן, ומת המגרש, לא נמצאת\u0004 שהיא \u0003אלמנה אצלו וגרושה אצל כל אדם? ו\u0004הלא \u0003קל וחומר\u0004 הוא: \u0003ומה גרושה שהיא קלה\u0004 — \u0003אסורה\u0004 לכהן \u0003משום צד גירושין שבה, אשת איש\u0004 שהיא \u0003חמורה\u0004 שכל עוד לא מת בעלה שגירשה הרי היא אשת איש לגבי אותו כהן, \u0003לא כל שכן\u0004 שאסורה לכל אדם! ולכן, אין הגט כשר.","ונברר \u0003ובמאי\u0004 \u0005[ובמה\u0006 היה התנאי\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא היה \u0003ב\u0004לשון \u0003\"על מנת\",\u0004"],["\u0003הרי גרושה\u0004 היא אף \u0003אצלו,\u0004 אצל אדם זה בזנות, שהרי לא התנה בעלה שאסורה לו אלא על ידי נישואין, אבל לגבי זנות לא התנה, ואם כן נאסרה עליו כגרושה, אף מצד גירושין שיש לה לגביו. מה שאין כן כאשר היא נחשבת אשת איש לגביו — לכל העולם הריהי מותרת לגמרי, ואין כאן \"כל שכן\"! \u0003אלא\u0004 כוונתו של ר' עקיבא להקשות \u0003ב\u0004מקרה של \u0003\"חוץ\u0004 מפלוני","\u0003\".\u0004 ושואלים: \u0003ור' עקיבא, אי\u0004 \u0005[אם]\u0006 \u0003\"חוץ\" סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שר' אליעזר אמר שהתנאי היה בלשון \"חוץ\" \u0003לותיב\u0004 \u0005[שיקשה]\u0006 אם כן מ\u0003\"חוץ\",\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 היה התנאי בלשון \u0003\"על מנת\" סבירא ליה\u0004 \u0005[סבור הוא]\u0006 אם כן \u0003לותיב\u0004 \u0005[שיקשה]\u0006 אם כן מ\u0003\"על מנת\",\u0004 ולפי מה שהסברנו קושיה ראשונה של ר' עקיבא היא על לשון \"על מנת\", וקושיה שניה על לשון \"חוץ\"!","ומשיבים: \u0003ר' עקיבא שמיע ליה דאיכא דאמר\u0004 \u0005[שמע שיש\u0006 מי \u0005שאומר]\u0006 את הדברים האלה בתנאי \"\u0003חוץ\u0004\" \u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 בתנאי של \"\u0003על מנת\u0004\", ולכן הקשה בשני המקרים, \u0003מאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 \u0003\"חוץ\"\u0004 — \u0003האי פירכא\u0004 \u0005[זוהי הפירכה],\u0006 \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 \u0003\"על מנת\"\u0004 — \u0003האי פירכא\u0004 \u0005[זוהי הפירכה].\u0006","ושואלים לגוף הדברים: הרי אמר רבא שעל כל השיטות יש פירכה, \u0003ומאי פירכא\u0004 \u0005[ומה הפירכה]\u0006 על דברי ר' עקיבא הללו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שהקושיה היא ש\u0003איסור כהונה שאני\u0004 \u0005[שונה],\u0006 ואין ללמוד ממנו לאיסור כללי כאשת איש — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003מאיסור כהונה קא מייתי ליה\u0004 \u0005[מביא,\u0006 למד, \u0005אותו],\u0006 וכפי שמביא ר' יוחנן לעיל: \"ואשה גרושה מאישה לא יקחו\" (ויקרא כא, ז) אפילו לא נתגרשה אלא מאישה!","ומשיבים: \u0003רבא, כר' ינאי משום זקן אחד קא מתני\u0004 \u0005[היה שונה],\u0006 שלא הביא לעיל ראיה מאיסורי כהונה, אלא ממה שנאמר \"ויצאה... והיתה לאיש אחר\" (דברים כד, ב) — אפילו הותרה לאיש אחד. ואם כן לשיטה זו יש להפריך את קושיית ר' עקיבא ולומר שאיסור כהונה שונה מדיני עריות.","שנינו בברייתא ש\u0003אמר להן ר' יהושע: אין משיבין את הארי לאחר מיתה.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יהושע כוותיה סבירא ליה\u0004 \u0005[כמותו,\u0006 כר' אליעזר, \u0005סבור הוא]?\u0006 \u0003והא איהו נמי מיפרך קפריך\u0004 \u0005[והרי הוא גם כן מקשה]\u0006 על ר' אליעזר!","ומשיבים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]:\u0006 \u0003לדידי נמי אית\u0004 \u0005[לי עצמי,\u0006 לשיטתי \u0005גם כן יש]\u0006 \u0003לי פירכא\u0004 \u0005[פירכה]\u0006 על ר' אליעזר, \u0003מיהו\u0004 \u0005[מכל מקום]\u0006 \u0003בין לדידי\u0004 \u0005[לי,\u0006 לשיטתי\u0005],\u0006 \u0003בין לדידכו\u0004 \u0005[לכם,\u0006 לשיטתכם\u0005]\u0006 \u0003אין משיבין את הארי לאחר מיתה.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומהי]\u0006 אותה \u0003פירכא\u0004 \u0005[פירכה]\u0006 של \u0003ר' יהושע?\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהושע:\u0004 הפסוק \"ויצאה מביתו... והיתה לאיש אחר\" (דברים כד, ב) \u0003מקיש\u0004 \u0005[משווה]\u0006 \u0003קודמי הויה שניה,\u0004 כלומר, את מצבה של האשה קודם נישואיה השניים \u0003לקודמי הויה ראשונה,\u0004 למצבה של האשה קודם נישואיה הראשונים, \u0003מה קודמי הויה ראשונה\u0004 לפני שנישאה בפעם הראשונה, מדובר \u0003דלא אגידא באיניש אחרינא\u0004 \u0005[שאינה קשורה באיש אחר],\u0006 \u0003אף קודמי הויה שניה\u0004 מדובר \u0003דלא אגידא באיניש אחרינא\u0004 \u0005[שאינה קשורה באיש אחר],\u0006 ואילו אשה זו שעל פי התנאי שבגט אינה מותרת לכל האנשים, עדיין היא קשורה בבעלה הראשון, ואם כן אינה יכולה להינשא לכל אדם.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו קודם, \u0003מודה ר' אליעזר במגרש אשתו ואמר לה \"הרי את מותרת לכל אדם חוץ מפלוני\", והלכה ונישאת לאחד מן השוק ונתארמלה או נתגרשה, שמותרת לזה שנאסרה עליו.\u0004","\u0003השיב ר' שמעון בר אלעזר תשובה לדברי ר' אליעזר: היכן מצינו שזה אוסר וזה מתיר,\u0004 שהרי בעלה הראשון אסר אותה על אדם מסויים והבעל השני בפטירתו או בגירושיו הוא שמתיר אותה לאותו אדם!","ותוהים על הקושיה: \u0003ולא?\u0004 האמנם לא מצאנו דוגמה כזו? \u0003והרי יבמה,\u0004 ש\u0003בעל אוסר,\u0004 שבגלל הבעל אסורה לכל העולם עד שתחלוץ ליבם או תתייבם, \u0003ויבם מתיר\u0004 אותה, שאם התגרשה או נתאלמנה מן היבם — מותרת לכל אדם!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 ה\u0003יבם הוא קא אסר לה\u0004 \u0005[שאוסר אותה],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004חמת ה\u0003בעל הא\u0004 \u0005[הרי]\u0006 היא \u0003שריא וקיימא\u0004 \u0005[מותרת ועומדת],\u0006 שאם לא היו לבעל אחים — היתה מותרת לכל אדם במות בעלה, אלא מפני שיש יבם הוא זה שאוסר אותה לאחרים, ומשום כך היבם גם מתיר אותה להם.","ומקשים: \u0003הרי\u0004 יש נדרים, שה\u0003נודר אוסר וחכם מתיר\u0004 לו! ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יוחנן:\u0004 \u0003אין חכם מתיר כלום אלא בחרטה,\u0004 כלומר, חכם איננו מתיר אלא כאשר הוא מוצא שהנודר התחרט, ובעצם בטל הנדר על ידי החרטה, ונמצא שלא החכם הוא זה שמתיר את הנדר.","ומקשים: \u0003הרי הפרת הבעל\u0004 שמיפר את נדרי אשתו, \u0003אשה נודרת\u0004 ואוסרת על עצמה \u0003ובעל מיפר!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 יש לומר \u0003כ\u0004פי ש\u0003אמר רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כל הנודרת\u0004 — \u0003על דעת בעלה היא נודרת,\u0004 ואם כן, האיסור מתחילתו תלוי בבעל, ולכן יכול הוא גם להתיר.","ועוד בפירוש הברייתא, \u0003נענה ר' אלעזר בן עזריה ואמר:\u0004 הלא נאמר בתורה בהגדרתו של הגט \u0003\"כריתות\"\u0004 — \u0003דבר הכורת\u0004 ומנתק כל קשר \u0003בינו לבינה, הא\u0004 \u0005[הרי]\u0006 \u0003למדת שאין\u0004 גט שכ \u0003זה,\u0004 בו משועבדת עדיין האשה לתנאי שקבע הבעל, נחשב \u0003כריתות.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלא הקשו מכאן על ר' אליעזר, \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 של \u0003\"כריתות\"\u0004 \u0003מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בה],\u0006 כיצד הם למדים אותה? ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[צריכים הם אותה לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"הרי זה גיטך על מנת שלא תשתי יין\u0004 לעולם \u0003\",\u0004 או \u0003\"על מנת\u0004 \u0003שלא תלכי לבית אביך לעולם\"\u0004 — \u0003אין זה כריתות,\u0004 שהרי היא נשארת לעולם קשורה וכבולה על ידו, ולא נותק הקשר שביניהם. אבל אם אמר לה שלא תעשה כן \u0003שלשים יום\u0004 — \u0003הרי זה כריתות.\u0004 ונמצא איפוא שהם למדים מלשון \"כריתות\" שצריך שלא תישאר עליה חובה לעולם מפני הבעל.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' אלעזר בן עזריה כיצד למד הוא דין זה? ומשיבים: \u0003מ\"כרת כריתות\" נפקא\u0004 \u0005[יוצא הדבר],\u0006 שהיה יכול לקרוא לגט \"ספר כרת\" וקרא לו \"כריתות\", ללמד שיש פה שני מיני כריתות. ושואלים: \u0003ואידך\u0004 \u0005[והאחר\u0006 חכמים\u0005]\u0006 מה הם למדים מדיוק לשון זה? ומשיבים: את דיוק הלשון \u0003\"כרת כריתות\u0004 הם \u0003\" לא דרשי\u0004 \u0005[אינם דורשים].\u0006","ובאותו ענין \u0003אמר רבא:\u0004 אם אמר לאשה \u0003\"הרי זה גיטך על מנת שלא תשתי יין כל ימי חיי\"\u0004 — \u0003אין זה כריתות,\u0004 שהרי היא נשארת קשורה בו כל ימי חייו. אבל אם אומר לה \u0003\"כל ימי חיי פלוני\"\u0004 — \u0003הרי זה כריתות.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 אם אמר לה \u0003\"חיי פלוני\"\u0004 שחל הגט משום שדבר זה אינו אוסרה לעולם, \u0003דדלמא מאית ומקיימא ליה לתנאיה\u0004 \u0005[ששמא ימות\u0006 אותו פלוני \u0005ויתקיים תנאו]\u0006 ואז תהיה חופשית לגמרי, \u0003\"חיי\" דידיה נמי\u0004 \u0005[שלו גם כן],\u0006 יש לומר: \u0003דלמא מאית ומקיימא ליה לתנאיה\u0004 \u0005[שמא ימות ויתקיים תנאו]!\u0006 ומדוע אין זה כריתות?","\u0003אלא אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 שאם אומר לה שהיא אסורה \u0003\"כל ימי חייכי\"\u0004 — \u0003אין זה כריתות,\u0004 שהרי היא קשורה בו כל חייה, \u0003\"כל ימי חיי\" או \"\u0004כל ימי \u0003חיי פלוני\"\u0004 — \u0003הרי זה כריתות,\u0004 לפי שאפשר שייבטל התנאי בחייה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם נתן הבעל לאשתו גט ואמר לה \u0003\"היום אי\u0004 \u0005[אין]\u0006 \u0003את אשתי ולמחר את אשתי\", מהו?\u0004 ומעיר: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 שאלה זו \u0003ל\u0004שיטת \u0003ר' אליעזר, תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ומבאר: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004שיטת \u0003ר' אליעזר: עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 שהגט כשר כשהגביל את יכולתה להינשא על ידי תנאו \u0003אלא\u0004 באופן כזה של תנאי \u0003דלמאן דקא שרי\u0004 \u0005[שלמי שהוא מתיר]\u0006 אותה בגירושין — \u0003קא שרי\u0004 \u0005[\u0006ו\u0005הוא מתיר]\u0006 \u0003לעולם, אבל הכא\u0004 \u0005[כאן]\u0006 \u0003לא,\u0004 שהרי אינו מתיר אותה אלא לזמן קצוב. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 וחל הגט מכל מקום.","וכן, \u0003תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005חכמים]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאין זו כריתות \u0003אלא\u0004 משום ש\u0003לא פסקה מיניה\u0004 \u0005[ניתק אותה ממנו]\u0006 \u0003לגמרי,\u0004 שהרי קבע תנאי לגבי אדם מסויים שלא תוכל להינשא לו לעולם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דפסקה\u0004 \u0005[שניתקה]\u0006 ממנו ואף אם עשה זאת לזמן מוגבל — לגמרי \u0003פסקה\u0004 \u0005[ניתקה]\u0006 והרי זה גט גמור.","ומוסיפים: \u0003בתר דבעיא הדר פשטה\u0004 \u0005[\u0006אחר \u0005ששאל\u0006 רבא את השאלה \u0005חזר, ופתרה\u0006 בעצמו\u0005]:\u0006"],["\u0003מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003בין ל\u0004שיטת \u0003ר' אליעזר בין ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003כיון דפסקה\u0004 \u0005[שניתקה]\u0006 — \u0003פסקה\u0004 \u0005[ניתקה],\u0006 שלאחר שהתירה היתר גמור ליום אחד, הרי ניתק לגמרי את הקשר ביניהם, וחל הגט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשה \u0003\"הרי זה גיטך על מנת שתנשאי לפלוני\"\u0004 — \u0003הרי זו לא תנשא, ואם נשאת\u0004 — \u0003לא תצא.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 בברייתא זו? למי הכוונה שאסורה להינשא לו? \u0003אמר רב נחמן, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003הרי זו לא תנשא לו,\u0004 לאותו אדם שהתנה עליו בעלה, וטעם הדבר — גזירה \u0003שמא יאמרו\u0004 הבריות: את \u0003נשיהן נותנין\u0004 זה לזה \u0003במתנה, ואם נשאת לאחר\u0004 — \u0003לא תצא\u0004 ממנו.","ושואלים: \u0003ומשום גזרה\u0004 \"שמא יאמרו\" \u0003לא מפקינן מיניה\u0004 \u0005[מוציאים אנו\u0006 אותה \u0005ממנו],\u0006 \u0003ושרינן\u0004 \u0005[ומתירים אנו]\u0006 בכך \u0003אשת איש לעלמא\u0004 \u0005[לכל]?!\u0006 שהרי לא קיימה את התנאי שהתנה עמה בעלה שתינשא לאדם מסויים, ואם כן היא עדיין אשת איש!","\u0003אלא אמר רב נחמן,\u0004 יש לדחות את ההסבר הראשון, ו\u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 זו כוונת הברייתא: \u0003הרי זו לא תנשא לו\u0004 לאותו אדם שעליו התנה בעלה, \u0003שמא יאמרו\u0004 הבריות שאנשים אלה \u0003נשיהם נותנין במתנה, ואם נשאת לו,\u0004 לאותו אדם — \u0003לא תצא,\u0004 ש\u0003משום גזרה\u0004 \"שמא יאמרו\" \u0003לא מפקינן\u0004 \u0005[אין אנו מוציאים]\u0006 אשה מבעלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב נחמן: מדבריך אפשר ללמוד ש\u0003לו\u0004 לאדם זה שהתנה עמה שתינשא לו \u0003הוא שלא תנשא,\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לאחר\u0004 — \u0003תנשא\u0004 לכתחילה? והרי דבר זה אינו אפשרי, \u0003והא\u0004 \u0003בעי קיומי לתנאה\u0004 \u0005[והרי צריכה לקיים את התנאי\u0006 שלה\u0005]\u0006 בגירושין, שהתנה עמה שתינשא לפלוני זה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אפשר דמינסבא\u0004 \u0005[שתינשא]\u0006 \u0003היום\u0004 לאדם אחר \u0003ומיגרשה\u0004 \u0005[ותתגרש]\u0006 ממנו \u0003למחר,\u0004 ותינשא לבסוף לאותו אדם שהתנה עמה בעלה שתינשא לו \u0003ומקיימא לתנאה\u0004 \u0005[ותקיים\u0006 על ידי כך \u0005את התנאי],\u0006 \u0003ולהך דפליגת עליה\u0004 \u0005[ול\u0006הלכה \u0005זו\u0006 \u0005שאתה חולק עליו]\u0006 על \u0003רב יהודה קמדמית ליה\u0004 \u0005[אתה מדמה אותה].\u0006 ומהי מחלוקת זו — \u0003דאתמר\u0004 \u0005[שנאמר]:\u0006 מי שאמר \u0003\"קונם\u0004 (אסור בנדר, כמו הקדש) \u0003עיני בשינה היום,\u0004 שגוזר על עצמו איסור על שינה היום, \u0003אם אישן למחר\", אמר רב יהודה: אל יישן היום שמא יישן למחר,\u0004 ונמצא שעבר על נדרו למפרע.","\u0003ורב נחמן אמר: יישן היום ואין חוששין שמא יישן למחר,\u0004 ואפשר היה לומר בדרך כוללת: אף שם יש איסור (נדר להיום) ותנאי (אם יישן מחר), שלדעת רב יהודה חל האיסור עליו כל עוד לא קיים את התנאי המתיר. ואילו רב נחמן סבור שכיון שביכולתו לקיים את התנאי מחר — אין האיסור חל מהיום. ולכאורה אף כאן אפשר לומר בדומה לכך, שיכולה האשה להינשא לאחר מפני שהיא יכולה לקיים את התנאי שהתנה עמה בעלה לאחר שתתגרש מבעל זה.","אבל \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם בדידיה קיימא\u0004 \u0005[שם,\u0006 בנדר, \u0005בו\u0006 תלוי ו\u0005עומד\u0006 הדבר\u0005]\u0006 שלא יישן למחר, \u0003דאי בעי מבריז נפשיה בסילואתא\u0004 \u0005[שאם ירצה ידקור עצמו בקוצים\u0006\u0005]\u0006 \u0003ולא נאים\u0004 \u0005[יישן],\u0006 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 וכי \u0003בדידה קיימא לאיגרושי\u0004 \u0005[\u0006\u0005בה תלוי\u0006 הדבר \u0005להתגרש]?!\u0006 והרי הגירושין תלויים ברצון הבעל שתינשא לו, ושמא לא ירצה לגרשה ולא יתקיים התנאי!","\u0003אלא אמר רבא,\u0004 כך יש להבין את הברייתא: \u0003הרי זו לא תנשא לא לו ולא לאחר, לו,\u0004 לאותו אדם שהתנה הבעל שתינשא לו \u0003לא תנשא\u0004 — \u0003שמא יאמרו \"נשותיהם נותנין במתנה\",\u0004 ו\u0003לאחר לא תנשא\u0004 — \u0003דבעיא קיומיה לתנאה\u0004 \u0005[ש\u0006היא \u0005צריכה לקיים את התנאי\u0006 שלה\u0005].\u0006","\u0003ואם נשאת לו,\u0004 לאותו אדם שהתנה הבעל שתינשא לו — \u0003לא תצא,\u0004 ש\u0003משום גזרה לא מפקינן\u0004 \u0005[אין אנו מוציאים]\u0006 אשה מבעלה, אבל אם נישאת \u0003לאחר\u0004 — \u0003תצא,\u0004 \u0003דבעיא לקיומיה לתנאה\u0004 \u0005[שהרי\u0006 היא \u0005צריכה לקיים את התנאי\u0006 שלה\u0005]\u0006 וכל עוד לא קיימה אותו — אינה יכולה להינשא לאחר.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא:\u0004 \u0003הרי זו לא תנשא לא לו ולא לאחר, ואם נשאת לו\u0004 — \u0003לא תצא,\u0004 אם נישאת \u0003לאחר\u0004 — \u0003תצא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשתו \u0003\"הרי זה גיטך על מנת שתעלי לרקיע\",\u0004 או \u0003\"על מנת שתרדי לתהום\",\u0004 או \u0003\"על מנת שתבלעי קנה של ארבע אמות\",\u0004 או \u0003\"על מנת שתביאי לי קנה בן מאה אמה\",\u0004 או \u0003\"על מנת שתעברי את הים הגדול ברגליך\"\u0004 ושאר תנאים שאי אפשר לקיים אותם — \u0003אינו גט,\u0004 כיון שאינה יכולה למלא את התנאי.","\u0003ר' יהודה בן תימא אומר: כזה גט.\u0004 כלומר, גט גמור הוא, והתנאי בטל. \u0003כלל אמר ר' יהודה בן תימא: כל תנאי שאי אפשר לו לקיימו בסופו\u0004 בכל אופן שהוא \u0003והתנה עליו מתחילתו\u0004 — \u0003אינו אלא כמפליגה בדברים,\u0004 כאומר דברים של גוזמה והפלגה שאין בהם ממש, ואין כוונתו לתנאי ממש אלא לצער אותה בלבד, \u0003וכשר\u0004 הגט, אף שלא התקיימו דבריו.","\u0003אמר רב נחמן אמר רב: הלכה כר' יהודה בן תימא. אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה במסכת בבא מציעא: \u0003כל\u0004 תנאי \u0003שאפשר לו לקיימו בסופו והתנה עליו בתחילתו\u0004 — \u0003תנאו קיים,\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 תנאי כזה ש\u0003אי אפשר\u0004 לקיימו בסופו — \u0003תנאו בטל.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם אמר לה \u0003\"הרי זה גיטיך על מנת שתאכלי בשר חזיר\", מהו\u0004 שיחול התנאי? \u0003אמר אביי: היא היא,\u0004 כלומר, גם זה הוא תנאי שאי אפשר לקיימו, שהרי אסורה בדבר מן התורה והתנאי בטל. \u0003רבא אמר: אפשר דאכלה ולקיא\u0004 \u0005[שתאכל ותלקה]\u0006 על כך, ואם כן זהו תנאי שאפשר לקיימו, אף שאסור לה לעשות זאת.","ומסבירים: \u0003ל\u0004שיטת \u0003אביי\u0004 מה שאמר ר' יהודה בן תימא בפתיחת דבריו \u0003\"כלל\"\u0004 הרי זה בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003בשר חזיר,\u0004 שאף הוא תנאי שלא ניתן לקיום. \u0003לרבא\u0004 מה שאמר \u0003\"כזה גט\",\u0004 שבא להדגיש שרק כזה ולא אחר, הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 תנאי של אכילת \u0003בשר חזיר\u0004 שאם לא קיימה אותו — אינו גט","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רבא ממה ששנינו בברייתא: אם אמר \u0003\"הרי זה גיטך על מנת שתבעלי לפלוני\",\u0004 אם \u0003נתקיים התנאי\u0004 — \u0003הרי זה גט, ואם לאו\u0004 \u0005[לא]\u0006 נתקיים \u0003התנאי —\u0004 \u0003אינו גט.\u0004 אם אמר לה \u0003\"על מנת שלא תבעלי לאבא ולאביך\"\u0004 — \u0003אין חוששין שמא נבעלה להן.\u0004","\u0003ואילו\u0004 התנאי \u0003\"על מנת שתבעלי לאבא ולאביך\"\u0004 שהיא אסורה להם מן התורה \u0003לא קתני\u0004 \u0005[שנה]\u0006 באותה ברייתא, \u0003לאביי ניחא\u0004 \u0005[נוח],\u0006 שהרי לדעתו אם התנה בדבר שאסור מן התורה לעשותו — אינו תנאי, \u0003לרבא קשיא\u0004 \u0005[קשה]!\u0006","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא:\u0004 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בשר חזיר\u0004 — \u0003אפשר דאכלה ולקיא\u0004 \u0005[שתאכל ותלקה],\u0006 וכן אם התנה שתיבעל ל\u0003פלוני\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דמשחדא ביה בממונא\u0004 \u0005[שתשחד אותו בממון]\u0006 שיבוא עליה, \u0003אלא \"אבא ואביך\" בדידה קיימא\u0004 \u0005[\u0006האם \u0005בה עצמה תלוי\u0006 הדבר\u0005]?\u0006 \u0003נהי דאיהי עבדא איסורא\u0004 \u0005[אם גם שהיא תעשה איסור]\u0006 שמפני שרוצה להינשא תחליט לעבור על דברי תורה, \u0003אבא ואביך מי עבדי איסורא\u0004 \u0005[האם יעשו איסור]?!\u0006 ובוודאי לא ישמעו לה בדבר הזה, ואם כן הריהו תנאי שאי אפשר לקיימו, ואינו אלא בגדר של הפלגת דברים בלבד.","ולפי זה \u0003לרבא, \"כלל\"\u0004 שאמר ר' יהודה בן תימא הרי זה \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003\"אבא ואביך\"\u0004 שגם תנאי זה נחשב בלתי אפשרי, ומה שאמר \u0003\"כזה\u0004 גט \u0003\"\u0004הרי זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 תנאי של אכילת \u0003בשר חזיר,\u0004 שאינו גט אם אינה מקיימת אותו."],["ואילו \u0003לאביי \"כלל\"\u0004 שאמר ר' יהודה בן תימא בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 גט שמתנה אותו בכך שתאכל \u0003בשר חזיר, \"כזה גט\"\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה בו התנה שתיבעל ל\u0003פלוני,\u0004 שאינו גט עד שתקיימו, מאחר שיכולה לקיים תנאי זה בהיתר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת: אם אמר \u0003\"הרי זה גיטך על מנת שתאכלי בשר חזיר\",\u0004 \u0003ו\u0004כן \u0003א\u0004 \u0003ם היתה זרה\u0004 (לא כהנת) והתנה \u0003\"על מנת שתאכלי בתרומה\",\u0004 \u0003ו\u0004כן \u0003אם היתה נזירה\u0004 — \u0003\"על מנת שתשתי יין\",\u0004 אם בכל אלה \u0003נתקיים התנאי\u0004 — \u0003הרי זה גט, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינו גט.\u0004 ואם כן \u0003לרבא ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי גם אם מתנה עמה שתעשה איסור — תנאי הוא, \u0003לאביי קשיא\u0004 \u0005[קשה]!\u0006","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי:\u0004 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שברייתא זו \u0003דברי הכל היא?\u0004 — אין הדבר כן, \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 החולקים על ר' יהודה בן תימא, וסבורים שאף תנאי שאי אפשר לקיימו — תנאי הוא, ורק אם נתקיים — יחול הגט.","ומקשים: מפני מה דנים אם תנאי זה ניתן לקיימו, \u0003ו\u0004הרי אף אם ניתן לקיימו \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 סיבה אחרת לבטל תנאי זה, שהרי זה \u0003מתנה על\u0004 (עוקר בתנאו) \u0003מה שכתוב בתורה הוא,\u0004 \u0003ו\u0004כלל הוא ש\u0003כל המתנה על מה שכתוב בתורה\u0004 — \u0003תנאו בטל!\u0004","כתשובה לכך \u0003אמר רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 \u0003מתנה על מה שכתוב בתורה תנאו בטל,\u0004 הרי זה \u0003כגון\u0004 שאומר לאשה שהוא נושא אותה על תנאי שלא יתן לה \u0003שארה כסותה ועונתה,\u0004 ש\u0003הוא,\u0004 המתנה, \u0003קא עקר\u0004 \u0005[עוקר]\u0006 את דברי תורה אם יקיים את התנאי, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003איהי קא עקרה\u0004 \u0005[היא עוקרת]\u0006 את דברי התורה אם תקיים את התנאי, ולא הוא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: כלום\u0004 (האם לא) \u0003קא עקרה איהי\u0004 \u0005[עוקרת היא]\u0006 \u0003אלא\u0004 כדי \u0003לקיומי לתנאי דידיה\u0004 \u0005[לקיים את התנאי שלו],\u0006 \u0003אישתכח דאיהו קא עקר\u0004 \u0005[נמצא שהוא זה שעוקר],\u0006 שהרי הוא זה שהטיל את התנאי בגט!","\u0003אלא אמר רבינא: כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 \u0003מתנה על מה שכתוב בתורה תנאו בטל,\u0004 הרי זה \u0003כגון שארה כסותה ועונתה,\u0004 ש\u0003ודאי קא עקר\u0004 \u0005[עוקר]\u0006 בכך מה שכתוב בתורה כאשר בשעת קידושין מתנה עימה שלא יעשה זאת, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003מי קאמר\u0004 \u0005[האם הוא אומר]\u0006 \u0003לה?\u0004 וכי \u0003לא סגיא\u0004 \u0005[די]\u0006 לה ש\u0003לא אכלה\u0004 \u0005[תאכל]?\u0006 הרי אין הוא מחייב אותה לאכול, ואם תרצה — ש\u0003לא תיכול\u0004 \u0005[תאכל]\u0006 \u0003ולא תיגרש\u0004 \u0005[תתגרש],\u0006 ואם כן בתנאי הזה כשלעצמו אינו עוקר את דברי התורה, ואם תרצה האשה למלא את התנאי — הרי היא מרצונה עוקרת את התורה.","שנינו במשנה: \u0003כיצד יעשה\u0004 כאשר נתן לה גט והתנה תנאי שאינה מותרת לפלוני — \u0003יטלנו הימנה\u0004 ויחזור ויתננו לה ויאמר לה \"הרי את מותרת לכל אדם\". ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כך? \u0003אמר חזקיה,\u0004 שיטת \u0003ר' שמעון בן אלעזר היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם נתן גט לאשה בלא שידעה שהוא גט, \u0003ר' שמעון בן אלעזר אומר:\u0004 אין גט זה מועיל \u0003עד שיטלנו הימנה, ויחזור ויתננו לה ויאמר לה \"הי גיטך\",\u0004 ואילו רבי סבור שאינו צריך לתת את הגט פעם נוספת, אלא די לו במה שאומר ומתקן את דבריו. ואם כן משנתנו כדעת ר' שמעון בן אלעזר היא, שצריך לחזור ולתת.","\u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבי, דילכון\u0004 \u0005[\u0006החכם \u0005שלכם],\u0006 כלומר, חכם אחר שבא גם הוא מבבל, הוא רב כהנא, \u0003אמר\u0004 בהסבר הדבר: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003הואיל וקנאתו\u0004 במקצת \u0003ליפסל בו\u0004 (על ידו) \u0003לכהונה,\u0004 שלענין זה לפחות הועיל הגט, נמצא שבמידה מסויימת חל כבר הגט, ולכן אינו יכול לתקן על ידי אמירה בלבד, אלא לכל הדעות, אף לדעת רבי, צריך שיתננו לה פעם שניה.","שנינו במשנה שאם התנה את הגט בכך שלא תינשא לאדם מסויים ו\u0003כתבו\u0004 לתנאי זה \u0003בתוכו,\u0004 אפילו חזר ומחקו — פסול הגט ולא ניתן לגרש בו עוד. \u0003אמר רב ספרא: \"כתבו בתוכו\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ולא כשאמר תנאי בעל פה.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, הלא \u0003\"כתבו בתוכו\" תנן\u0004 \u0005[שנינו]\u0006 במפורש! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שגט שכתוב בו תנאי שכזה פסול לעולם, לא נאמרו אלא בשכתב את התנאי \u0003לאחר\u0004 כתיבת \u0003התורף,\u0004 שכבר נכתב עיקרו של הגט, \u0003אבל לפני\u0004 כתיבת \u0003התורף\u0004 — \u0003אפילו\u0004 היה התנאי \u0003על פה נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול,\u0004 לפי שתנאי זה גורע את כוחו של הכתוב בגט, שמתחילה כתב את הגט מתוך כוונה שיהיה בו שיור, שלא תהא מותרת לכל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדווקא אם כתבו בתוכו ממש הוא נפסל, ואין הוא נפסל במקרה שהתנה תנאי בעל פה. ואם עתה נותן לאשה את הגט בלא תנאי, נתבטלה כוונתו הראשונה, והגט כשר.","\u0003ורבא אמר: לא שנו\u0004 שתנאי זה כשהוא כתוב בגט פוסל את הגט \u0003אלא\u0004 שכתבו \u0003לאחר\u0004 כתיבת \u0003התורף, אבל\u0004 אם כתבו \u0003לפני\u0004 כתיבת \u0003התורף\u0004 — \u0003אפילו על פה נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול.\u0004","ומעירים \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא להנהו דכתבי גיטי\u0004 \u0005[לאותם שכותבים גיטין]:\u0006 \u0003שתקו שתוקי\u0004 \u0005[השתיקו]\u0006 את ה\u0003בעל עד דכתביתו ליה לתורף דגיטא\u0004 \u0005[שאתם כותבים את התורף של הגט],\u0006 כדי שלא יאמר תנאי בגט, ויפסלנו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל התנאין פוסלין\u0004 אם נכתבו \u0003בגט,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: כל\u0004 תנאי \u0003שפוסל\u0004 אם אמרו \u0003על פה\u0004 בשעת מסירת הגט לאשה — \u0003פוסל בכתב, וכל שאינו פוסל על פה\u0004 — \u0003אינו פוסל בכתב.\u0004 ולכן, כשאומר לה שהגט חל לגבי כל העולם \u0003\"חוץ\u0004 מפלוני \u0003\"\u0004ש\u0003פוסל על פה\u0004 — \u0003פוסל\u0004 אף \u0003בכתב,\u0004 ואם התנה בלשון \u0003\"על מנת\"\u0004 שתעשה דבר מסויים, \u0003שאינו פוסל על פה\u0004 — \u0003אינו פוסל בכתב.\u0004","\u0003אמר ר' זירא: מחלוקת\u0004 זו היא כשכתב את התנאי \u0003לפני\u0004 כתיבת \u0003התורף,\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 במקום שכתב תנאי \u0003\"על מנת\" אטו\u0004 \u0005[משום]\u0006 מקרה שמתנה וכותב \u0003\"חוץ\u0004 מפלוני \u0003\", ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 כשכתב \u0003\"על מנת\" אטו\u0004 \u0005[משום]\u0006 המקרה שכתב \u0003\"חוץ\". אבל\u0004 אם כתבו \u0003לאחר התורף\u0004 —"],["\u0003דברי הכל כשר. ו\u0004לשיטת ר' זירא \u0003מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]\u0006 \u0003\"כתבו\u0004 — פסול\", \u0003ואוקימנא\u0004 \u0005[והעמדנו,\u0006 והסברנו\u0005]\u0006 שהמדובר שם בשמתנה \u0003ב\u0004לשון \u0003\"חוץ\", אבל\u0004 אם כתב בלשון \u0003\"על מנת\" — לא פסיל\u0004 \u0005[פוסל],\u0006 הרי אפשר לפרש אותה לשיטת ר' זירא, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר במשנה כשכתב את התנאי \u0003לפני\u0004 כתיבת \u0003התורף, ו\u0004הוא כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר במשנה כשכתב את התנאי \u0003לאחר\u0004 כתיבת \u0003התורף, ודברי הכל,\u0004 ואף לדעת רבי.","ואילו \u0003רבא אמר: מחלוקת\u0004 רבי וחכמים היא בכותב את התנאי \u0003לאחר\u0004 כתיבת \u0003התורף,\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003גזרינן אטו\u0004 \u0005[גוזרים אנו משום]\u0006 המקרה שכותב את התנאי \u0003לפני\u0004 כתיבת \u0003התורף, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא גזרינן אטו\u0004 \u0005[אין אנחנו גוזרים משום]\u0006 \u0003לפני התורף, אבל\u0004 אם כתב \u0003לפני התורף\u0004 — \u0003דברי הכל פסול. ו\u0004לשיטת רבא","\u0003מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]\u0006 \u0003\"כתבו\" ואוקימנא\u0004 \u0005[והעמדנו]\u0006 את התנאי \u0003ב\u0004לשון \u0003\"חוץ\", אבל\u0004 אם היה בלשון \u0003\"על מנת\" לא פסיל\u0004 \u0005[פסול],\u0006 הרי מדובר במשנה שכתבו \u0003אחר\u0004 כתיבת \u0003התורף, ורבנן\u0004 \u0005[ו\u0006שיטת \u0005חכמים]\u0006 היא.","מסופר: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' אבין קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' זירא\u0004 ברייתא זו: \u0003כתב גט על תנאי\u0004 — \u0003דברי הכל פסול.\u0004 ותמה ר' זירא: \u0003דברי הכל פסול? והא מיפלג פליגי\u0004 \u0005[והרי חולקים\u0006 בכך\u0005]!\u0006","ומתרץ ר' זירא לשיטתו: \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003לדברי הכל כשר, והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 שיהא תנאי כשר לדברי הכל — בתנאי שכתבו \u0003לאחר\u0004 כתיבת \u0003התורף.\u0004","ומקשים: כיון שמתקנים את לשון הברייתא, שמא נתקן בדרך אחרת \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003הרי זה פסול, ו\u0004שיטת \u0003רבי\u0004 היא! ודוחים: ה\u0003תנא\u0004 (חוזר המשניות) שלימד ברייתא זו, בודאי לשון \u0003\"דברי הכל\" אתנייה\u0004 \u0005[לימדו],\u0006 שלשון זו היא חלק עיקרי בברייתא ובודאי לא שכחה או החליפה, אבל מחמת שכחה \u0003כשר בפסול\u0004 עלול היה ש\u0003מיחלף ליה\u0004 \u0005[מתחלף לו],\u0006 אבל \u0003\"הרי זה\" ב\"דברי הכל\"\u0004 ברור לו ש\u0003לא מיחלף ליה\u0004 \u0005[מתחלף לו],\u0006 ולכן התיקון הזה שהצענו אינו מסתבר.","אמר לאשתו בנתינת הגט: \u0003הרי את מותרת לכל אדם אלא\u0004 (חוץ מ...) \u0003לאבא\u0004 (אבי) \u0003ולאביך, לאחי ולאחיך, לעבד ולגוי, ולכל מי שאין לה עליו\u0004 תפיסת \u0003קדושין —\u0004 הרי זה גט \u0003כשר,\u0004 שהרי ממילא אין להם קידושין בה, ונמצא שתנאו לא שייר בגט דבר.","אבל אם אמר לה: \u0003הרי את מותרת לכל אדם אלא\u0004 שלא תינשאי כשאת \u0003אלמנה לכהן גדול,\u0004 או \u0003גרושה וחלוצה לכהן הדיוט,\u0004 או \u0003ממזרת ונתינה לישראל, בת ישראל לממזר ולנתין, וכל מי שיש לה עליו\u0004 תפיסת \u0003קדושין, אפילו\u0004 שהיו אלה קידושין \u0003בעבירה\u0004 כגון המקרים שמנינו — הרי זה גט \u0003פסול,\u0004 שהרי בגלל התנאי שהתנה עימה נמצא ששייר הבעל בגט, שלא הותרה לכל מי שיכולה היתה בפועל להתקדש לו, ואין זה גט הכורתה ממנו לגמרי.","מעירים: \u0003כללא דרישא\u0004 \u0005[הכלל ש\u0006כתב \u0005בראש\u0006 המשנה\u0005]\u0006 (\"ולכל מי שאין לה עליו קידושין\") בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003שאר חייבי כריתות\u0004 (עונש כרת על ביאתם עליה) שאין קידושין תופסים בהם, \u0003כללא דסיפא\u0004 \u0005[הכלל שבסוף\u0006 המשנה\u0005]\u0006 (\"כל מי שיש לה עליו קידושין\") בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003שאר חייבי לאוין, כגון עמוני ומואבי, נתיני\u0004 \u0005[נתינים]\u0006 גבעונים, \u0003מצרי ואדומי,\u0004 שיש מהם אסורים באיסור לאו ויש מהם אסורים בעשה, אבל קידושין תופסים בהם.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם אמר לה שיכולה לקבל קידושין מכל אדם \u0003חוץ מקדושי\u0004 פלוני שהוא \u0003קטן\u0004 באותה שעה, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003השתא מיהא לאו בר\u0004 \u0005[עכשיו על כל פנים לא בן]\u0006 \u0003הויה\u0004 (קידושין) \u0003הוא,\u0004 שהרי אין הקטן יכול לקדש אשה, ולפי זה — לא אסר עליה כלום, ולא שייר בגט, \u0003או דלמא\u0004 \u0005[שמא]\u0006 הלא \u0003אתי\u0004 \u0005[יבוא]\u0006 \u0003לכלל הויה\u0004 (קידושין) לכשיגדל, ולכן הוא כאוסר עליה מי שיש בו תפיסת קדושין?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005למדתם אותה]\u0006 את התשובה לשאלה זו ממה ששנינו: \u0003קטנה מתגרשת\u0004 מבעלה גם אם התקדשה לו \u0003בקידושי אביה\u0004 (שאביה קידש אותה לאיש זה).","ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה דמיון שלם בין גירושין לקידושין, כפי שלמדים מן הגזירה השווה \u0003\"ויצאה... והיתה\"\u0004 (דברים כה, ב), והרי אין הקטנה יכולה להתקדש בעצמה עד שתגדל, ומדוע יחולו בה גירושין? \u0003אלא\u0004 ודאי צריכים לומר שכיון ש\u0003אתיא\u0004 \u0005[תבוא]\u0006 \u0003לכלל הויה\u0004 של נישואין בעתיד, הרי היא נחשבת כ\"בת הוויה\" גם עכשיו. ולפי זה \u0003הכא נמי אתיא\u0004 \u0005[כאן גם כן בא]\u0006 הקטן \u0003לכלל הויה.\u0004 ולכן אם התנה הבעל את חלות הגט בכך שלא תתקדש לאותו קטן — הגט פסול.","משפתר לו רב נחמן שאלתו לאיסור, הוסיף ושאל רבא עוד: אם אמר לה \u0003\"חוץ מן הנולדים\"\u0004 (ילדים שעתידים להיוולד), \u0003מהו?\u0004 האם נאמר \u0003השתא מיהא\u0004 \u0005[עכשיו על כל פנים]\u0006 \u0003לא איתיליד\u0004 \u0005[נולדו]\u0006 עדיין ואין ממש בתנאי על דבר שאינו קיים בעולם. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003עתידי דמתיילדי\u0004 \u0005[עתידים\u0006 הם \u0005שיוולדו]\u0006 ויש איפוא צד איסור בהם בעתיד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 שהרי שנינו במשנה שאם התנה עימה שלא תינשא \u0003לעבד ולגוי\u0004 — הגט כשר, ומעתה \u0003אם איתא\u0004 \u0005[יש]\u0006 דבר כזה שאתה מתחשב במה שיהיה בעתיד, אם כן \u0003עבד וגוי נמי עבידי דמיגיירי\u0004 \u0005[גם כן עשויים להתגייר]\u0006 ונמצא שהוא אוסר עליה מי שראוי לה בעתיד, וצריך הגט להיפסל בכך! אלא ודאי אין דנים אלא לפי ההווה.","ודוחים: אין זו ראיה שכן \u0003הנך לאו לאיגיורי קיימי\u0004 \u0005[אלה לא לגיור עומדים],\u0006 שהדבר הוא רק אפשרות לעתיד, אבל אין שום סיבה להניח שאכן כך יקרה. אבל כשמדבר בנולדים, \u0003הני לאיתילודי קיימי\u0004 \u0005[אלה להיוולד\u0006 הם \u0005עומדים]\u0006 בודאי, ואם כן אין ללמוד מן המשנה.","ועוד שאל רבא את רב נחמן: אם אמר לה \u0003\"חוץ מבעל אחותה\", מהו? השתא מיהא לא חזיא ליה\u0004 \u0005[עכשיו על כל פנים אינה ראויה לו],\u0006 שהרי הוא אסור עליה באיסור כרת מדין אחות אשתו, ואם כן הגט כשר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003זמנין\u0004 \u0005[פעמים]\u0006 ש\u0003מתה אחותה וחזיא ליה\u0004 \u0005[ו\u0006תהיה \u0005ראויה לו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 כבר \u0003תניתוה\u0004 \u0005[שניתם אותה\u0006 במשנתנו\u0005]\u0006 שאם אסרה \u0003לעבד ולגוי\u0004 אין זה פוסל, והרי \u0003עבד וגוי נמי עבידי דמיגיירי\u0004 \u0005[גם כן עשויים\u0006 הם \u0005שיתגיירו],\u0006 משמע שאין דנים אלא לפי המצב הקיים בהווה. ודוחים: אין זו ראיה גמורה, כי \u0003גירות לא שכיחא\u0004 \u0005[מצויה],\u0006 \u0003מיתה שכיחא\u0004 \u0005[מצויה].\u0006","ועוד שאל רבא: אם אמר לה שהוא מתירה לכל אדם \u0003\"חוץ מזנותיך\",\u0004 שמתירה להינשא לכל אדם אבל לא שתזנה בלא נישואין, שאם יבוא עליה אדם בדרך זנות תהא לגביו אשת איש, \u0003מהו,\u0004 האם נאמר שגט הוא? וצדדי השאלה: מצד אחד \u0003בנשואין הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר\u0004 והתירה לכל, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שייר\u0004 בגט — \u0003בביאה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: כבר \u0003תניתוה\u0004 \u0005[שניתם\u0006 אותה\u0005]\u0006 שאם מתנה את הגט בכך שלא תהא מותרת \u0003\"לאבא ולאביך\"\u0004 הגט כשר. \u0003ובמאי\u0004 \u0005[ובמה\u0006 מדובר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בנשואין,\u0004 וכי \u0003אבא ואביך בני נשואין נינהו\u0004 \u0005[הם]\u0006 לה? הרי קידושין שלה להם אינם חלים כלל. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 שאוסרם עליה \u0003בזנות, ו\u0004כשהתנא אומר שרק כשמתנה את הגט בכך שלא תזנה \u0003לאבא ולאביך\u0004 — \u0003הוא\u0004 ש\u0003לא שייר,\u0004 נסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם אסרה \u0003לאחר\u0004 בזנות — \u0003שייר.\u0004","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר במשנה \u0003בנשואין,\u0004 ש\u0003עבר\u0004 האב \u0003ואינסיב\u0004 \u0005[ונשא\u0006 אותה\u0005],\u0006 ואין לדייק מכאן לגבי זנות לאחרים.","ועוד שאל רבא: אם אמר לה שמותרת לכל אדם \u0003\"חוץ מ\u0004ביאה \u0003שלא כדרכה\", מהו?\u0004 האם נאמר: \u0003בכדרכה הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר\u0004 והתירה לכל, \u0003או דלמא\u0004 \u0005[שמא]\u0006 מאחר ש\u0003\"משכבי אשה\"\u0004 (ויקרא יח, כב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 ומלשון הכתוב למדים שביאה שלא כדרכה דינה לכל ענין כביאה כדרכה, ונמצא שאוסר את אשתו בתנאי באופן זה?","ועוד שואלים: אם אמר לה \u0003\"חוץ מהפרת נדריך\",\u0004 שלא יוכל האיש הנושא אותה להפר את נדריה, אלא בעלה הראשון הוא שיפר לה, \u0003מהו?\u0004 האם נאמר \u0003בנשואין הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר, או דלמא\u0004 \u0005[שמא]\u0006 כיון ש\u0003\"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד) \u0003כתיב\u0004 \u0005[נאמר],\u0006 נמצא שהפרת נדרים היא חלק מדיני האישות, ושייר בגט.","ועוד שואלים: אם התנה \u0003\"חוץ מתרומתיך\",\u0004 שאם תינשאי לכהן לא תוכלי לאכול בתרומה, \u0003מהו?\u0004 האם נאמר \u0003בנשואין הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר, או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"קנין כספו\u0004 הוא יאכל בו\u0003\"\u0004 (ויקרא כב, יא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 שאכילת התרומה של אשת הכהן היא מכוח היותה \"קנין כספו\", ואם אינה רשאית לאכול נמצא שאין קניינו בה קנין שלם.","ועוד שואלים: אם אמר \u0003\"חוץ מירושתיך\",\u0004 שלא יוכל בעלך השני לרשת את נכסיך, \u0003מהו?\u0004 האם נאמר \u0003בנשואין הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר, או דלמא\u0004 \u0005[שמא]\u0006 כיון ש\u0003\"לשארו... וירש אתה\"\u0004 (במדבר כז, יא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ולמדו מכאן שבעל יורש את אשתו, נמצא שירושת הבעל נובעת מקשר השארות עם אשתו, וכשאינו יורשה נפגם קשר זה.","ועוד: אם אמר לה \u0003\"חוץ מקידושיך בשטר\",\u0004 שאם יקדשה אחר בדרך זו לא יחולו הקידושין, \u0003מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 הרי \u0003אפשר דמקדש לה\u0004 \u0005[שיקדש אותה]\u0006 \u0003בכסף\u0004 או \u0003בביאה,\u0004 ואם כן לא שייר בגט, \u0003או דלמא\u0004 \u0005[שמא]\u0006 כיון שנאמר \u0003\"ויצאה... והיתה\"\u0004 (דברים כד, ב), ולמדנו מכאן כי \u0003איתקוש\u0004 \u0005[הוקשו]\u0006 \u0003הוויות להדדי\u0004 \u0005[זו לזו],\u0006 שכל דרכי הקידושין שוות זו לזו, ואם אסרה באחת מהן — כאילו אסרה בכולן.","לכל השאלות הללו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 השאלות במקומן.","\u0003גופו של גט,\u0004 כלומר, עיקרו של הגט שהוא החלק המהותי והקובע שבו, הוא מה שכתוב בו \u0003\"הרי את מותרת לכל אדם\".\u0004"],["\u0003ר' יהודה אומר:\u0004 אף זה הוא גופו של גט, מה שכתוב בו \u0003\"ודן דיהוי ליכי מינאי\u0004 \u0005[וזה שיהיה לך ממני]\u0006 \u0003ספר תירוכין\u0004 \u0005[גירושין]\u0006 \u0003ואגרת שבוקין\u0004 \u0005[עזיבה]\u0006 \u0003וגט פטורין למהך להתנסבא\u0004 \u0005[ללכת להינשא]\u0006 \u0003לכל גבר דיתצביין\u0004 \u0005[איש שתירצי]\u0006 \u0003\"\u0004וזהו \u0003גופו של גט\u0004 (שטר) \u0003שחרור\u0004 של שפחה: \u0003\"הרי את בת חורין\", \"הרי את לעצמך\".\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005],\u0006 שאם \u0003אמר לה לאשתו\u0004 שכך כתב בגט שלה \u0003\"הרי את בת חורין\"\u0004 — \u0003לא אמר ולא כלום,\u0004 שאין זו לשון גירושין, וכן אם \u0003אמר לה לשפחתו \"הרי את מותרת לכל אדם\"\u0004 — גם כן \u0003לא אמר ולא כלום,\u0004 שאין זו לשון שיחרור.","אולם אם \u0003אמר לה לאשה\u0004 בגט \u0003\"הרי את לעצמך\", מהו\u0004 הדין? האם \u0003\"\u0004הרי את לעצמך \u0003לגמרי\" קאמר\u0004 \u0005[אומר]\u0006 \u0003לה\u0004 שהיא יכולה לעשות כל דבר לעצמה, ובכלל זה להינשא לאחר, \u0003או \"\u0004הרי את לעצמך \u0003למלאכה\"\u0004 בלבד \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003לה?\u0004 שהיא יכולה לעשות מלאכה עבור עצמה, אבל אין זו לשון גירושין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003גופו של גט שחרור \"הרי את בת חורין, הרי את לעצמך\". ו\u0004מעתה \u0003מה עבדא דקני ליה גופיה\u0004 \u0005[עבד שקנוי לו גופו\u0006 לאדונו\u0005],\u0006 \u0003כי אמר ליה\u0004 \u0005[כאשר אומר לו],\u0006 כלומר, לשפחה, \u0003\"הרי את לעצמך\"\u0004 — \u0003קני גופיה\u0004 \u0005[קונה\u0006 את \u0005גופו]\u0006 לעצמו, \u0003אשה\u0004 ש\u0003לא קני\u0004 \u0005[קנוי]\u0006 לו \u0003גופה לא כל שכן\u0004 שאם אמר לה \"הרי את לעצמך\" הריהי משוחררת ממנו לגמרי?","ועוד בענין זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אם \u0003אמר לו\u0004 \u0003לעבדו\u0004 בשטר השיחרור \u0003\"אין לי עסק בך\", מהו?\u0004 האם יש בזה לשון מועילה של שיחרור?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנין לרב אשי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב חנין מחוזנאה\u0004 \u0005[ממחוזא]\u0006 \u0003לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר זה ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר עבדו לגוי יצא\u0004 העבד \u0003לחירות, וצריך גט שחרור מרבו\u0004 ה\u0003ראשון. אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — דווקא באופן \u0003שלא כתב עליו אונו\u0004 (שטר) כשמכרו, אבל אם \u0003כתב עליו אונו\u0004 — \u0003זהו שחרורו.\u0004","והסברנו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אונו\"? אמר רב ששת: דכתב ליה\u0004 \u0005[שכותב לו]\u0006 כך: \u0003\"לכשתברח ממנו,\u0004 מאותו גוי שמכרתיך לו, \u0003אין לי עסק בך\",\u0004 ולכן כשמשתחרר בדרך כלשהי מאדוניו הגוי הריהו יוצא לחירות לגמרי ודינו כישראל גמור. ומכאן משמע, שלשון \"אין לי עסק בך\" היא לשון מועילה לענין שחרור.","שנינו במשנה: גופו של גט \"הרי את מותרת לכל אדם\", \u0003ר' יהודה אומר\u0004 שגם לשון זו היא חלק מעיקרו של הגט: \u0003\"ודן דיהוי ליכי מינאי\u0004 \u0005[וזה שיהיה\u0006 \u0005לך ממני]\u0006 \u0003ספר תירוכין\u0004 \u0005[גירושין]\u0006 \u0003ואגרת שבוקין\u0004 \u0005[עזיבה]\u0006 \u0003\".\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005נחלקו]\u0006 ר' יהודה וחכמים? ומסבירים: \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003ידים,\u0004 כלומר, ביטויים בלתי מושלמים מבחינה לשונית, אף ש\u0003אין מוכיחות\u0004 בעצמן את כוונת האומר מכל מקום \u0003הויין\u0004 \u0005[הריהן]\u0006 \u0003ידים.\u0004 שחכמים סבורים שאם אמר משפט שאינו מושלם, מכל מקום כיון שהענין ברור מן ההקשר — הרי זה מספיק. \u0003ו\u0004לכן, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא כתב לה \"ודן\",\u0004 שזהו גט שמתגרשת בו, מכל מקום \u0003מוכחא מילתא דבהאי גיטא קא מגרש לה\u0004 \u0005[מוכח הדבר שבגט זה הוא מגרש אותה]\u0006 ואין צריך לפרש.","\u0003ור' יהודה סבר: ידים שאין מוכיחות לא הויין\u0004 \u0005[אינן נחשבות]\u0006 \u0003ידים, ו\u0004משום כך \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003כתב לה \"ודן\"\u0004 \u0005[וזה]\u0006 וכו', \u0003דמוכחא מילתא דבהאי גיטא קא מגרש לה\u0004 \u0005[שמוכח הדבר שבגט זה מגרש אותה],\u0006 \u0003אבל\u0004 אם \u0003לא כתב לה \"ודן\"\u0004 \u0005[וזה]\u0006 וכו', \u0003אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003בדיבורא גרשה\u0004 \u0005[בדיבור\u0006 בלבד \u0005גירש אותה],\u0006 שסבורים שעצם הגירושין הוא מה שאומר לה שמגרש אותה, \u0003ושטרא\u0004 \u0005[והשטר]\u0006 \u0003ראיה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 שכך אמר, ולא גופו של הגט.","\u0003אמר אביי: האי מאן דכתב גיטא\u0004 \u0005[זה מי שכותב גט],\u0006 \u0003לא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003\"ודין\"\u0004 ביו\"ד שיש ב\u0003משמע\u0004 לשון זה גם \u0003ודין,\u0004 כלומר, משפט ביני ובינך לגרשך, \u0003אלא\u0004 ידקדק לכתוב \u0003\"ודן\"\u0004 חסר, שיהא ברור שכוונתו ל\"וזה\".","\u0003ולא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003\"איגרת\"\u0004 ביו\"ד ש\u0003משמע\u0004 גם לשון \u0003איגרת\u0004 (גג) \u0003אלא אגרת\u0004 חסר. \u0003ולא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003\"לימהך\"\u0004 מלא, ש\u0003משמע לי מהך\u0004 \u0005[מזו].\u0006 \u0003ו\u0004ישים לב ש\u0003לא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003\"למחך\",\u0004 כאשר אין האות ה\"א כתובה בדיוק ונראית כמו חי\"ת, \u0003דמשמע כי חוכא\u0004 \u0005[שנשמע\u0006 כלשון \u0005צחוק].\u0006","וצריך לכתוב במילים \u0003\"דיתיהוייין\" \"דיתיצבייין\" תלתא תלתא יודי\"ן\u0004 \u0005[שלושה שלושה יודי\"ם],\u0006 שבאופן זה ברור שיש לקרוא במשמעות \"שתהיי, שתרצי\", ולא יכתוב בשתי יודי\"ן ש\u0003משמע\u0004 כמו \u0003תהויין ותצביין\u0004 \u0005[יהיו, ירצו]\u0006 והכוונה לנשים כל שהן. \u0003ולורכיה לוי\"ו\u0004 \u0005[ויאריך את הוא\"ו]\u0006 של \u0003\"תירוכין\" ולוי\"ו\u0004 \u0005[ואת הוא\"ו]\u0006 של \u0003\"שבוקין\"\u0004 שאם לא כן \u0003משמע תריכין ושביקין\u0004 \u0005[מגורשים ועזובים].\u0006","\u0003ו\u0004בנוסח \"וכדו פטרית ושבקית ותרוכית יתיכי\" (ועכשיו פטרתי והעזבתי וגירשתי אותך) \u0003לורכיה לוי\"ו\u0004 של \u0003\"כדו\",\u0004 שאם הוא מקצר בו נמצא \u0003דמשמע\u0004 \u0005[שמשמעו]\u0006 \u0003\"וכדי\"\u0004 \u0005[בחנם].\u0006 \u0003ולא ליכתוב\u0004 \u0005[יכתוב]\u0006 במשפט בו הוא מתירה להינשא \u0003\"לאיתנסבא\"\u0004 שמא לא יכתוב בדיוק ויעשה רווח כלשהו בין האותיות \u0003דמשמע\u0004 \u0005[שמשמעו]\u0006 \u0003לא יתנסבא\u0004 \u0005[תינשא],\u0006 \u0003אלא\u0004 יכתוב \u0003\"להתנסבא\"\u0004 (בה\"א ובלא יו\"ד), שלא יהא מקום לטעות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 לפסק ההלכה לגבי המחלוקת במשנה: האם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לכתוב \u0003\"ודן\", או לא בעינן\u0004 \u0005[צריכים אנו]\u0006 לכתוב \u0003\"ודן\"?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דאתקין\u0004 \u0005[שהתקין]\u0006 \u0003רבא בגיטי\u0004 \u0005[בגיטין]\u0006 את הנוסח: \u0003\"איך פלניא בר פלניא\u0004 \u0005[פלוני בן פלוני]\u0006 \u0003פטר ותריך ית פלוניתא אינתתיה דהות אינתתיה מן קדם דנא מיומא דנן ולעלם\u0004 \u0005[וגירש את פלונית אשתו שהיתה אשתו מלפני זה, מיום זה ולעולם],\u0006 \u0003ואילו\u0004 לשון \u0003\"ודן\" לא קאמר\u0004 \u0005[אמר].\u0006","ותוהים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003כולהו מי קאמר\u0004 \u0005[כל\u0006 הלשונות האחרים \u0005האם אמר\u0006 בנוסח זה\u0005]?\u0006 \u0003אלא בעינן\u0004 \u0005[צריכים אנו]\u0006 שיכתוב אותם, ואם כן אפשר לומר כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין \"ודן\" \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לכתוב.","ומדקדקים בהסברת לשון על הגט כמו שתיקן אותו רבא: \u0003\"מיומא דנן\"\u0004 \u0005[מיום זה]\u0006 כתוב בו כדי \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דבריו של \u0003ר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו,\u0004 ואין צורך לכתוב \"מיום זה\", ותיקן רבא שמכל מקום יכתבו נוסח זה.","ומה שתיקן רבא שצריך לכתוב \u0003\"ולעלם\"\u0004 —"]]};
